/* 令和元年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r01.committeeSessions.push(...[{"id":"r01-20191202-9","meetingId":"r01-cm12","date":"2019年12月2日","dateIso":"2019-12-02","committee":"文教委員会","time":"午前１０時００分～午後 ２時２２分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を85件抜き出しています。","topics":[{"id":"topic-01","title":"令和元年請願第１７号、品川区私立幼稚園保護者負担教育費の軽減に関する請願","agenda":"令和元年請願第１７号、品川区私立幼稚園保護者負担教育費の軽減に関する請願","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"公私間の格差の是正をしてほしいということで、毎年のように出ておりますけれども、公私の格差というものが、現状、どうなっているのか。保育費の負担のところで伺いたいと思います。","respondent":"大澤保育支援課長","answer":"公立幼稚園と私立幼稚園の保育料の差ということでご説明します。公立幼稚園の場合は、本年１０月より幼児教育無償化になりましたので、保育料は無料、ゼロ円ということになっております。","id":"exchange-001"},{"speaker":"塚本委員","kind":"確認","question":"今、ご説明で私立の入園料の補助金というものが、現在、１０万円と説明があったのでしょうか。実際、私立の入園料というのはどれぐらいが平均というか、どのぐらいの分布の状況になっているのか、お伺いしたい。これは私の認識が間違っていないかどうかの確認なのですけれども、「直接助成金」という言葉が２回ほど出てくるのです。２点、お願いいたします。","respondent":"大澤保育支援課長","answer":"区内の私立幼稚園の入園料ですが、現在、１１万円から１６万円の間で、平均で約１３万円となっております。直接助成というのは、恐らく園への助成ということと保護者への助成ということで、直接園、または保護者へ助成をしているという意味で使われていると認識しております。","id":"exchange-002"},{"speaker":"塚本委員","kind":"質問","question":"今回、１０月から幼児教育の無償化が国で実施されて、それによって、区の財政負担が国からの無償化による財源との差し引きみたいなことが起こると思うのです。どういう状況になっているのか。区としての負担が軽減している部分があれば、それがどれぐらいなのかを教えてください。","respondent":"大澤保育支援課長","answer":"９月までは、国の就園奨励費というものがございまして、そちらに対する区の負担が４分の３という大きなものでございました。無償化後は、区の負担が４分の１になりますので、それだけで考えると、区の負担が８,０００万円ほど低くなる計算になります。","id":"exchange-003"},{"speaker":"塚本委員","kind":"質問・要望","question":"陳情第５２号で、１１月１５日に園から受け入れ拒否を電話で言われた。その前に、１１月１１日に登園の拒否。保育課ですか。この辺りの経緯というのは、今のご説明と齟齬があるかなと思ったのですけれども、どういう実情だったのかというのをお知らせください。もう少し具体的な説明があれば教えていただきたいと思います。","respondent":"吉田保育施設調整担当課長","answer":"過大な要求に対しては、応えられない、応じられないということを言っておりますので、例えば、個別で対応してくれということについては、現在、転園後の園については、前園でいじめられたという子はもう既にいないわけですし、そういう状況がない中でも。","id":"exchange-004"},{"speaker":"筒井委員","kind":"質問","question":"この陳情者の方が理由に書いている暴力行為等は、実際、あったのでしょうか。それは、区としてはどういう認識なのか。","respondent":"吉田保育施設調整担当課長","answer":"ただ、その際に、誰々ちゃんに噛まれたという言われ方をしているのですけれども、実際に担任や園長が確認したところ、本当にその子かどうかはわからない。多分、噛まれただろうと思われる傷があった。園内で起こったことであれば、園長が謝罪したという形にはなっております。","id":"exchange-005"},{"speaker":"筒井委員","kind":"質問","question":"耳をちぎられそうになる、あと、目をつつかれて流血したなど、いろいろ、ある意味深刻な状況が書かれているのですけれども、医師の診断など、この陳情者の方は受けられたのですか。","respondent":"吉田保育施設調整担当課長","answer":"医師の診断書につきましては、特にその時点では何も上がってきておりません。","id":"exchange-006"},{"speaker":"高橋（し）委員","kind":"質問","question":"ご説明を伺って、陳情が４つ出ていて、現在の状況はこのような状況なのですけれども、区としては、今後、どのような対応をするのか。見込みというか、その辺りを伺いたいと思います。","respondent":"吉田保育施設調整担当課長","answer":"引き続き、保護者には園に来ていただくようにお願いする、連絡をとるとともに、精神面の不安があるのであれば、そちらは医療機関等の受診をお勧めするという形をとってまいりたいと考えています。","id":"exchange-007"},{"speaker":"横山委員","kind":"確認","question":"本日、結論を出す、でお願いします。今、いろいろと議論をお伺いしたのですけれども、結論としては不採択でお願いしたいと考えています。理由としましては、今、お話をお聞きしましたけれども、今回、個別の事例等に関しましては、行政側の確認や現場において対応していただくことが適切かなと考えております。これから詳細等も調査する必要があるのかなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"芹澤副委員長","kind":"質問・要望","question":"自民党、本日、結論を出すで、不採択でお願いします。理由として、まず、前提となる事実の段階で、区の認識と陳情者の認識が大分ずれている部分で、なかなか議論が難しい。前提条件の事実が陳情者側のほうにあったとしても、なかなかこの要望自体が、非常にハードルの高いもので実現困難と考えておりますので、不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"塚本委員","kind":"質問・要望","question":"態度としては、不採択でお願いしたいと思います。こういう特性をおもちのお子さんというのはそれぞれの園にいらっしゃって、一人ひとりの状況に応じて対応していくということが求められているのは事実ではありますけれども、今、集団保育であるということが大前提としてあって、そういった中で、これまで区としても政策として個別の特別な支援はできる範囲で進めていただいていると認識をしております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"のだて委員","kind":"意見","question":"結論を出すということで、第三者委員会の設置やネットワークカメラなど、個別のもので解決する問題ではないと思います。保育園と保護者の信頼関係なしに保育は成り立たないと思いますので、区には引き続き信頼関係を築く努力を続けてほしいと思います。ですので、不採択でお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-011"},{"speaker":"筒井委員","kind":"確認","question":"本日、結論を出すで、不採択でお願いします。要旨の中立公正性を疑われないような運用が必要だと考えておりますけれども、今回のかなり個別具体的な理由、そして、それが区の認識とずれが生じて、今、申したとおり、事実確認が客観的にできないという状況であるから、そうした理由で不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"結論を出すということで、不採択でお願いします。その仕組みの中で、保育園との課題を解決していると思います。ただ、先ほどお話がありましたが、今後に向けて、園の姿勢を理解していただくということをお聞きしたので、誠意をもって対応していくことでご理解をいただくように努力をしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"塚本委員","kind":"質問","question":"本日、結論を出す。態度としては、不採択でお願いします。理由としては、先ほども少し述べましたけれども、やはり、まず大前提として集団保育ということがあって、その上での個別のいろいろな発達の特性などに対応する。この陳情に対しては、不採択ということでお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"筒井委員","kind":"質問・要望","question":"本日、結論を出すということで、不採択でお願いします。理由は、先ほど述べましたとおり、事実の確認ができないということであります。ただ、一般論として、発達障害児と健常児との間に存在するグレーゾーンのお子さんの処遇改善、支援拡充というのは、引き続き、区としてもぜひ研究していっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"結論を出すで、不採択でお願いします。現在もきちんとされていると思うのですが、現在以上の対応ができるようにしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"塚本委員","kind":"意見","question":"本日、結論を出します。態度は、不採択でお願いいたします。理由としては、この陳情を出されている方の一事例内容をもって、区内のすべての保育所に防犯カメラを設置していくということは難しい。そこまでは至らないと思いますので、不採択でお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-017"},{"speaker":"筒井委員","kind":"質問・要望","question":"本日、結論を出すで、不採択でお願いします。理由は、先ほども述べましたとおり、要旨の理由の事実確認がとれないということであります。ただ、暴力行為防止ということは、一般論として必要でありますので、暴力行為の防止につきましては、区としては引き続きしっかりと行っていただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"結論を出すで、不採択でお願いします。カメラ設置については、先ほど、数々の状況からなかなか厳しいという区の説明がありました。園での様子を、園長をはじめ、保育士等々がきちんと把握していっていただいて、そこでさまざまなことを解決していっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"横山委員","kind":"質問","question":"自民・無所属・子ども未来、結論を出す、でお願いします。結論は、不採択でお願いいたします。今、品川区で保育の質の向上を取り組んでいただいているかと思うのですけれども、理由としては、引き続き頑張っていただいて、先ほどと同じになります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"塚本委員","kind":"意見","question":"本日、結論を出します。結論としては、不採択でお願いいたします。やはり、このいじめの実態調査というのは、就学前の児童、お子様に対しては、現実的でないというか、難しい問題だと思いますので、これは不採択でお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-021"},{"speaker":"筒井委員","kind":"質問・要望","question":"本日、結論を出すで、不採択でお願いします。理由は、先ほど来、述べているとおり、要旨の理由の事実確認がとれないということであります。ただ、一般論として、いじめの防止ということは、区としてしっかりと行っていただきたいと存じます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"結論を出すで、不採択でお願いします。理由は、前の陳情でお話ししたのですが、やはり日常の様子を園長や保育士たちが十分に把握し、その情報共有をし、問題が起きないように対応していっていただきたいということをお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"のだて委員","kind":"質問・要望","question":"説明がありましたけれども、現状では、週２.５日配置されているということで、今回の陳情については、週５日、毎日勤務できるようにということで求めているわけです。実際に、今の２.５日の配置の中で、学校図書館が開いていない日がある学校があるのか、伺いたいと思います。","respondent":"横山品川図書館長","answer":"スタッフがいない時間につきましては、学校の自主管理の中で、例えば、学校図書館担当の教諭が必ずおりますので、その教諭の管理のもとに図書委員が開いているとか、学校図書館のボランティアがいる学校で運営しているところ、さまざまなやり方がありますが。","id":"exchange-024"},{"speaker":"のだて委員","kind":"質問・要望","question":"司書はいないけれども、さまざまな学校の状況で開いているということなのですね。毎日開かないという学校はないということでいいのか、そこをお伺いさせていただきたいと思います。","respondent":"横山品川図書館長、大関教育総合支援センター長","answer":"学校図書館の運営自体は、学校長が図書館長として管理しているところなので、実態そのものを調査したことはないのですが、学校の運営の中で有効に活用するという法則のもとで運営していますので。例えば、理科の準備室などもかかっておりますし、そういうものと同じように、図書室も児童・生徒の実態に応じて、活用しない場合にはかけておいて、また、休み時間のときには図書係の児童が来て、職員室から鍵を持っていって。","id":"exchange-025"},{"speaker":"のだて委員","kind":"提案","question":"やはり学校司書がいることによって、その専門性を活かして、子どもの本を選ぶことや、自分の読みたい本がどういうものが合っているのかというところで、一人ひとり読みたい本は変わってきます。それがわからないと、合った本の提案をすることができないと思うのですけれども、その点、いかがかというところ。そういった点についても伺えればと思います。","respondent":"横山品川図書館長、大関教育総合支援センター長","answer":"先ほど、危機管理で鍵がかかっている時間をご案内しましたけれども、そういう意味では、その子に対応するために、その子のためだけに開けるような時間も学校においては設けているようなところですので。先ほど、ご紹介いたしました理科室など、さまざまな特別教室がありますので、いろいろな場所を含めまして、例えば、特別支援教室専門員が各校配置されていますから、場合によっては。","id":"exchange-026"},{"speaker":"のだて委員","kind":"質問・要望","question":"先ほど、説明の中にも、全日配置することも含めて検討するということでしたので、ぜひそれは検討していただきたいと思うのです。ぜひ配置日数の増加をお願いしたいと思うのですけれども、この間の検討状況といったところを伺えればと思います。","respondent":"横山品川図書館長","answer":"私どもも平成１７年度から８年かけて配置を完了しているような状況ですので、これからまた活用の状況を見ながら、また、学校のそれぞれの状況に合わせながら、どういう形にしたほうがボランティアや地域の方と関わりながら運営し、なおかつ。","id":"exchange-027"},{"speaker":"のだて委員","kind":"質問・要望","question":"ボランティアの方やいろいろな方と協力して、ぜひ進めていただきたいと思うのです。５年、１０年かかるというお話だったのですけれども、そうすると、子どもたちがどんどん成長してしまうので、できるだけ早く配置ができるように、ぜひ進めていただきたいと思います。利用の頻度や何の授業に使われているのかというところを伺えればと思います。","respondent":"横山品川図書館長","answer":"授業での教科利用が１,６６４時間という形にはなっておりますが、各教科、国語を中心に社会、理科、生活、音楽、保健体育、英語、市民科等、数は違いますけれども、満遍なくご利用いただいているような状況です。","id":"exchange-028"},{"speaker":"のだて委員","kind":"質問","question":"今、利用状況をご説明いただきました。そういった中で、学校の司書はどういった形で先生と協力をしてやっていらっしゃるのか、伺いたいと思います。","respondent":"横山品川図書館長","answer":"子どもたちに読み聞かせを行って、その感想を聞く。ブックトークとして、本の紹介をするなど、さまざまな形でその授業を一緒に組み立てる形で協力させていただいているところです。","id":"exchange-029"},{"speaker":"のだて委員","kind":"質問","question":"一緒に組み立てていくというお話でしたけれども、その中で、今、民間に委託されているというところで、先ほど、会議にも責任者の方が参加して、委託の制限を受けないように、というお話がありました。それで、すべてが解決するわけではないと思うのです。職員会議にも出られない。そして、業者が変わったときに、引き継ぎもできないのではないかと思うのですけれども、その点について、伺いたいと思います。","respondent":"横山品川図書館長、大関教育総合支援センター長","answer":"先ほどご案内しました月ごとの会議ですが、作業企画会議に責任者が出席しまして、相談や個別の対応を学校と一緒に考えることができます。それと同じような対応は、当然、一般的にしていただく場面はあろうかと思いますが。引き継ぎにつきましては、品川図書館が主催で事業者の運営会議というものを年に３回から４回開いておりますので、その際、事業者が変わった場合は。","id":"exchange-030"},{"speaker":"のだて委員","kind":"質問","question":"担任の先生との相談の場合に責任者が出るという話や、引き継ぎの際の事業者の運営会議をやられているということでした。今、国が学校司書を１.５校に１人配置するという交付税措置を始めたみたいなのです。２３区についても、財調がそれに準じていると思うのですけれども、そういったところで、さらに配置していけるのではないかなと思うのですが、いかがでしょうか。","respondent":"横山品川図書館長","answer":"今、２.５日ですから、これを倍にするとなると、単純に予算が倍なので、そういう意味では、事業としてもなかなかすぐに倍にするということは難しい状況もあります。金額的にも精査しながら、また、協力関係を仰ぎながら、長期的に考えることかなと考えています。","id":"exchange-031"},{"speaker":"のだて委員","kind":"質問","question":"これからの国の措置ということなのですけれども、これが行われることによって、配置の増員や日数を増やすといったことができるということでいいのでしょうか。","respondent":"横山品川図書館長","answer":"詳細が確認できてからのことになると思いますが、財政当局と調整しながら、今後のことについては、財政的にも、運営そのものについても考えて、検討しながら進めていきたいと思います。","id":"exchange-032"},{"speaker":"のだて委員","kind":"質問・要望","question":"そういったところで、ぜひ進めていただきたいと思います。最後に１点。この間、自ら学ぶアクティブラーニングといったところが重要視されておりますけれども、そういった面でも、この学校司書がいることによって、教員との協力がスムーズにいって、自ら学んでいくということがより進んでいくのではないかなと思うのですけれども、いかがでしょうか。","respondent":"大関教育総合支援センター長","answer":"専門性のある図書館スタッフの方から定期的にアドバイスをいただいて、先ほどもお話がありましたように、会議などでいろいろとご助言いただいたことを教員としてもしっかりと有効活用している。そのような状況があります。","id":"exchange-033"},{"speaker":"筒井委員","kind":"質問","question":"私は、読書というのは、いろいろな教育、学習の基礎となるもので、非常に重要なものと捉えております。先ほどのご答弁と重なるところはあるかもしれませんが、この文部科学省の計画を受けて、品川区としては、今後どのようにやられていくのでしょうか。","respondent":"横山品川図書館長","answer":"国の第四次計画を追い風として、これからより充実させたいということで、今、国のレベルよりも品川区のほうが進んでおりますので、国の方針に則りながら、品川区の計画自体もより充実させて進めていきたいと考えています。","id":"exchange-034"},{"speaker":"筒井委員","kind":"意見","question":"東京都内の公立小・中学校の学校司書配置状況を見ますと、学校司書の日数を週６日置いているのは三鷹市で、週５日置かれているのが荒川区、葛飾区、杉並区、世田谷区、港区、足立区等々、かなり多いのです。週２回になっているのは品川区、そして、新宿区、中央区、目黒区ぐらいしかないという状況であります。そうした他自治体との比較、現状を見て、どういうご認識なのかをお聞かせください。","respondent":"横山品川図書館長","answer":"他区や他市の比較で、５日間の勤務でないというところについては、ほかのところでは職員で全部補うという考え方もありますけれども、品川区のように図書館ボランティアやクラスの運営の中の図書委員に入ってもらった運営の仕方ということで。","id":"exchange-035"},{"speaker":"筒井委員","kind":"質問","question":"そうしたお考えがあるということなのですけれども、陳情者の方もおっしゃっていたのですけれども、やはり直接雇用でないと、ボランティア等いろいろな方が関わっていくような今の体制ですと、機動的な、柔軟的な取り組みができないということをおっしゃっているのです。そうしたご不満というか、問題点の指摘については、どのようなお考えなのでしょうか。","respondent":"横山品川図書館長","answer":"そちらに関しては、学校図書館の図書館長である学校長に対して、年に１回、状況調査をさせていただいているところです。","id":"exchange-036"},{"speaker":"せお委員","kind":"質問・要望","question":"先ほどのご答弁から、ボランティアの方のお話もあると思うのですけれども、コミュニティ・スクールとの関わりもあると思うのです。今現在、コミュニティ・スクールとの関わりや、その関わりが、今後、どのような見通しか。お話しいただきたいと思います。","respondent":"横山品川図書館長","answer":"コミュニティ・スクールの運営については、学校それぞれで力を尽くしていただいているところなので、状況はそれぞれで違うのですが、多くの学校で学校図書館の支援スタッフを学校の一員として、コミュニティ・スクールの一員として扱っていただいて。","id":"exchange-037"},{"speaker":"高橋（し）委員","kind":"質問","question":"もう一つは、先ほどの運営支援スタッフは区の独自財源だというお話がありました。これは、全部区の独自財源で、いわゆる都との関係では入ってきていないのかということをお尋ねします。そうすると、東京都教育委員会の考え方はどのような考え方なのでしょうか。日常的に敏速にというか、迅速にというか、さまざま連絡・調整がとれるような仕組みは、どのような形で行われているのでしょうか。","respondent":"横山品川図書館長","answer":"学校図書館の重要性につきましては、学校図書館法でも必置の施設ですので、学校でも重要な位置づけになっておりますし、授業でも欠かせない存在だと認識しています。スタッフの財源については、今のところは独自財源で、補助金を受けないような形で運営されております。","id":"exchange-038"},{"speaker":"高橋（し）委員","kind":"意見","question":"それぞれ、ありがとうあります。都の考え方で、重要と考えているというところと、もう一つは、都は、司書教諭、教員の中で資格をもった方が学校図書館の運営をするという形の位置づけにしているのかどうか。つまり、こういった学校運営スタッフを２３区がこのような形で雇用するのを前提としているのかというところです。","respondent":"横山品川図書館長","answer":"雇用や存在の形態ではなく、学校図書館を充実させるために司書教諭や学校司書が連携してあたるという観念的な計画のように承知しています。品川区においては、司書教諭については、法令設置の規定どおり配置されている状況です。","id":"exchange-039"},{"speaker":"筒井委員","kind":"質問","question":"費用の問題なのですけれども、今現在、民間委託されているということなのです。仮の話になるのですけれども、区が司書を直接雇用した場合の費用と、民間委託している今現在の費用を比較したら、かなり大幅な差があるのでしょうか。","respondent":"横山品川図書館長","answer":"直接の詳細な比較をしたことがないので、金額的に幾らというのは出ないのですが、一般的な委託だと、会社の管理費が入りますので、その分をスタッフ個人の給与を落とすような形で調整するところが多いと聞いています。","id":"exchange-040"},{"speaker":"筒井委員","kind":"質問","question":"管理費は、民間委託のほうが負担が大きいということですか。","respondent":"横山品川図書館長","answer":"一方で、直接雇用の場合は、基本的には一生雇用するという考え方で、退職金や社会保険料などの負担も全部込みになりますので、一概の比較というのはなかなか難しいかなと思います。","id":"exchange-041"},{"speaker":"横山委員","kind":"質問","question":"本日、結論を出す、でお願いいたします。不採択でお願いします。ですので、引き続き、地域の方々と協力していただきながら、民間の協力なども仰いでいただいて進めていくということをお願いしたいなと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-042"},{"speaker":"芹澤副委員長","kind":"意見","question":"自民党、本日、結論を出すで、不採択でお願いします。他の自治体で週５日にしていないところが、なぜそのようにしているのかはわかりませんが、今、図書館の立ち位置が本を読むだけではなくて、いろいろな教育の成長の１つの大きなステップ、場所になっていると思っています。週５日にしたことで、この品川区のよさがなくならないように、ぜひさまざまな研究を続けていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-043"},{"speaker":"塚本委員","kind":"意見","question":"本日、結論を出します。態度は、不採択でお願いしたいと思います。一方で、どこまでこの中身を充実し、どのように運営していくか、どういうあり方であればいいのかということは、やはり利用する児童の側に立って、その子の成長を見ながら、いろいろと考えていく必要もあるのだろうと思います。そういった意味からも、現時点においては不採択ということでお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-044"},{"speaker":"のだて委員","kind":"意見","question":"結論を出すということで、採択をしていきたいと思います。いろいろな方が関わったほうがいいというお話もありましたけれども、それはそれで。学校司書も週５日、できれば、さらに専門性があるといいですし、それによって子どもたちの学習にも寄与するというところで、採択をしていきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-045"},{"speaker":"筒井委員","kind":"質問","question":"本日、結論を出すで、趣旨採択でお願いします。理由は、日数を増やす、将来的に毎日勤務ということは、区のほうも方向性を認めているところですし、私もある程度の日数は必要かなと考えております。ただ、民間への委託の問題やさまざまな課題があるところから、趣旨は採択したいという考えで、趣旨採択ということでお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-046"},{"speaker":"高橋（し）委員","kind":"意見","question":"結論を出すということで、私は趣旨採択です。専任の司書教諭を置くというのが一番ですが、これは東京都の考えで、少し違った方向に来ているところがあるので、では、自治体としてどうしていくかというところで、品川区としては２.５日という形でやられているのです。必ずしも毎日という形がベストかどうかというのは、また別で、そのような考え方から、趣旨は理解します。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-047"},{"speaker":"のだて委員","kind":"質問・要望","question":"今回の陳情は、全体としてインクルーシブ教育をより充実してくださいということだと思うのですけれども、まず、確認をさせていただきたいのです。教員の研修について、今、どのくらいやられているのかということで、今年度は３回実施したというお話でしたけれども、毎年３回くらいなのか、どのような形でやられているのか、伺いたいと思います。","respondent":"大関教育総合支援センター長","answer":"特殊教育から特別支援教育に変わったここ１０年間の推移の中で、当初は教職員全体、１,２００人を一堂に集めるような研修会も数年間行いました。","id":"exchange-048"},{"speaker":"のだて委員","kind":"質問・要望","question":"基本として、全体でやった後に、新しく入ってくる方にはやっている。それにプラスして年３回やられているということです。それでも、まだ理解が足りない部分があるのかなと思いますので、より理解を深めていくということで、やっていっていただきたいと思います。１点。今、特別支援教育コーディネーターのお話が出ましたが、その役割、どういったことをやられているのか、ご説明いただきたいと思います。","respondent":"大関教育総合支援センター長","answer":"周囲の学校との関係調整、連絡調整、あるいは保護者との対応に関する教員との共通理解、あるいは校内委員会を管理職、担任と一緒に主催する。そのような立場にあります。","id":"exchange-049"},{"speaker":"のだて委員","kind":"質問","question":"ご説明ありがとうございました。別の件なのですが、巡回相談員の巡回数を増やすということも陳情に書かれておりますけれども、今の巡回はどのくらいの頻度でいらっしゃるのか。どういった業務、支援を行っていらっしゃるか、伺いたいと思います。","respondent":"大関教育総合支援センター長","answer":"１人の巡回相談員が５校ないし６校、１つの小学校、中学校、義務教育学校のグループとして担当いたしまして、学校間連携も意識した状態の担当校を２週に１日巡回しております。","id":"exchange-050"},{"speaker":"のだて委員","kind":"質問","question":"今、２週に１回巡回されているということで、事務事業概要を見たときに、常に支援が必要な方がいるときに伺うような感じに受け取ったのですけれども、そうではなくて、定期的に通って、そういう支援が必要な方がいるかどうかということも見ながら、あとは助言などをした子どもがどう改善するかといったところも見ていらっしゃるということでしょうか。","respondent":"大関教育総合支援センター長","answer":"学習支援員のように、個別に１人のお子さんの支援に直接携わるのではなくて、学習の様子を見ながら、支援を受けている、あるいは配慮を受けているお子さんに関する情報を精査したり、あるいは担任にアドバイスしているといった立場です。","id":"exchange-051"},{"speaker":"のだて委員","kind":"質問","question":"いることがわかっていて行くということなのか、それとも、定期的に行って、支援が必要な子がいたら、そういう助言をするということなのかを伺いたかったのです。","respondent":"大関教育総合支援センター長","answer":"個別指導計画が作成されている方がいないクラスにも入っていきまして、どのクラスにも、何らかの支援、あるいは配慮が必要なお子さんはいるという前提で、対象者、あるいは学校からの要望がある、ないに関わりなく、２週に１日は必ず行くという形をとっております。","id":"exchange-052"},{"speaker":"のだて委員","kind":"質問","question":"定期的に伺っているということで、やはりそういったところで今回、頻度を増やしてほしいということで出ているわけです。そこで、特別支援のお子さんが、今、増えているというお話もありますし、そういった中で先生が対応していくために、より巡回を増やしていく必要があるのかなと思うのですけれども、いかがでしょうか。","respondent":"大関教育総合支援センター長","answer":"巡回相談員が増えれば、それだけで解決するということではなくて、さまざまな立場から学校を支えていくということが重要だと思いますので、引き続き、現状を充実させてまいりたいと現段階では考えております。","id":"exchange-053"},{"speaker":"のだて委員","kind":"質問・要望","question":"さまざまなところを充実させていきたいということですので、巡回相談員のところでも、ぜひ充実させていっていただきたいと思います。スクールカウンセラーのところで、この陳情にも書かれておりますが、先ほどの司書の話と一緒ですけれども、学校に多くいることによって、子どもがどういう子かということがわかってくるということで、今回、週１回から増やすようにということで求められています。","respondent":"大関教育総合支援センター長","answer":"東京都の配置しているスクールカウンセラーは、特別支援だけに特化せずに、保護者への教育相談的なことまで、全般的なことを含めて、カウンセラーという立場で週１回、学校に常駐しています。","id":"exchange-054"},{"speaker":"のだて委員","kind":"質問","question":"そうすると、区の考え方としては、このスクールカウンセラーのところは、最初に情報をキャッチして、教育相談室につなげる役割という捉え方なのでしょうか。","respondent":"大関教育総合支援センター長","answer":"あるいは内容によっては、もしかすると副校長や管理職が対応したほうが適切な内容もあったり、あるいは教育相談室のカウンセラーが対応する内容、ＨＥＡＲＴＳのカウンセラーが対応する内容、あるいは特別支援教育係の中には。","id":"exchange-055"},{"speaker":"のだて委員","kind":"質問・要望","question":"さまざまな対応先があるということで、それに適したところがやっていくというお話だったと思うのですが、やはりそういった面でも、それぞれを充実させていくということが重要だと思います。スクールカウンセラーも、配置日数を増やしていっていただきたいと思います。やはり、このインクルーシブ教育を進めていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-056"},{"speaker":"筒井委員","kind":"確認","question":"インクルーシブ教育は必要なものでありまして、公園でも、砧公園と府中の森公園の都立公園がインクルーシブ公園になったり、そうした社会情勢も相まってインクルーシブということは進めていかなくてはいけないものだと考えております。ただ、この陳情者が言われていること。そうしたことが書かれているのですけれども、書かれていることに対して、品川区としてはどういう認識なのでしょうか。","respondent":"大関教育総合支援センター長","answer":"そこは丁寧にしていくのが大切かなと思いますし、そこでなかなか難しいケースについては、教育相談室にご相談いただいて、そこから教育相談室のスタッフを通じて情報をいただいて、学校担当の指導主事が学校訪問をし、実際に子どもの様子を見させていただいたり、必要に応じて。","id":"exchange-057"},{"speaker":"筒井委員","kind":"質問","question":"今回の陳情は個人お一人の方なのですけれども、ほかにもそうした希望の係をやらせてもらえないとか、スクールカウンセラーの配置が週１日だから、それで子どもが混乱しているとか、他の方からそうした苦情のお声はあるのでしょうか。","respondent":"大関教育総合支援センター長","answer":"それほど複数の声をいただくというケースはございませんが、今回のようなご相談は、もう既に教育総合支援センターとしても受けてきて、その中で、可能な限り学校も努力していく、その中で、またホームドクター、通院先の医師の助言等の必要があれば。","id":"exchange-058"},{"speaker":"のだて委員","kind":"質問","question":"最後に１点。陳情項目の中に特別支援児の居場所づくりということで書かれております。先ほども少しお話があったかもしれませんが、支援の必要な子が外に飛び出してしまった場合の対応を、現状、どうされているのか、伺いたいと思います。","respondent":"大関教育総合支援センター長","answer":"先ほどの特別支援教室専門員、教員とは違う立場のスタッフも東京都から各校に１名配置されているところですので、教室にじっとしているのが難しいお子さんがいた場合に。","id":"exchange-059"},{"speaker":"のだて委員","kind":"質問","question":"いろいろな方々が力を合わせて対応しているというご答弁でした。陳情者の方のお話を聞いて、廊下で放置されていたというお話も聞いています。やはりそういったことがないように、例えばパニックになってしまって飛び出したというときに、逃げ込むような場所、落ちつくような場所を確保していくということは必要なのではないかと思いますけれども、そのお考えを伺えればと思います。","respondent":"大関教育総合支援センター長","answer":"引き続き、お子さんの実態に応じて、今は何が適切なのか、そして、今後、どうしていくべきかという部分は、関係者含めてケース会議等でしっかりと丁寧に検討を進めるのが基本だと考えております。","id":"exchange-060"},{"speaker":"横山委員","kind":"質問・要望","question":"本日、結論を出す、でお願いいたします。教育委員会として、総合的にしっかりと進めていただきたいということを要望させていただきたいと思っています。個別での細かい点を１つ１つあたっていくということはなかなか難しいかなと考えていますので、不採択でお願いいたします。ただし、インクルーシブ教育を総合的にしっかりと進めていただくよう、どうぞお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-061"},{"speaker":"芹澤副委員長","kind":"意見","question":"自民党、本日、結論を出すで、不採択でお願いします。しかしながら、まだまだ不完全、不十分というところもたくさんあるかと思いますので、そこは教育委員会でさまざま議論、研究を進めていただいて、さらなる拡充をしていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-062"},{"speaker":"塚本委員","kind":"質問・要望","question":"このインクルーシブ教育というのは、私個人としても、会派としても、しっかりと進めていくべきものということで、これまでも議会等でも発言しています。保護者の方がこういった思いを抱くということ自体は理解できるのですけれども、陳情という形で個別にもっと充実してほしい、もっとこうしてほしいということになってくると、やはりそれはなかなか願意に沿い難いですので、不採択とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-063"},{"speaker":"筒井委員","kind":"質問・要望","question":"事実確認もなかなかできない状況でして、そういった意味では、こうした陳情項目を並べられているところが賛同できないということで、不採択とします。ただ、品川区のインクルーシブ教育の体制を、こうした１人の不満も出ないように、さらなる充実をお願いしたいと考えております。この陳情者のご不満解消、そして、ご理解いただけるような丁寧な対応を引き続き行っていただきたいと考えております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-064"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"結論を出すで、不採択ということでお願いします。ただ、一方で、児童・生徒および保護者の方々に対しては細心の注意、配慮を払いながら、理解をいただき、インクルーシブ教育のシステム構築を進めていっていただきたいという点では、こういった陳情のお気持ちの方が出てきてしまわないように進めていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-065"}]},{"id":"topic-02","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"せお委員","kind":"質問・要望","question":"何点かお聞かせいただきたいのですが、まず、就学前の子どものための特別支援についてに書いてあります、１番の巡回相談です。品川区ではどのように使い分けているのかなということをお聞きしたいと思います。それと療育というところの違いがありましたら、教えていただきたいと思います。その２点、お願いいたします。","respondent":"佐藤保育課長","answer":"特別支援児に対する保育は、今、お伝えした一般的な保育活動よりも、より丁寧な関わり、配慮を行う保育活動と認識しておりまして、療育と保育の違いは、各施設の設置目的、また、従事する職員の資格や支援内容等に違いがあると考えております。","id":"exchange-066"},{"speaker":"せお委員","kind":"質問","question":"そうしますと、例えば療育と特別支援保育となりますと、公立園と私立園で、考え方として違いがあったりしますでしょうか。","respondent":"佐藤保育課長","answer":"特別支援に対する公立、私立の違いのところだと思うのですけれども、区として「のびのび育つしながわっこ」を区内の各保育施設に配っているところと、定期的に全体的な講演会を行っていますので、特別支援児の対応は、保幼小の連携も含めて、非常に大事な事業だということは。","id":"exchange-067"},{"speaker":"せお委員","kind":"質問・要望","question":"公立と私立で方針の違いがもしかしたらあるのかなということがありまして、特別支援保育については、やはりどのお子さんも同じように支援が受けられるように、さらに取り組んでいっていただきたいと思っています。それは、どのような理由が考えられると思いますか。","respondent":"大関教育総合支援センター長","answer":"あわせて、特別支援学級ではなく、通常の学級で頑張りたいという見極めが難しいケースの場合に、どうしても低学年の間、支援が必要だったお子さんが１年間、２年間と経過するうちに、固定学級に移られるというケースもあります。","id":"exchange-068"},{"speaker":"せお委員","kind":"質問","question":"中学校でも誰でも普通学級に通えるような体制を少しずつ整えていっていただけたらいいなと思っています。１点だけ。入院している方、あと、在宅医療のお子さんなども含めて、どこにも通えていないというか、どこからも学習を受けられていないようなお子さんは品川区にいらっしゃいますでしょうか。","respondent":"大関教育総合支援センター長","answer":"あわせて、都立特別支援学校、光明特別支援学校から訪問教育も受けられるようになっておりますので、本人の体調さえ許せば、何らかの形で入院中も学習ができるという状況にあります。","id":"exchange-069"},{"speaker":"せお委員","kind":"質問","question":"在宅医療をしている子など、全然通えていない子は把握できていたりしますでしょうか。","respondent":"大関教育総合支援センター長","answer":"ただ、訪問指導を行っている中で、本人の代わりにＯｒｉＨｉｍｅというロボットを教室に参加させるという工夫が過去にはございました。それも、また個別のケースで柔軟に対応したいと考えております。","id":"exchange-070"},{"speaker":"塚本委員","kind":"質問","question":"就学前の子どものための特別支援の巡回相談を行う人材名のところでお伺いしたいのです。嘱託医も含めて、それぞれの資格ごとに人数として何人ぐらい携わっていらっしゃるのか。それで、臨床心理士、臨床発達心理士、学校心理士と３つの資格があるのですけれども、この使い分けというか、資格の特徴などにおいて、巡回の相手先ややり方の使い分けの考え方があるのかということについてもお伺いします。","respondent":"佐藤保育課長","answer":"巡回相談の関係ですが、まず、人数は、それぞれ１名です。嘱託医１名、臨床心理士１名、臨床発達心理士１名、学校心理士１名〔同日後刻に「４名」と答弁訂正あり〕です。","id":"exchange-071"},{"speaker":"塚本委員","kind":"質問","question":"それぞれ１人ということで、嘱託医は多分、普段どこかでお医者さんをやられているのだと思うのです。臨床心理士や、ほかの３つの資格の方は、通常はどういうところに属しているというか、本業地というか、巡回相談以外にどういうところで仕事をされている方かを教えてください。","respondent":"佐藤保育課長","answer":"臨床発達心理士の方は、自分でＮＰＯを立ち上げて、特別支援に関する発達の相談の講演などをされております。臨床心理士の方に関しましては、外部の別の病院に短時間お勤めになっていらっしゃるというところです。","id":"exchange-072"},{"speaker":"塚本委員","kind":"意見","question":"就学後の子どものための特別支援の表なのですけれども、先ほども少し質疑がありました。こちらの人材の確保というところです。中学校なので、多少勉強の内容が難しくなってきている中で、この学習支援をしていくという人材面で、十分なリソースという言い方が正しいかどうかわからないけれども、あるのか、やや人がいなくて探さなければいけない状況にあるのか。","respondent":"大関教育総合支援センター長","answer":"今年度より、中学生段階のいろいろな学習上の支援の研究に非常に詳しいスタッフを新たに迎えたと聞いておりますので、さらに深めていっていただけると期待しています。","id":"exchange-073"},{"speaker":"塚本委員","kind":"質問・要望","question":"その辺りの巡回相談から発達支援施設への連携というのは、巡回相談員の方々は、それぞれ個人的にパイプをもっているところがあるのか、あるいは、それは個人で進めるということではなくて、保育課なりが１回集約して対応していくのか。その辺りの流れというのは、どのようになっているのか。詳しく教えていただきたいと思うのです。","respondent":"佐藤保育課長","answer":"１点、答弁の訂正をさせていただいていいですか。先ほど、学校心理士を１名と答えたようなのですけれども、４名です。","id":"exchange-074"},{"speaker":"塚本委員","kind":"質問・要望","question":"保育課のほうでということなのだと思うのですけれども、児童発達支援の所管は、一応、障害者福祉課になるので、そこの連携が少しうまくいかないと、早期発見、早期導入につながらないところが出てしまうといけないと思うのです。その辺りの連携について、最後に確認をさせていただきたいと思います。","respondent":"佐藤保育課長","answer":"入った後に関しましては、先ほどの巡回相談やさまざまなタイミングを見て対応しているところなのですけれども、基本的に療育支援ネットワークという庁内の情報共有の場がありますので、そういった場を通じて、効果的に情報共有や事業内容の理解に努めているということです。","id":"exchange-075"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"一般質問でもお伺いしたところでもあるのですが、この図で、どんな方がどういう情報の連携をされているかというのを、３ページの図の左下の「保育園」「幼稚園」というところで、今、巡回相談の事業をやられているのですが、そこから「入学」というところに入ったときに、先ほど、支援シートをつくられると言っているのですが、それだけで情報が小学校のほうに行っているのかということです。","respondent":"大澤保育支援課長、大関教育総合支援センター長","answer":"私から私立幼稚園の巡回相談についてご説明します。計画としましては、３６回分、学校心理士が回る計画があります。そうではなくて、何か学校と情報共有したほうが、本人の学習にはよりスムーズだという部分は、ぜひご相談くださいね、という形で、入学前の入学説明会の段階で、各校の校長から“うちの学校には特別支援教室があって。","id":"exchange-076"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"もう一つは、就学前の事前の準備のことについて、教育委員会のほうも把握しているということですので、今後、そういった教室のことは、教育委員会としても十分注視していっていただきたいと思います。お子さんのための療育が行き過ぎた形にならないように、ご本人にとっていい形になるように、教育委員会として見られる範囲で結構ですので、注視していっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-077"},{"speaker":"のだて委員","kind":"質問","question":"就学前のところで、特別支援保育推進チームの設置をされているということで、これは各園に設置をしているのでしょうか。人数といったところを少しご説明いただければと思います。","respondent":"佐藤保育課長","answer":"特別支援保育推進チームですが、今年度から区立保育園各園で１名の中堅保育士をリーダーと定めて実施しているところです。","id":"exchange-078"},{"speaker":"のだて委員","kind":"質問","question":"それを各園でやられているということで、そうすると、メンバーは何人ぐらいの体制でそれぞれ意見交換して、対応を考えていくということになるのか。特別支援に特化したというか、専門性をもった人が中堅のリーダーになるという形になるのでしょうか。","respondent":"佐藤保育課長","answer":"すみません。人数は、４３園ありますので、４３名です。各園１人ずつです。","id":"exchange-079"},{"speaker":"のだて委員","kind":"確認","question":"確認なのですけれども、４３人いらっしゃるというのは、チームとしては４３園分あるということでいいのですか。チームが４３人です、というと、４３人のチームなのかと感じてしまうのですけれども、そこの確認です。","respondent":"佐藤保育課長","answer":"説明が悪くてすみません。４３園で、各園ごとに１チームといいますか、１つの体制でやっているということです。","id":"exchange-080"},{"speaker":"のだて委員","kind":"質問","question":"そういったチーム体制でやられているということで、今年度から始めたということなのですが、始めるきっかけ、背景を伺えればと思います。どういった仕組みで、実際のケースを検討していくにあたって、どういうスキーム、形でやられるのか伺いたいと思います。","respondent":"佐藤保育課長","answer":"こういった特別支援に対する研修というのは、先ほどご答弁したとおり１０年経っていまして、相当なノウハウもたまっているところで、いつまでも研修を受けたり、講演を聞く受け身ではなく、中堅職員のやりがいの面でも。","id":"exchange-081"},{"speaker":"のだて委員","kind":"質問","question":"就学後のところで、学習支援員と介助員が入ってやられているということで、先ほどご説明があったのかもしれないですが、平成２５年度から何倍にも増えているというところで、その理由というか。行事のみの場合もあるというお話だったので、そこも要因だとは思うのですが、ほかに背景などがあったら伺いたいと思います。学習支援員と介助員というのは、何人ぐらいいらっしゃるのか伺いたいと思います。","respondent":"大関教育総合支援センター長","answer":"あるいは学校に何時間という形で、特別支援学級には必ず１人配置するという形で進めているところです。すみません。増えている理由といたしまして、子どもが年々増えていると同時に、やはりそれだけ特別支援教育に対する理解と期待が両方とも高まってきたと受けとめております。","id":"exchange-082"},{"speaker":"のだて委員","kind":"質問・要望","question":"そういった面でも、考えていっていただきたいと思いますが、いかがでしょうか。","respondent":"大関教育総合支援センター長","answer":"今後につきましても、引き続きそういった部分は財政部門のほうに相談して進めていきたいと考えています。","id":"exchange-083"},{"speaker":"横山委員","kind":"質問","question":"幾つかお伺いしてまいります。そして、２点目、４の園での具体的な取り組みというところで、先ほどご答弁にもありましたけれども、公立園ではノウハウがかなり蓄積されているとお聞きしました。例えば、研修に関して、連携の状況がもし何かございましたら、教えていただけたらと思います。","respondent":"佐藤保育課長、大関教育総合支援センター長","answer":"一方で、その分、巡回相談の体制を拡充していますので、そこをうまく使って、私立園にもさまざまな研修を開催しますし、相談も行っていって、力を伸ばしていきたいと考えております。普段もそれぞれのすまいるスクールのＮＰＯの方と我々教育総合支援センターの特別支援教育係のスタッフ等で、必要に応じて新たな発達障害等に関する情報共有などは進めておりますので、これからも依頼があれば学校のほうも連携して。","id":"exchange-084"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"田中さやか議員の体罰の質問で、事例を挙げて、たたいたり、廊下に立たせたりすることがあるというところで、本会議上では精査しないと答えられないというような答弁だったと思うのです。それは、手続上、そういったこともあるかもしれませんが、これについて、今後、調査などはやっていかないのかどうかということ。実際にそういった事例をつかんでいるのかというところを伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-085"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/810051?Template=document&Id=4986#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2019-01-01&TermEnd=2019-12-31"}],"sourceMeta":{"pages":0,"characters":49803,"voices":245}},{"id":"r01-20191202-5","meetingId":"r01-cm12","date":"2019年12月2日","dateIso":"2019-12-02","committee":"総務委員会","time":"午前１０時００分～午後 １時０２分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を77件抜き出しています。","topics":[{"id":"topic-01","title":"第９１号議案 戸越台複合施設大規模改修機械設備工事請負契約の変更","agenda":"第９１号議案 戸越台複合施設大規模改修機械設備工事請負契約の変更","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"２つ目は、これは相手から区に相談があって検討するものなのか、上昇そのものは客観的なものだから、区のほうから相手側に状況を伺うのか、その流れもご説明いただきたいと思います。","respondent":"立木経理課長","answer":"きっかけといたしましては、国が賃金労務単価、もしくは資材単価の上昇があったので、その単価を変更しますと、各自治体においても同様の処置をするようにというような要請が来た上で、区でも改めて判断をして適用させているということになりますので。","id":"exchange-001"},{"speaker":"西本委員","kind":"質問","question":"あくまでも品川区が全額をもちなさいと言われてしまうのか、そうなってくると、仮に国の補助金があって、それを品川区が適用するという形であるならば、そういう形でこういう流れになっているとすれば、品川区が現場の状況を見て、国からはどういう判断が来るかわからないけれども、これは投資したほうがいいということは品川区独自ではできないのか、その辺はいかがですか。","respondent":"立木経理課長","answer":"そうした中で、ある基準点より前に、要は、以前の労務単価で積算されたものに関して、例えば今回は３.３％ほど上昇ということで来ておりますけれども、そういった場合に、やはりそのままにしておくと、受注者側の企業努力というところも当然総価契約でやっているものですので。","id":"exchange-002"},{"speaker":"西本委員","kind":"質問","question":"補助金ですが、金額が高くなるわけですね。そうすると、この増額分は、区が全部支払うという感覚でよろしいのですかというのが１点。それから、毎年変動する。それはそれでわかります。なら、ずれはないのでしょうか。市場の動きと国が決めている、国と品川区という形で来ると思うのですけれども、そこでずれは生じませんか。そういうときの判断を区としてはどうするのですかという話なのです。","respondent":"立木経理課長","answer":"市場価格とのずれというところでの話ですが、まさにずれが出ていること、実際の市場の情勢の中で賃金上昇、資材価格の上昇とかが見込まれるということで、今回、国も単価を変えてきているところがありますので。","id":"exchange-003"},{"speaker":"西本委員","kind":"質問","question":"増額分を誰が支払うのですか、所管課なのか、経理課なのか、どこなのでしょうか。そうすると、これだけの増額分を誰が支払うのですか。これは誰が、実際にお金をどういう流れで動かすことになるのか。それに対して大丈夫ですと言うのか、それにのっていくのか、受注者側の判断になるのだろうけれども、実際に増額分と請求されたときに、どういう処理をするのですかいうことなのです。誰が処理するのですか。","respondent":"立木経理課長、品川財政課長","answer":"増額になる分に関しましては、これは区の予算の中で見込めない場合は、また補正予算等を組ませていただいて、その部分を手当てするという形になりますので、基本的には一般会計になるかというふうには思ってあります。国も毎年度一定の予算を確保していますので、そこの中でやはり他の自治体等と調整をしながら、国のほうでも補助金が残金としてあれば、そこで配付される、そういうような形になるかと思います。","id":"exchange-004"},{"speaker":"西本委員","kind":"質問","question":"ここはすごい大切な部分だと思うのですけれども、国があげるということを決めました、都も決めました、品川区に指示が来ました、それを受注者が請求してきます、そのお金を誰が払うのですかということ。補正をやるのはわかります。これ、結構な数が来ています。その数をどういうふうに管理しているのですか。それともグロスで来てしまって中身はわかりませんという状況なのか、どうなのでしょうか。","respondent":"品川財政課長","answer":"国や都がそのインフレスライド等に応じて補正予算等を組んでいれば、それで予算化されて配分がされるということになりますし、そこまでしなくても、国や都で配分ができるということであれば、そういうふうに対応されるということになります。","id":"exchange-005"},{"speaker":"西本委員","kind":"質問","question":"要は、そのまま金額が入ってくると私は思っていたので、ここの増額分は、ひもつきではないですけれども、こういう項目でこのぐらいになっているという、何％の値上がりというのはあると思うのですけれども、そういう形で照合できるのかと思えば、全くそれはできていないという理解でいいですか。","respondent":"品川財政課長","answer":"補助金の原則的な考えですが、例えば、いろいろな補助金で全体の費用の中の３分の２が出ますというような形で制度として決められているところがあります。","id":"exchange-006"},{"speaker":"西本委員","kind":"質問・要望","question":"わかりました。仕組みが少しわかってまいりましたが、納得したわけではありません。結局は、国が補助金の査定の中で、状況によって「なしね」という場合もあるわけではないですか。そういう状況になっているからしようがないではなくて、やっぱり要求は要求としてしていかないといけないのではないかと思いますので、なかなか難しいと思いますが、ぜひそういう努力もしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"須貝委員","kind":"質問","question":"以前にも申し上げたのですが、たまたま民間の業者の方にお聞きした内容では、民間ではこういうスライド条項がない。このようなことをやるということは、正規の今までの見積もりはないわけですから、常に不安定な見積もりで予算を組んで、そして執行しているということになるのですが、その辺についてどのようなお考えを持っているのかお聞かせください。","respondent":"立木経理課長","answer":"公の契約に関しましては、積算をする際に、国や都が出してきている設計労務単価等を使うことになってあります。そちらのほうには、将来的な上昇等の分は見込まれてございませんので、その時点での適正価格という形での単価設定になってあります。","id":"exchange-008"},{"speaker":"須貝委員","kind":"質問","question":"できるだけ正確な、皆さん、こうやって今回も議案になって提出されるわけですから、やはり本来はきちんとした入札でこういう価格に決まりました。今、人件費が決まっています云々というお話を言われました。それと、逆にお聞きしたいのは、こういうふうにインフレスライド条項があるのですが、逆にデフレスライド条項があって、それを区が適用したことがあるのですかという話になります。","respondent":"立木経理課長","answer":"もう１点、デフレ条項に関しましては、これはもちろんそういった急激な変化が見込まれる場合には適用になるものですが、区では、今まで適用したことはございません。","id":"exchange-009"},{"speaker":"須貝委員","kind":"意見","question":"区としては、例えば、工事費の一部を先にお渡ししたりとか、さまざまな工夫をして民間業者、区内業者を支援するような仕組みをつくって、それは本当に立派だと思うのですが、区民が見た場合に、民間の人が見た場合に、やっぱりおかしいのではないかというふうに疑問に思われると思うので、その辺は改善を考えてほしいと思うし、今お話ししたインフレ条項はあるけれどもデフレ条項は適用したことがない。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-010"},{"speaker":"田中委員","kind":"質問・要望","question":"契約の相手の方たちが余り負担にならないようにというのは本当に納得しています。先ほどのやりとりの中でも、国や都の補助金の話とかも確かに求めていってもいいと思っているのですけれども、やりとりの中で、そのときどきにインフレスライド条項を適用させるかを判断しているということがあったと思います。","respondent":"立木経理課長","answer":"時期といいますか、残工事期間が多少変わってきますので、その当時、一番長く残工事をとった段階での見積額でいきますと、増額分としては、３億円程度を見込んでいたところです。","id":"exchange-011"}]},{"id":"topic-02","title":"第９２号議案 第二戸越幹線整備工事（下水道本管立坑整備）請負契約の変更について、および(3)第９３号議案 第二戸越幹線整備工事（上流部シールド）請負契約の変更","agenda":"第９２号議案 第二戸越幹線整備工事（下水道本管立坑整備）請負契約の変更について、および(3)第９３号議案 第二戸越幹線整備工事（上流部シールド）請負契約の変更","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"設計変更分のところを伺いたいのですけれども、当初思ったより手間がかからなかったというか、必要なかったという分と、当初思ってもみなかった追加があったということですけれども、これは区の職員がずっと現場に立って見ているわけではないから、相手からの報告ということになるのかと思うのですけれども、区のほうで、判断はどうやってするのかというのが素朴な疑問でして、ある意味、追加の工事であれば。","respondent":"松本河川下水道課長","answer":"あわせまして、私たちのほうで施工監理という委託をしていますので、そういった施工監理の業者が精査した分も含めまして、上がってきた書類等を精査して妥当と判断し減額をしたものです。","id":"exchange-012"},{"speaker":"中塚委員","kind":"質問","question":"今回何かごまかしているというわけではなくて、何か思ったより手がかからなかったときに、ごまかすことができない、そのために施工監理を委託しているわけですけれども、そこが歯どめになっているという、そういうことになるのでしょうか。もちろん公共事業においてそういうごまかしはあってはいけないのだけれども、それを防止するための仕組みは、どういう形があるのか、改めて伺いたいと思います。","respondent":"松本河川下水道課長","answer":"その段階、段階で精査をしておりますので、そこの数量だったり、出来高を確認しながらやっておりますので、その中で数量がちゃんと合っているのかどうかというようなことを適宜現場ごとにやっておりますので。","id":"exchange-013"},{"speaker":"田中委員","kind":"質問","question":"私は、第９３号議案のことを伺いたいのですが、工事のこととか本当に苦手で、ちょっと難しくて、見当違いの質問をしてしまうかもしれないのですけれども、設計変更分の増額ということだったのですけれども、設計変更で工事が危険になったから交通誘導の人数が増えたとか、この人数変更だけだと、増えたのか減ったのかとかがよくわからなくて、ここのところは、最初の契約とはまた違う工事の契約になったのか。","respondent":"松本河川下水道課長","answer":"前面の道路も狭い道路のところで工事をしておりまして、当初、交通誘導員を５名配置して工事をする予定でございました。こういった交通誘導員の配置につきましては、警察と協議の中でどういった配置がいいのかということで、道路使用許可をいただく際に決まってあります。","id":"exchange-014"},{"speaker":"西本委員","kind":"質問","question":"第９２号のほうですけれども、騒音対策とか、仮設工というのですか、追加分が出ているのですけれども、騒音対策などは、当然、工事をされる前に想定されていたのだと思うのです。それがこういう変更があるということ。それは入った状況で積算するのではないですか。後になって、なぜ工期が１５日間延伸になるのですか。これもずれるのが仕方ないこと、許容範囲の中にあるものなのか、それらを教えてください。","respondent":"松本河川下水道課長","answer":"３点ほどご質問があったと認識しております。１点目の騒音対策等ですが、確かに騒音が当初から見込みがあれば、そういった騒音対策を実施するということは場合によってはあります。","id":"exchange-015"},{"speaker":"西本委員","kind":"質問","question":"いろいろな要因があるのだということがわかりました。いろいろな想定の中で、契約をする、入札をするというときには、公平にやっていると思いますけれども、その辺を意識した形で、今回はいろいろな変更点があったということがわかりました。これはどういう処理をするのですか。これは東京都の受託なので、１００％対応してくれるという認識でよろしいでしょうか。","respondent":"松本河川下水道課長","answer":"そのとおりです。","id":"exchange-016"},{"speaker":"西本委員","kind":"質問","question":"減額の場合には、返すと思うのですけれども、それはどういうふうに返すのですか。済みません、一緒くたになって返すものは返すというような、そういうふうにするところがあるのか、個別で、この分返しますとなるのか、それはどう、お金はこれだけ来ているのだからということで返すだけなのか、いやいや、まだまだ支払いのずれが出てくるので、ということなのか。","respondent":"松本河川下水道課長","answer":"詳細はわかりかねるところがありますが、年度協定を下水道局とは結んです。ですので、その中で各精算をしていくようなことになろうかと思います。最終的には、来年度に工事が終わりになりますので、そこで精算をしていくというような形になろうかと考えています。","id":"exchange-017"},{"speaker":"須貝委員","kind":"意見","question":"１点だけ。","respondent":"松本河川下水道課長","answer":"今回、泥水処分ですが、確かに量が減ったということもあります。あわせて、当初、今お話がありましたように、産業廃棄物ということで処分場のほうに出すという予定をしてございました。","id":"exchange-018"}]},{"id":"topic-03","title":"工事請負契約の変更について、(6)第９６号議案 城南小学校校舎・幼稚園園舎改築空気調和設備工事請負契約の変更について","agenda":"工事請負契約の変更について、(6)第９６号議案 城南小学校校舎・幼稚園園舎改築空気調和設備工事請負契約の変更について","exchanges":[{"speaker":"須貝委員","kind":"質問・要望","question":"先ほど、第９１号議案でも述べましたが、インフレスライド条項と同様に、デフレスライド条項も作成するなどして、区民にわかりやすい、理解を得られやすい、そういう案をつくっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"西本委員","kind":"質問","question":"これは契約相手側にはきっちりと説明をされているという理解でよろしいですか。これから請求していただける形になっているのでしょうか。","respondent":"立木経理課長","answer":"事業者のほうで、これは実際に積算をやり直したりとか、いろいろ書類の用意をしていただくというところで、実際に請求を出すかどうかというところはそれぞれのご判断ということになりますけれども、そこら辺はきちんと説明をした上で、今回、申請をいただいているというところで。","id":"exchange-020"},{"speaker":"西本委員","kind":"質問","question":"その際に、「今回こういう形になりますので請求してください」という話だと思うのですけれども、状況によっては、「大丈夫です」という形もあるだろうし、いや、「もう困っていたのです」という相手方もいらっしゃると思いますけれども、今回はどういう感じに受けとめられたのでしょうか。","respondent":"立木経理課長","answer":"今年度、インフレスライド条項、今回の適用になる案件としては２０案件ほど調査で出てきております。今回、議案で出てきているのが１０件ということで、再積算をしたりですとか、書類を準備するというのは、相当程度の手間がかかるものです。","id":"exchange-021"}]},{"id":"topic-04","title":"第９８号議案 芳水小学校第２期校舎改築その他工事請負契約の変更","agenda":"第９８号議案 芳水小学校第２期校舎改築その他工事請負契約の変更","exchanges":[{"speaker":"須貝委員","kind":"質問・要望","question":"先ほども申し上げましたが、インフレスライド条項と同様にデフレスライド条項も作成し、区民の理解が得られる契約制度をつくっていただきたい。それだけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"}]},{"id":"topic-05","title":"築その他工事請負契約の変更について、(10)第１００号議案 後地小学校校舎改築その他機械設備工事請負契約の変更について","agenda":"築その他工事請負契約の変更について、(10)第１００号議案 後地小学校校舎改築その他機械設備工事請負契約の変更について","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"地中障害物ということですけれども、具体的に何かということと、事前にどのような地中の調査をしたのか、想定することは技術的に難しかったのか、そこをご説明いただきたいと思います。","respondent":"若生学校施設担当課長","answer":"もう１点は、隣地に擁壁がございまして、そちらの地中に底盤が若干校舎側のほうに越境していたところがございまして、このまま工事を進めると、擁壁自体の安全性等も含めて直す必要が生じてきてしまうということが懸念されましたところで、さまざま検討したところ。","id":"exchange-023"},{"speaker":"中塚委員","kind":"質問","question":"旧校舎を壊してから地下にあったということで、やむを得ないかなとは思うのですけれども、伺ったのは、工期が２月末から８月末に変わる、つまり、子どもたちにとっては卒業式と入学式が、今まで仮設の教室にいたけれども、卒業式、入学式は新しいところで行いたいというのは、子どもも教師も地域の方も、もちろん区も願うところではあるかと思うのですけれども。","respondent":"若生学校施設担当課長","answer":"実は、こちらの障害物等が発見されて以降、さまざまな形で、授業ですとか、子どもたちに影響がなるべくないような形で検討を進めてまいりまして、さまざま工法ですとか、あるいは素材等の技術的な部分も、設計の管理会社ですとか、ＪＶとも何度も協議を重ねた結果、今回。","id":"exchange-024"},{"speaker":"田中委員","kind":"確認","question":"済みません、今のに関連してですけれども、たしかプールの利用だったり、運動会のグラウンドをほかの学校から借りていたと思うのですけれども、それは来年の３月以降は大丈夫というか、後地小学校でできるということなのか、そこだけ確認させてもらってもいいですか。","respondent":"若生学校施設担当課長","answer":"説明が不足して申しわけございません。プールに関しましては、残工事として４月以降続けするのですけれども、６月ぐらいにプール開きがあります。それまでに間に合う形で仕上げるということで、プールの新校舎での利用は支障がないところです。","id":"exchange-025"},{"speaker":"西本委員","kind":"意見","question":"これ、地中障害物の撤去処分ということで延伸ということなのですが、第１００号議案、第１０１号議案の機械設備、電気設備工事も増額になっているのですが、地中障害物の撤去との関連は何なのか。建物だけであれば、掘ったときに何か出てきたということで、それはわかるのです。でも、機械とか電気工事ということに関しては、どういう関連性があるのかと思うのです。","respondent":"若生学校施設担当課長","answer":"原因として地中埋設物等があって、それによって工期が伸びた部分については、やはり職人ですとか、そういったところについても引き続き確保しておく必要があるというところになりますので。","id":"exchange-026"},{"speaker":"西本委員","kind":"意見","question":"そういうことなのだろうと思っているのですが、ということは、そこに保障するといいますか、確保するための税金投入ということになるのですね。それは仕方ないことだと思いますが、そこまで関与してくるのかということです。なるべく事前にわかれば一番いいのかなと思いますが、よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-027"},{"speaker":"須貝委員","kind":"質問・要望","question":"私などもいろいろな人とお話しするのですが、では、その現場が延びたからといって、遊んでいるわけではなくて、ほかのところへ行っていますから、この業者がこういう請求をしてきたというのは、すごく違和感を感じます。ですから、今回ちょっと違和感があるので、今後、そういうところも民間の建設業者にもいろいろ相談されて対応することを心がけていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"つる副委員長","kind":"質問","question":"だから、そこのところをちゃんとご説明いただかないと、多分この疑問が残ったままの質問しか出てこないのかと、私は個人的な感想を持ったところなのですけれども、それはそれとして、今の工期の部分ですが、当然、その間の担当者なりのいろいろ保障の部分、そういうところがあると思うのですけれども、そこについては私も不勉強で、そういう期間について何か別の単価の基準とか計算方法とか。","respondent":"若生学校施設担当課長","answer":"１点目、工期延伸となって単価等がどうなるのかというところですけれども、まず、延伸に伴って契約の変更をするに当たっては、やはり金額については事業者と区側と協議をして決めていくというようなところがございまして、区としても設定されている単価に基づいて算定していく。","id":"exchange-029"},{"speaker":"つる副委員長","kind":"質問","question":"工事の期間の話なので、障害物を撤去するのにどれだけかかるのですかという話。工期自体は半年延びていますけれども、障害物の撤去の作業だけでどれだけかかるのですか。","respondent":"若生学校施設担当課長","answer":"地中障害物の撤去に関してですけれども、先ほど申し上げた２点の理由がございまして、それを２つとも含めると、約４カ月程度のおくれが生じるところで、ただ、学校運営を考えますと、やはり夏休み中に仕上げを一気に行う必要がありますので。","id":"exchange-030"},{"speaker":"つる副委員長","kind":"質問・要望","question":"ここもわかれば教えていただきたいのですが、第９９号、第１００号、インフレスライド分があって、設備のところにはインフレスライド条項の適用がなかったということですが、ここのところについて詳しくわかれば教えてください。","respondent":"立木経理課長","answer":"具体的に申しますと、インフレスライドの適用工事になるかどうかという調査の中で精査した結果、インフレスライドは増額分の１％ほどが事業者、受注者側の負担ということになっているのですけれども、そういった計算をした結果、増額分が１％未満になってしまうということで。","id":"exchange-031"},{"speaker":"田中委員","kind":"質問・要望","question":"地中障害物の撤去処分作業は、今、第９９号から第１０１号に出ている業者の方がやっているわけではなくて、地中障害物による延伸でこれだけかかっている中に、地中障害物撤去の金額と延びた分の金額が一緒に含まれた額なのか、その部分のところを教えていただきたいのと、やっぱり気になるのは、工事を請け負っていた方たちが、延びてしまった分、ストップしてしまったけれども。","respondent":"若生学校施設担当課長","answer":"こちらの延びたところの賃金の支払いについてですけれども、今回、延伸した費用のうち、事実上、工事が新たに発生するというところでいうと、先ほど申し上げた仮の部分で仕上げたものを、本仕様にやり替えるというようなところが主な追加工事になってございまして。","id":"exchange-032"}]},{"id":"topic-06","title":"第１０２号議案 後地小学校外構整備その他工事請負契約","agenda":"第１０２号議案 後地小学校外構整備その他工事請負契約","exchanges":[{"speaker":"田中委員","kind":"確認","question":"後地小学校のところで、今お話のあったとおり、一方通行だったりというのは最初からわかっていることで、契約の相手も同じなので、わざわざ随意契約にしなくても、初めから同じ事業者でよかったのではないかということを確認したくて、その部分をお知らせください。","respondent":"若生学校施設担当課長","answer":"ただし、直近で契約させていただいている鮫浜小学校につきましては、外構も含めて一本契約ということで第２回定例会で審議いただいているところですけれども、都を通じて補助金の考え方について、よくよく確認したところ、どうも後ろ２年間というところは。","id":"exchange-033"},{"speaker":"田中委員","kind":"確認","question":"確認ですが、今後は随意契約ではなくて、こういった工事の場合は、１つにまとまって出てくるということを確認させてください。","respondent":"若生学校施設担当課長","answer":"あくまでもその学校の状況ですとか、ケース・バイ・ケースで、どういった契約形態がいいかというのは考えていくべきものと考えていますので、必ず一本化しなければいけないというようなことではございませんので。","id":"exchange-034"},{"speaker":"田中委員","kind":"質問","question":"ほかのものには代用できないというか、ほかの案は、人工芝以外は出てこないものなのか、その部分を伺いたいです。","respondent":"若生学校施設担当課長","answer":"ただし、技術革新等も進んでいますので、なるべく低減するような対策というか、素材は、メーカーでも検討しているということは聞いております。","id":"exchange-035"},{"speaker":"田中委員","kind":"質問・要望","question":"水はけの部分ですけれども、確かに水はけはいいというのですけれども、実際、子どもたちの声だと、水が結構たまっているということもあって、あと、ほかに人工芝だとマイクロプラスチックの問題とか、環境の問題とかもありまして、子どもたちの使用感だったり、環境のこととかも考えて、人工芝の砂ぼこり対策というのはとても理解できるのですけれども、いろいろな検討をしていただきたいという。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"}]},{"id":"topic-07","title":"第１０３号議案 勝島歩道橋南側エレベーター設置工事委託契約の変更","agenda":"第１０３号議案 勝島歩道橋南側エレベーター設置工事委託契約の変更","exchanges":[{"speaker":"田中委員","kind":"質問","question":"随意契約の場合、経理課は所管課の推薦によって契約がなされると聞いています。推薦した所管課と、どのような推薦理由であったかを伺いたいのでけれども。","respondent":"立木経理課長","answer":"こちらの工事に関する協定をとってありますので、そちらに基づく委託という形になってあります。","id":"exchange-037"},{"speaker":"田中委員","kind":"質問・要望","question":"業者の推薦について聞きたかったのですけれども、後地小学校の外構整備については、推薦書の情報公開を求めて持っているのですけれども、こちらは求めなかったので、その理由だったり、随意契約が妥当かどうかを伺いたくて、その部分をお知らせいただければと。","respondent":"立木経理課長","answer":"済みません、ちょっと説明が足りなかったのですけれども、こちらは随意契約というふうになってありますが、もともとは工事協定を結んでおります。","id":"exchange-038"},{"speaker":"田中委員","kind":"意見","question":"それだったら、本当に苦手な分野なのであれなのですけれども、工事協定を結んでいる中で、この随意契約が発生した理由、最初から決められなかった理由というのか、なぜ随意契約になったのかの部分を、ごめんなさい、本当に苦手な分野なので、お知らせいただければと思います。","respondent":"立木経理課長、多並道路課長","answer":"こちらの工事に関しましては、広く競争入札でやるのではなく、やはりいろいろな制限がある、モノレールの駅に近いところでのエレベーター設置ということになりますので、東京モノレールと工事に関しての協定を結んでおります。補足してご説明します。","id":"exchange-039"},{"speaker":"田中委員","kind":"意見","question":"ご説明を聞いて、何となくわかったのですけれども、そうしたら、随意契約ではなくて、またほかの方法があったのではないかというふうに思うのですけれども、鉄道に関することとかなので、入札ではなくて委託だったりした、工事協定を結んでいて、それに基づくということで、何となくわかったのですけれども、だから、なぜ随意契約になったのか。","respondent":"立木経理課長","answer":"先ほど、ご説明の中で、競争させて工事をさせるような案件ではないというようなところから、競争性というところが全くなくなってありますので、協定を結んだ上で、そこの会社に工事自体を丸ごとお願いするというような形ですので、随意契約の１つの形であるということです。","id":"exchange-040"},{"speaker":"田中委員","kind":"質問","question":"わかりました。では、そのような説明が、この説明資料にあったらよかったなというふうに思いました。重要な参考資料となるのではないかというふうに思うので、随意契約のときの推薦書、勝島に関しては推薦書はないということだったのですけれども、最低限の委員会資料として示されるべきではないのかというふうに思うので、その部分について見解を伺えればと思うのですが。","respondent":"立木経理課長","answer":"先ほど、後地小学校のところで随意契約理由ということでご説明させていただきましたので、そういった形で今後も議案の審査、報告等の案件に関しましては、そのような形でご報告をさせていただければと考えております。","id":"exchange-041"},{"speaker":"中塚委員","kind":"質問・要望","question":"それと、エレベーターは４億円もするものなのですか。何か随分高いなというのが率直な実感なのですけれども、もちろんモノレールとくっついているという特殊性も踏まえながらも、４億円もするのかというところは率直に伺いたいのですけれども、よろしくお願いします。","respondent":"多並道路課長","answer":"当初は仮囲い等の簡単な工事でやる予定でずっと詰めてきたところなのですけれども、やっぱり工事を実際に詰める最終的な段階で、馬主の方とか、いろいろ配慮したほうがいいだろうということで。","id":"exchange-042"},{"speaker":"西本委員","kind":"質問","question":"防音の対応をしたということなのですが、ここは私たちもすごく慎重になる場所なのです。金額はそれなりにかかるでしょう。それが疑問点と、それから、これはオリンピックの１つの対策になっていると思うのですけれども、どういう費用になっていますか。金額が高くなっていますけれども、これは全額品川区が出すのでしょうか。それとも東京都のほうからいただけるものなのでしょうか。","respondent":"多並道路課長","answer":"それで騒音対策と一般的にやっているところでもあるのですけれども、それが具体的に話をした中で、どうしても馬の状況を見ると、もう少し重ねた対応が必要だろうということで、一般的な対応に加えてやらせていただいたということなので。","id":"exchange-043"},{"speaker":"西本委員","kind":"質問","question":"それと、結局、エレベーターの設置については、品川区もある程度出すということの理解でよろしいでしょうか。例えば、まちづくりの１つのバリアフリーも含めてのことだから、国も東京都もある程度、品川区もある一定の負担は強いられるということでの理解でよろしいでしょうか。そこだけお聞きします。","respondent":"多並道路課長","answer":"駅舎と区の施設を共同で使っているような、ちょっと特殊な構造でもありますので、国費だとか都費を入れる場合には、新たに整備するエレベーターの費用の中で、ここに財源が当たるということで、それ以外の部分については、どうしても補修は区のほうで行うところもありますので。","id":"exchange-044"},{"speaker":"中塚委員","kind":"質問","question":"今のご説明ですけれども、区長が若い世代と意見を交わし、区政に反映させるということは大事なことだと思います。ただ、今のお話ですと、これまで区長と一般区民といいますか、公募した方との今までやっていたタウンミーティングはやめたということですか。","respondent":"木村広報広聴課長","answer":"区長が区民の方々とお話をして意見交換をするという、そのもの自体はやめてはおりません。継続実施をしておりますが、いわゆる名前あるいは対象、テーマを変えて継続して区民の方の声を聞いているです。","id":"exchange-045"},{"speaker":"中塚委員","kind":"質問","question":"区長と区民が、今まで平成１８年度からやっていたタウンミーティングはやめていないということであれば、なぜ平成３０年度は実施されなかったのですか。その辺がよくわからない。陳情の趣旨は、復活してほしいということなので、ご説明ください。","respondent":"木村広報広聴課長","answer":"平成３０年度につきまして、予算計上もして実施をする予定ではあったのですけれども、日程とか会場の調整がつきませんで、実施をしておりません。","id":"exchange-046"},{"speaker":"中塚委員","kind":"確認","question":"やはり予算に組まれて会場と日程をしっかり押さえて、こうやって楽しみにしている方もいらっしゃるわけですから、しっかり実施をするということが必要だったのではないかと思うのですけれども、今振り返ってどうお考えなのかお聞かせください。","respondent":"木村広報広聴課長","answer":"以降につきましては、大学にするのか、あるいは、例えばですけれども、子育て世代であるとか、特定の対象の方々を対象にするのか、それはその都度、年ごとで判断をして考えていきたいと思いますが、このいわゆる区長との意見交換という形は継続してまいりたいと考えております。","id":"exchange-047"},{"speaker":"中塚委員","kind":"質問","question":"継続というのはわかったのですけれども、令和２年は、区長と一般区民のタウンミーティングはやらないということですか。","respondent":"木村広報広聴課長","answer":"現在は、連携の大学と「しながわ未来トーク」という形で、展開をするということで考えておりまして、広く一般区民の方から公募をしてやるということは、今のところ考えておりません。","id":"exchange-048"},{"speaker":"中塚委員","kind":"質問・要望","question":"大学生だったり、子育て世代だったり、対象のターゲットを絞って区長が意見交換をするということもとても大事だと思います。一方、幅広く区民に募集をかけて、区長とタウンミーティングを行うという、両方大事だと思います。令和２年度以降も、ぜひ多くの区民と区長が意見を交わすタウンミーティングを復活していただきたいと要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-049"},{"speaker":"田中委員","kind":"質問","question":"今までのやりとり大体わかったのですけれども、ただ、「しながわ未来トーク」とともに、今まで行われていたタウンミーティングの場を両方持つことはできないのですか。もっと話したいという区民の方たち、参加したいと思っている方たちに対しても、やっぱりそういう場はなくすではなくて、両方一緒に続けられてもいいのではないかと思うのですけれども、いかがでしょうか。","respondent":"木村広報広聴課長","answer":"もう１つは、場を設定しますと、例えばその日時、場所に限定いたしますと、そこへ来られない方のご意見がいただけないというところもありますので、幅広で、例えばホームページでメールで出していただいても、それは区長が全部見るような形にしていますし。","id":"exchange-050"},{"speaker":"田中委員","kind":"意見","question":"ただ、この陳情に関しては、タウンミーティングの場を復活させてほしいということなので、未来トークをやめろではなくて、一緒に行ってもいいのではないかと思うのと、この陳情者の方も書かれているように、区政参画にはやっぱりそういう意見交換だったり、さっきお話しされていた相互理解が必要だと私も思うので、そこの部分についてもう少しご説明いただければと思います。","respondent":"木村広報広聴課長","answer":"そういう形で進めてまいりたいと思います。","id":"exchange-051"},{"speaker":"田中委員","kind":"意見","question":"この陳情者の方のように、楽しみにされていた方たちもやはり多くいた中で、これからは対象を絞っていくということになった政策変更というか、それに至った理由、根拠の部分は、どのようなことがあって移行していってしまったのか、その部分をお知らせください。","respondent":"木村広報広聴課長","answer":"冒頭でもご説明させていただいたところではあるのですけれども、やはり公募という形でやっている中で、なかなか若い方のご参加がいただけなかったというところが正直ございまして、議会のほうからも。","id":"exchange-052"},{"speaker":"田中委員","kind":"質問・要望","question":"ほかにも方法があったのではないかと。総務委員会で視察に行った松阪市では、出前講座をはじめとした常に市民の声を聞きに行く姿勢、市民意見をなるべく反映させようとしている姿勢にとても共感しました。この視察で学んだ姿勢を品川区も見習うべきなのではないかというのはとても考えましたし、区民参画につながる場として復活させてほしいというのは、品川生活者ネットワークは強く賛同したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-053"},{"speaker":"須貝委員","kind":"質問・要望","question":"タウンミーティングの件ですが、区長もおそらくお忙しいということもあるので、そういうときに、やはり区民と接するという意味で、品川区は副区長がいらっしゃいますので、副区長と理事者で、二、三人でもいいから、例えば、各地域で地域懇談会、１００人ぐらいの地域の人が集まって懇談会をやるときに、３０分ぐらい出席して皆さんの声を聞くとか、それから、各団体でも、いろいろな団体がありますが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-054"},{"speaker":"西本委員","kind":"質問","question":"質問ですが、この題名にある「品川区のタウンミーティング」というふうに書いてありますが、品川区のタウンミーティングなのでしょうか、区長とのタウンミーティング、どうなのでしょうか。私はタウンミーティングと今までやっていたのは、区長とのタウンミーティングだと思ったのですけれども、品川区なのですか。そうすると、ちょっとニュアンスが違うのかなと思うのですけれども、いかがですか。","respondent":"木村広報広聴課長","answer":"もちろん区がやって、区の政策、姿勢、あるいはご意見を区に頂戴するというところもありますので、区とのともいえますし、区長が直接お話をするということ、区長とのタウンミーティングというところもありますけれども、基本的には、品川区に対して。","id":"exchange-055"},{"speaker":"西本委員","kind":"質問","question":"なぜかというと、レベルが違う。そして区民の皆様も期待通りのことがあったのだろうか。そういうことを考えた上で、いろいろ変わってきた部分があるのかなと思うのですが、「しながわ未来トーク」とか、そういうふうに変わってきたという経緯を見ると、テーマをしっかり明確にして、それに対する意見をいただくというふうに変わってきたのかなというふうに思うのですけれども、その辺の経緯はいかがですか。","respondent":"木村広報広聴課長","answer":"今までもテーマ別というような形でも、いろいろ年によってはやってきたところがございまして、それを明確にすることによって、先ほどおっしゃったミーティング、話がしやすい、意見交換しやすいというところがありますので、今回、若い層というところもありましたけれども。","id":"exchange-056"},{"speaker":"西本委員","kind":"質問・要望","question":"だから、昔のようにということよりは、いろいろな要求とか要望とかご意見をいただく場を設定しましょうというのが今の品川区のスタンスだと私は感じるので、前のようにと言われてしまうと、それでいいとは思わないと思います。やっぱり進化形であってほしいという思いがあります。それを議会がここで話し合うべきものなのだろうかというのはすごく感じます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-057"},{"speaker":"大倉委員","kind":"質問・要望","question":"今までもいろいろ質疑があってわかったこともあるので、改めて平成１８年から行ってきて１０年以上続いてきて、そこでいろいろなタウンミーティング、意見が出てきた、その中で、想像すると、わりと年齢層の高い人たちなのかなというところで、先ほど言った課題として若い人がなかなか参加していただけないみたいなお話があったと思うのですけれども、１０年間やってきた中での総括というか、課題だったり。","respondent":"木村広報広聴課長","answer":"それと、課題につきましては、先ほど、西本委員からのご指摘もございましたけれども、やはりどうしても固定化といいますか、ご意見の固定化も含めてですけれども、あるいは。","id":"exchange-058"},{"speaker":"小芝委員","kind":"質問","question":"過去４年間の実施状況をホームページで見せていただきまして、平成２９年が２回やって４５人と５２人参加されて、その前の年とその前々年は、実施場所が区役所だったと思うのですけれども、いずれも２０人以下で、その前の平成２６年が平成２９年と同じく４５人、４９人というふうに出ておるのですけれども、これは公募する段階で人数制限はかけていたのでしょうか。","respondent":"木村広報広聴課長","answer":"平成２７年、平成２８年については、特定のテーマに絞って関係者の方にご参加いただいて直接お話をしたです。","id":"exchange-059"},{"speaker":"小芝委員","kind":"意見","question":"平成２９年と平成２６年とでキャパシティの関係もあると思いますけれども、その会に参加できなかった、参加しなかった、声なき声に耳を傾けるのもやはり行政の仕事でありますので、もちろん声ある声にも耳を傾けるのは当たり前なのですけれども、そういった意味では、私としては、広く公平に意見を言えるような環境を整えていったほうがいいとは思います。言わせていただきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-060"},{"speaker":"つる副委員長","kind":"意見","question":"だから、やり方とか、そういった部分は、先ほど質疑であったかもしれませんけれども、いろいろなやり方を模索して、とにかく多種多様な意見を聞いていくということが、これは１つすごく大事なことだと思います。１点聞きたいのが、この間、どういう人数、どういう階層別にしても、司会進行が基本は時の広報広聴課長だったりするのかなという理解です。","respondent":"木村広報広聴課長","answer":"なかなか言いたい、聞きたいということが、自分の中で埋もれているところをうまく引き出してくれる、そういったことは大変、私はそのスキルはございませんけれども、区のタウンミーティング。","id":"exchange-061"},{"speaker":"つる副委員長","kind":"意見","question":"いずれにしても、広報ないし広聴の部分、かつて私も予算が９対１でしたので指摘したことがあって、なかなか広聴、行政として広く区民の方の声を聞いていく機会、金額ではないのですけれども、当然やり方とかということで、いろいろな手法をこれまでもやられてきているわけですし、今、ご答弁いただいた中でも、ぜひ今後のやり方、工夫という部分では、さまざまなやり方があるのだと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-062"},{"speaker":"大倉委員","kind":"質問・要望","question":"先ほど来お話をなさる中で、やはり未来に向けてさらにいろいろな話を聞きながら、区政の課題であったり、洗い出しをしていく中で、若い人たちということで目的を明確に持ってやられているというところで、さらにそうした声を聞きながら推し進めていっていただければいいかなと、当然課題があって、それをＰＤＣＡサイクルではないですが、１０年間やってきた中で課題があって。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-063"},{"speaker":"小芝委員","kind":"意見","question":"本日結論を出すということで、先ほど、意見を述べましたけれども、声ある声、それを聞くことももちろん大事ですが、声なき声も大事です。それはこの品川区のタウンミーティングの復活ということだけではなく、いろいろな方法で声なき声を聞くことができる環境を今後備えていけると考えますので、今回のこの陳情に関しては不採択としたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-064"},{"speaker":"つる副委員長","kind":"質問・要望","question":"結論を出すで、本陳情については不採択。先ほど、意見の中で言いましたが、今年の事務事業の説明の中でも、タウンミーティングのリニューアルということで、継続性をもって取り組まれているという理解でおりますので、本陳情については、その復活という表現ですから、当然、継続性を持って取り組まれているという理解のもとでの意味で本陳情については、不採択。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-065"},{"speaker":"中塚委員","kind":"質問・要望","question":"本日結論を出すということ、態度については採択でお願いいたします。「しながわ未来トーク」は続けていただきたいと思いますし、一方で、幅広い区民の方が自分の意見を区長と交換することができるこちらの区長とのタウンミーティングを復活させていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-066"},{"speaker":"須貝委員","kind":"質問・要望","question":"たまたま区長が懇親会にいらしたときに、そこに大勢、１００人ぐらいの地域の人がいたのですが、皆さん、いかないのですね。別段、区長が何がなんでも来いというのではなくて、接触したい、話を聞いてくれという、そういう要望を持っている方はたくさんいらっしゃいますので、確かにご苦労なことだと思いますが、区からも積極的に前へ出ていってやっていただければと思います。今回は採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-067"},{"speaker":"田中委員","kind":"意見","question":"タウンミーティングと「しながわ未来トーク」がやっぱり全然別物だなというふうに思うので、「しながわ未来トーク」はそのまま継続されていいと思いますし、タウンミーティングの復活というか、いろいろな声を聞く場面がさまざまあっていいと思うので、さまざま意見を聞く場があって区民参画につながって、区政の運営にもいい方向に働くと思うので、私はぜひ賛同したいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-068"},{"speaker":"西本委員","kind":"質問・要望","question":"本日結論を出していただきたいと思います。不採択でお願いします。先ほど言いましたように、この陳情の趣旨が、以前のタウンミーティングの復活ということを書かれております。こういうものが議会から上がってきたというのはいいのですが、それをやれとかというのは、すべきものではないというふうな思いがありますので、そういう意味で、今後の事業に期待を込めて、今回は不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-069"}]},{"id":"topic-08","title":"今定例会の一般質問に係る所管質問ですが、今定例会の一般質問中、総務委員会にかかわる項目","agenda":"今定例会の一般質問に係る所管質問ですが、今定例会の一般質問中、総務委員会にかかわる項目","exchanges":[{"speaker":"田中委員","kind":"質問・要望","question":"私の一般質問の庁舎のあり方検討の部分で、公文書の部分は総務委員会の所管だと思うので、公文書としての経営会議会議記録要旨についての補足の質問を求めたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-070"},{"speaker":"中塚委員","kind":"意見","question":"ルール化はないということであれば、できるということなので、ご本人の希望があればかまわないと思いますし、ほかの常任委員会でも、たまに自分たちのということも行われていますので、ここであえて拒む理由はないと思いますので、よろしいかと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-071"},{"speaker":"西本委員","kind":"質問","question":"やっぱり公文書の話だけというふうにはならないような気がするのです。なので、そこの線引きが、私たちも議論する中で、そこの仕切りをどうしたらいいのだろうなと、本当は議論したいです、本来は総務委員会でもやりたいです。ただ、行財政改革特別委員会がやると言っていることがあるので、そこの仕切りは、委員長、どうしたらいいのでしょうかということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-072"},{"speaker":"中塚委員","kind":"質問","question":"仕組みそのものをどうしようかという議論はどこかでするとしても、現状はそうだということでいいのではないでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-073"},{"speaker":"西本委員","kind":"質問","question":"田中委員の所管質問に関しては、自分で一般質問したという部分がありました。特別委員会の中でそういう関連の中での議論ができればいいのですけれども、そういう仕組みがなければ、中塚委員が言うように、総務委員会の中で取り上げるべきなのかと思うのですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-074"},{"speaker":"田中委員","kind":"質問","question":"本当に公文書の部分だけなので、庁舎の建て替え、あり方検討の中での公文書の部分だけなので、ぜひできればなということは思うのですけれども。どうしましょうか。質問したかった内容とかを今言ってみてもいいですか。明日やるかどうかは別としても。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-075"},{"speaker":"中塚委員","kind":"質問・要望","question":"もともとのルールをどうしようかという議論はしっかりすべきだと思いますけれども、従来、本人の質問でも所管質問を他の委員会でも認められてきておりますので、それを今回取り上げないとルールを変えることはできないと思います。なので、もう一度、考え直していただいて、明日ぜひできるようにするのが筋かなと思いましたので、意見を述べさせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-076"},{"speaker":"田中委員","kind":"質問","question":"今、ご決定があったというのならば仕方ないかなとも思うのですけれども、ただ、言いたいのは、吉田議員も総務委員会に今までいた中で、自分の所管質問を行っていたので、できるのかなという感じで聞いてみたら、そのときはできたということだったので、私ももしできたらよかったなと思ったのですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-077"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/203294?Template=document&Id=2152#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2019-01-01&TermEnd=2019-12-31"}],"sourceMeta":{"pages":0,"characters":52802,"voices":290}},{"id":"r01-20191203-6","meetingId":"r01-cm12","date":"2019年12月3日","dateIso":"2019-12-03","committee":"区民委員会","time":"午前１０時００分～午前１１時５７分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を3件抜き出しています。","topics":[{"id":"topic-01","title":"「」を聴取いたします。 「羽ばたけ！ アントレーヌ」の開催","agenda":"「」を聴取いたします。 「羽ばたけ！ アントレーヌ」の開催","exchanges":[{"speaker":"くにば委員","kind":"質問","question":"こちらは私から１点だけ伺いたいです。最終チェックが入っているかというのを１点伺いたいのと、あとは、募集要項の出店ＮＧ項目のところに、４点もろもろ書いてあるのですが、その中に、出店なさるサービスや商品でトラブルが発生する可能性があるものを出店なさる場合にＮＧというのは記載されていないのです。私から申し上げたいのは以上です。以上、ご答弁をお願いします。","respondent":"山崎商業・ものづくり課長","answer":"そういう中で発生するトラブルも、いろいろな危機レベルを広げていくと、ものすごくたくさんあるのですが、本来、企業が企業活動として守るべきものに、企業側に瑕疵があれば、これは企業の瑕疵ということですから、区としてはそういった対応になりますし。","id":"exchange-001"},{"speaker":"くにば委員","kind":"確認","question":"今ご答弁があったような形で、基本的にはこちらの雑貨、商品を販売なさる方たちでしたら、それらの商品は全てチェックなさった上で、問題がないということを確認したものしか販売されない。それとも、先ほど後者のほうでおっしゃっていた、区がイベントとして行ったので、区として対応するという。そちらに関して２点、もう一度ご答弁をお願いします。","respondent":"山崎商業・ものづくり課長","answer":"それで、区のイベントで、区のかかわりで、例えば今回供する会場の何かのせいで少しトラブルが発生したような場合については、そういった事象を個別に考えて、区として補償の必要性といいますか、責任が発生するようなことがあれば。","id":"exchange-002"},{"speaker":"くにば委員","kind":"意見","question":"そうですね。おっしゃった形で、ＳＨＩＰは我々区民委員会でも視察させていただきましたけれども、非常にすばらしい施設で、こちらの「羽ばたけ！アントレーヌ」に関しても、いろいろな新しい起業家の方たちがチャレンジ、トライアルするいい機会。そういった中で、今おっしゃった形で、きちんと区のチェックが入っているという部分を聞いて安心しました。以上です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-003"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/826260?Template=document&Id=2854#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2019-01-01&TermEnd=2019-12-31"}],"sourceMeta":{"pages":0,"characters":6778,"voices":18}},{"id":"r01-20191203-7","meetingId":"r01-cm12","date":"2019年12月3日","dateIso":"2019-12-03","committee":"厚生委員会","time":"午前１０時００分～午前１１時５１分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を30件抜き出しています。","topics":[{"id":"topic-01","title":"品川区立東品川高齢者多世代交流支援施設（東品川ゆうゆうプラザ）運営事業者の選定","agenda":"品川区立東品川高齢者多世代交流支援施設（東品川ゆうゆうプラザ）運営事業者の選定","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"提案","question":"それからもう一つなのですけれども、２事業者のうち、なぜ福栄会が選ばれたのかというのがこれだとわからないのです。福栄会の選定理由というのは、福栄会がこういうところでの提案をされてきているので選ばれたということはわかるのですけれども、２事業者を比べてなぜ福栄会になったのかというところが、今回のここのところには全く出ていないので、そのところについて教えていただきたいと思います。","respondent":"宮尾高齢者地域支援課長","answer":"２番目の議決のスケジュールですが、この後、令和２年第１回の定例会において上程をさせていただいて、ご審議をいただく予定でおります。","id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"点数表なのですけれども、２事業者で、福栄会ともう一つ。どういう事業者だったのかという、そこら辺のところも、２つ来たわけですから、２つの中で福栄会がなぜ選ばれたのか。今日はここの中に、資料としては示されていないので、口頭でも結構ですから、ご説明をいただけたらと思います。それからもう一つ、選定委員会のメンバーも教えていただきたいと思います。","respondent":"宮尾高齢者地域支援課長","answer":"その後の選定会議は、委員長を福祉部長が務め、委員は、企画調整課長、福祉計画課長、そして私、高齢者地域支援課長が務めたです。","id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"募集要項は今でもホームページで見ることができるでしょうか。そういう点では、ここは選定というところで、そこのところはぜひ今度の議決のときでも結構ですので、示していただきたいということでお願いしたいと思いますけれども、いかがでしょうか。その書類というのは、もうこの選定の段階で出されているということで考えていいのでしょうか。その点についてもお聞かせください。","respondent":"宮尾高齢者地域支援課長","answer":"点数につきましては、こちらは区の方針でもありますけれども、応募団体の営業ですとか信用の保護などにも配慮するということで、こちらは遠慮させていただきたいと考えています。なお、今回応募があったもう１事業者ですが、特定非営利活動法人のワーカーズコープです。","id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"そうすると、提案の中には、指定管理者を受けるに当たって、事業計画書の中に職員体制とかそういうふうなところがしっかりと載ってくると思うのですけれども、この提案のところでは、職員体制とかはどの程度の職員でやるのかとかということがわかっているのであれば、職員体制、職種と人数についてお聞かせいただきたいと思います。","respondent":"宮尾高齢者地域支援課長","answer":"資格としては、介護福祉士、社会福祉士または介護支援専門員、もしくは保育士資格を所持している者というふうになっています。もう一人の職員が、介護福祉士または保育士資格の所持者です。それに加えまして、非常勤職員の採用を予定しているというふうになっています。","id":"exchange-004"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"最後に、先ほど事業計画書とかさまざま、指定管理者に必要な書類というのはこれから出てくるということでしたけれども、いつごろ出されるかということだけ教えてください。","respondent":"宮尾高齢者地域支援課長","answer":"開設から逆算をして、しっかり余裕を持って、我々もそれを受けとめて、話し合い、相談ができる期間を持った上でと考えています。具体的な期日につきましては、まだ現在では未定です。","id":"exchange-005"},{"speaker":"あべ委員","kind":"質問","question":"一方、裏面のほうの選定理由を見ますと、ではどこで差がつくのかなというと、品川区の諸政策について理解が深くとか、これまでの意向ですとか、これだったら、こういうところで選ばれるのであれば、これから先幾らプロポーザルをやっても、結局区内でこれまでやっていた、いつもおつき合いをしている法人ばかりが結局は選ばれてしまうということになるのではないかと思うのですが。","respondent":"宮尾高齢者地域支援課長","answer":"その中でも点数の詳しい中身については、こちらではあれですけれども、まず大きく差がついた点といたしましては、施設の設置目的を達成するために十分な能力を有しているかというところで、例としては大きく差がついているというところが挙げられたというところです。","id":"exchange-006"},{"speaker":"あべ委員","kind":"質問","question":"その部分で、これまでのワーカーズコープの仕事を見ていると、そんなに大きな差がつくというのは、私としては不思議だなという気がするのですが、質問を変えます。今、東品川も含めてゆうゆうが幾つあって、それぞれどこが運営しているか教えてください。","respondent":"宮尾高齢者地域支援課長","answer":"こちらが品川総合福祉センターに運営管理をお願いしております。そして、今年の３月にオープンをいたしました平塚につきましては、福栄会にお願いをしています。そして、今回東品川がまた同様に福栄会のほうにお願いをする予定です。","id":"exchange-007"},{"speaker":"あべ委員","kind":"質問","question":"指定管理者制度、先ほど鈴木ひろ子委員の質問にもありましたように、他区に準ずるぐらいのレベルでは、もっと情報公開をしていくべきだと思いますし、そのほうが区のためになると思います。といいますのは、また質問の方向が変わりますけれども、今福栄会に品川区からのＯＢの職員は何人いますか。","respondent":"大串福祉計画課長","answer":"今、福栄会のほうにＯＢということで行ってらっしゃるのはお二人です。","id":"exchange-008"},{"speaker":"あべ委員","kind":"質問","question":"幹部も含めてのお二人だと思います。ワーカーズコープのほうには多分いらっしゃらないかとは思います。選定のメンバーも区の現職の職員の方ですよね。そういった意味からも、指定管理者制度についての選定、あるいは選定委員会のメンバー、そして選定の手順、スケジュール等々についても、よりオープンにしていくことが区のためにもなるのではないかと思いますが、ここはご意見を伺いたいところです。","respondent":"大串福祉計画課長","answer":"ご指摘いただいた透明性等々、こういったところも重要な問題だとは認識をしておりますので、その辺については検討していければと考えています。","id":"exchange-009"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"国のほうもそういう方向を求めているというのもあると思うのです。指定管理者制度が始まって１５年以上経つのです。だから多分、福祉部全体として、点数は一切公開しないというものでもないのではないかなと思うのですけれど、そういう点では、ワーカーズコープと福栄会で、最終的なトータルの点数だけでも何点かということは、ここでお答えいただくということはできないでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういうところも含めてぜひご検討いただきたいということで、ご意見を申し上げておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"}]},{"id":"topic-02","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"渡部委員","kind":"確認","question":"右側の多職種連携システムの取り組みについて伺いますと、あらあら内容、こういうものなのだなというのはわかるのですが、整備状況はこれからだということなのだけれども、本当は基本的にきっとあれですよね、かかりつけ病院とかにかかったり、在支とかにお世話になっている方の１００％を目指すのだと思うのですが、同意とれた方というのは、さまざまな部分、訪問看護だろうが。","respondent":"大串福祉計画課長、寺嶋高齢者福祉課長","answer":"ブロックごとでの課題、対応、こういったものが出てきて、それが品川区全体として、これが広範に活用できれば一番いいのかなと考えているところです。それからもう１点は、ここの資料には具体な書き込みはないのですけれども、総合病院はまだなかなかアプローチがしづらいというか、ご説明はしているのですけれども、どちらかというとクリニック系のほうで。","id":"exchange-012"},{"speaker":"渡部委員","kind":"質問","question":"２点お伺いしたいのが、さっきの地域ケアブロック会議もそうなのですけれども、例えば医師会ですとか、歯科医師会ですとか、薬剤師会に入っていないそれぞれ病院とか薬局ですとか、区内に結構あると思うのですが、そういうところというのはどういうふうに連携をとられていくのか。逆にそういうところはせっかくですから、会のほうに所属していただいてというのも１つの手だと思うのです。","respondent":"大串福祉計画課長、寺嶋高齢者福祉課長","answer":"医師会加盟、非加盟といったところではなく、在宅医療、こういったものに取り組まれていらっしゃる方というところでお願いをしています。ただいまの内容で、１点まず追加しますと、実際に同意をいただいたキーパーソンの方が、医師会等々未加入の方のご利用があるという例も実際にはありまして、そのときは、もとよりうちの職員等が直接お邪魔をして、ご説明をして。","id":"exchange-013"},{"speaker":"渡部委員","kind":"質問","question":"そこの問題については、セキュリティー上もし見られますよと言ったら、セキュリティー上大丈夫ですかと聞こうと思ったのですが、そこまで考えてお答えいただいてありがとうあります。例えば大田区だったり、目黒区だったりした場合も、今課長にお話しいただいたような感じで、何らかの形で品川区はこういう仕組みをやっていますというアナウンスが入るのかどうなのかだけ最後にお聞きして終わります。","respondent":"寺嶋高齢者福祉課長","answer":"今はまだあまりにも始まったばかりで区内の事業所登録が少ないものですから、そこまで実際には手が回っていないところがあるのですけれども、検討課題としては認識しております。","id":"exchange-014"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"地域ケアブロック会議についてなのですけれども、これを見たときになかなかイメージがわかなくて、いろいろ介護保険制度推進委員会の議事録とかも見せていただいたのですけれども、そこのところでも委員から「イメージがつかめないため、何か具体的なイメージがあれば教えていただきたい」という意見が出されていて、その後で福祉計画課長が説明されているのですが。","respondent":"大串福祉計画課長","answer":"正直に申し上げて手探りな部分はあります。したがって、医師会の皆さん方にもご説明をさせていただきながらいろいろなご意見をいただく、あるいはまたこういった形で会議を開いて、皆さんからご意見をいただいた中でといったところです。","id":"exchange-015"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"４ブロックで８人。８人のブロックリーダーが集まって、区の担当の方々と一緒にこの問題を抽出し、分析、具体的な解決策を提案、決定できる場を、多分ブロック会議をするにあたり準備会議みたいなものをして、ブロック会議をやるということにしないと、ブロック会議というのもなかなかできないと思うのですけれども、そういうふうな形で進めるということになっていくのでしょうか。","respondent":"大串福祉計画課長","answer":"他区と比較してどうこうということではなく、まずは、例えばこちらの医療と介護の連携といったテーマ設定において、品川区の中での資源等々、こういったものも捉えた上で、より深い連携をしていくことが地域包括ケアの推進。","id":"exchange-016"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"多職種連携のシステムとは今までもっとあったような思いがしていたのですけれども、認知症の問題などにしても、いろいろと多職種連携のそういう仕組みというのは地区ケア会議しかなかったところに今回これがプラスという、そういうイメージでいいのでしょうか。他区は同じような形でされているのかどうか。他区の多職種連携とあわせてどうなのかというあたりも教えていただけたらと思います。","respondent":"寺嶋高齢者福祉課長","answer":"逆に言うと、職種という意味で言えば、例えば、場合によっては学校の関係者の方が入っていただいているとか、それから地域の方が入っていただいている場合が当然あるわけで、お呼びをして、その方について情報を持っている方、関与している方ということで入っていただき。","id":"exchange-017"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それは大事な部分もあるので、必要であれば把握しなくてはいけないという部分であると思うのですけれども、そういうふうにその人の収入状況まで全て把握できるような形というのが、プライバシーとかそういうふうな観点で気になった部分があったのですが、そこら辺の捉え方と、確認がとられているのかというとことを１つお聞かせいただきたいと思います。","respondent":"寺嶋高齢者福祉課長","answer":"私の説明の仕方がよくなかったようで、もし誤解があったら訂正したいのですけれども、システム開発をする中で、これまで高齢者福祉課の係の作業がそれぞれ独自のシステムとなっていたものを、共通する部分も多々ありますので、在宅介護支援システムという形で。","id":"exchange-018"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"わかりました。何か先ほどの説明だと、この方の保険料まで全部、その人が丸ごと見えてしまうようなそういう仕組みなのかなという思いがしていたのです。この方にとって、このグループで共有すべきものをアップして、それをみんなで共有できるというシステムだということなのですね。それともサービスを使っている方は皆さん登録してもらうということになるのか、そこの仕組みだけ教えてください。","respondent":"寺嶋高齢者福祉課長","answer":"ただし、実際の流れとしてどうなっているかというと、まず実際に要介護認定受けている方は１万５千人ぐらいいますけれども、そこの中から三千何名ということになっていますが、当然まだサービスは使っていないという方もいますし。","id":"exchange-019"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"先ほどの共有すべき情報なのですけれども、具体的にどのような情報を入れるのか。共有すべきではない情報もあるため、そのようなことの整理ということが介護保険制度推進委員会の中でも言われていたのです。具体的にどのような情報を入れるのか、共有すべきでない情報もあるというところなのですが、どのような情報を入れるかというのは、誰が判断をして情報を入れていくということになるのでしょうか。","respondent":"寺嶋高齢者福祉課長","answer":"今現在まだ完全に動いているというよりは、検証しながら進めているということもあるので、今現在が完成形というわけではないのですけれども、それぞれの関係者、医療系は医療系、介護系は介護系から情報をいただいて、それを区の中で一定程度精査した上で、相互に。","id":"exchange-020"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そうすると、この情報をアップするということに対しては、共有すべきでない情報というものを除いて、この情報だったらいいのではないかというふうな、共有する情報として設定するというところは、最終的には区が責任を持つということでいいということですか。","respondent":"寺嶋高齢者福祉課長","answer":"システムに関係しての責任は全て品川区にありますので、品川区が責任を持ってやっていきます。","id":"exchange-021"},{"speaker":"あべ委員","kind":"質問","question":"地域ケアブロック会議のほうなのですけれども、あくまでも医療者、あるいは専門家の人たちの顔合わせのためと考えてよろしいでしょうか。こういった方々も入ってもいいのかなと考えています。それから、今回これは、特に高齢者医療をイメージしているかと思うのですけれども、今後これが障害ですとかそうした形で別の医療に広げていくお考えはあるでしょうか。教えてください。","respondent":"大串福祉計画課長","answer":"どういう周知方法がいいのかといったことについても検討していただき、まずは専門職の中でご意見をいただければと考えています。","id":"exchange-022"},{"speaker":"あべ委員","kind":"質問","question":"これは行政によって、例えば大田区などはわりとそういったところを密に連携がとれている印象があるのですけれども、品川区でもこの地域ケアブロック会議というのが、１つの突破口と言ったらいいのでしょうか、これまでなかなか課題として進んでいなかったところがこれによって進んでいくという期待もしてよろしいのでしょうか。","respondent":"大串福祉計画課長","answer":"そういったお声を受けて、こういった機会を設置していくのも必要ではないかなと考えているところです。そういった意味では、少しでもこういった形で連携が深まっていければ、最終的には区民の福祉の向上につながるものではないかと考えているところです。","id":"exchange-023"},{"speaker":"あべ委員","kind":"確認","question":"多職種連携システムのところなのですけれども、この地域ケアブロック会議によって、関係が地域ごとにできていくということも、多職種連携システムを進めていく上での１つの土壌づくりと捉えていいのかということを１点お伺いします。それから、このシステムのほうのセキュリティーなのですけれども、これを一応確認させてください。それとも３千人分が全部見られるのかということを確認させてください。","respondent":"寺嶋高齢者福祉課長","answer":"地域ケアブロック会議の取り組みがこのシステムの連携の促進にというところですけれども、今システムのほうを担当している側としましては、登録者が増えていくことがまず一番の必須課題でありますので、そういう意味では、こういう地域ケアブロック会議等でご案内したり。","id":"exchange-024"},{"speaker":"あべ委員","kind":"質問","question":"そのときに、非常に効果が高くて、例えば医者の指示で水分補給などを日々やってもらうことによって、ＱＯＬがとても向上したというようなことを、確か医師会の先生から伺ったような気がしております。インセンティブがないとなかなかお願いだけでは、仕事が確実に増えるのは増えるので、どうなのでしょうか。","respondent":"寺嶋高齢者福祉課長","answer":"ただ、一番の弱点は簡単に言うと汎用性がなかった、広がらなかったというのでしょうか、お聞きするところ、それを実際に使っている医師会の医師もいまして、「私はもう東京都のほうで入れたので」と言って「この中で見られるならやるけれども。","id":"exchange-025"},{"speaker":"あべ委員","kind":"質問","question":"これまでの仕組みの延長ではなくて、また違うシステムだということですので、そこら辺もどういう意向がいいのかも含めて進めていただければと思います。すみません、このシステムを構築して運用する事業、これはどこが財源になっているのでしょうか。","respondent":"寺嶋高齢者福祉課長","answer":"ただ、一部なのですけれども、そのうち多職種連携にかかった、これは在宅介護支援システム全体で６億円弱なのですけれども、内訳として、多職種連携システムを付加したことで７,５００万円ぐらいがその内訳としては入っているのですが。","id":"exchange-026"},{"speaker":"あべ委員","kind":"質問","question":"このシステム自体も、品川区オリジナルのシステムと考えていいのでしょうか。そうすると、区をまたいだ病院とかクリニックというのは、ここには入ってきようがないという感じなのでしょうか。","respondent":"寺嶋高齢者福祉課長","answer":"このシステムにほかから入ってくるということは、もともと区の中で完結しておりますので、少し触れましたけれども、多職種連携システムはインターネット環境が整っていれば、仮想のサーバーのところでアクセスをするので。","id":"exchange-027"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"そういった、別にガイドラインとかがあるわけではなくて、この取り組みは区独自で医療と介護の連携というものの中で考えてきたものということでしょうか。","respondent":"大串福祉計画課長","answer":"地域支援事業の実施ということで、通知もいただいているところです。包括的支援事業といったところで、在宅医療・介護連携推進事業ということでつけられているものです。それに基づいて、介護と医療の連携については取り組んでいるといったところです。","id":"exchange-028"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"あべ委員","kind":"確認","question":"２点確認させてください。できればペーパーが欲しかったなと思うのですけれども、一応日にちのあるものなので、口頭だけだと。お願いできればと思います。それともう一つ、愛称はこれから募集するのですよね。事業者の方々の中で、確かサーフという愛称にしましたみたいなものを読んだことがあるのですけれども、一体そこはどういうかかわりになっているのでしょうか。","respondent":"築山障害者施策推進担当課長","answer":"事業者のほうで、サーフという愛称のほうを決めたというところがあったのですけれども、それは事業者のほうの思いといいますか、施設をつくって、区民の方が障害児者総合支援施設というのが言いづらいというのもあって。","id":"exchange-029"},{"speaker":"あべ委員","kind":"意見","question":"私が言うまでもないことではありますけれども、事前にここはお話をしておくべきところだったと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-030"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/461144?Template=document&Id=3552#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2019-01-01&TermEnd=2019-12-31"}],"sourceMeta":{"pages":0,"characters":38238,"voices":87}},{"id":"r01-20191203-8","meetingId":"r01-cm12","date":"2019年12月3日","dateIso":"2019-12-03","committee":"建設委員会","time":"午前１０時００分～午後 ０時０９分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を44件抜き出しています。","topics":[{"id":"topic-01","title":"はじめに、(1)「東京における都市計画道路の在り方に関する基本方針」の策定・公表","agenda":"はじめに、(1)「東京における都市計画道路の在り方に関する基本方針」の策定・公表","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"補助３０号線、補助２７号線、補助３１号線については、なぜこれらが存続になったのか、もう少しご説明いただきたいと思います。品川区は共同で検証したということですけれども、このあり方検証の過程で、補助３０号、補助２７号、補助３１号についてどのような意見を言ったのでしょうか。伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"全体の件数のうち品川区民の方の意見の数、そういう形での把握はしてございません。それから、補助３０号線、３１号線等については基本方針の６８ページになりますが、（１）既存道路による代替可能性というところで、検証がなされてあります。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問・要望","question":"特に補助３０号線、補助３１号線については、結構地域の方々がかなり、整備の必要性があるのかということで、具体的には廃止を求める請願を出されたこともありました。最後に、今回存続とされた道路については、現在、第四次優先整備路線の整備期間ですけれども、これが終わった後の１０年間で全て整備、着手するというお考えなのでしょうか。伺います。","respondent":"鈴木都市計画課長","answer":"その中に、このあり方で必要性が再度確認された路線として、どの部分が入ってくるかというのは、そのときの道路整備の状況と第五次事業化計画の検討の中で、全てが入ってくるのか、部分的に入ってくるのかというのは、またそのときの検討になろうかと考えています。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"パブリックコメントにもありますように、やはり整備をするべきではないと、廃止するべきだという意見も出ております。この具体化に当たっては、きちんともう一度、繰り返しになりますけれども住民の意見を交えた検証をするよう、求めていってほしいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"}]},{"id":"topic-02","title":"大井町駅周辺のまちづくり方針の策定および広町地区におけるまちづくりの検討状況","agenda":"大井町駅周辺のまちづくり方針の策定および広町地区におけるまちづくりの検討状況","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"まちづくりの方針なので、繰り返し言っておりますが、住民参加で進めていくべきだと思っているのですが、誰が、どこで、何を検討していくのか、それともこれから策定しますよという報告なのか、伺いたいと思います。まちづくり方針、策定項目（予定）とありますけれど、何を定めるのか、特に空間形成方針というのは一体何を指して、何を定めるものかということについても伺います。","respondent":"稲田都市開発課長","answer":"このまちづくり方針、現在私どものほうでいろいろと、たたき台を検討しながらやっているところです。ある程度まとまったところで、地区の関係者、町会や商店街その他等にお伺いしながら、意見を聞きながらまとめていきたいと。最終的には説明会をやっていければと考えています。","id":"exchange-004"},{"speaker":"安藤委員","kind":"質問","question":"地元関係者への説明というところですけれど、地元関係者の範囲とは何でしょうか。その説明、意見交換を行うおおよその想定時期を伺います。その後の地域の説明会ですが、その対象範囲はどこになるのでしょうか。その開催予定時期についても伺いたいと思います。","respondent":"稲田都市開発課長","answer":"これはまだ、方針自体は内部等でも協議していかないといけない段階ですので、それが終わった後に皆様方に示していければと考えています。４月以降の策定ということで、具体的にはまだで、来年度早々ぐらいにはつくっていければという予定で考えているところです。","id":"exchange-005"},{"speaker":"安藤委員","kind":"確認","question":"それと広町地区のほうの検討ですが、今、検討していると書いていますけれど、情報公開の資料によれば、昨年度は広町地区プロジェクト推進会議という名前で、９回開催されている会議体がありますけれども、それが検討体制ということでしょうか。確認させてください。この構成メンバーと、今年度は何回ぐらい開催されてきたのか、伺いたいと思います。","respondent":"稲田都市開発課長","answer":"方針のほう、町会、商店街等に話を聞きながら、またその後、それらの意見を聞いた上で地元説明会等をやっていきたいです。範囲におきましては、まだ決定していないところですが、影響する周辺地域と考えております。それから広町地区の検討です。","id":"exchange-006"},{"speaker":"安藤委員","kind":"質問","question":"それと広町地区のほうは、今後の予定ということで、ＪＲ東日本と方針合意をしていくということですけれど、方針合意の内容の中の、土地の利用区分、再開発等促進区を定める、あるいは土地区画整理事業の適用とありますけれど、これだけだとわからないので、もう少し、どういうことを合意しようとする内容なのか、伺います。","respondent":"稲田都市開発課長","answer":"広町地区のほうですけれども、今まではやはり敷地的にもこちら側がＪＲ東日本で、こちらからという雰囲気だったのですけれども、今後、一歩進んでしっかりと検討を進めなければいけないというところで、ここで詳細を決めるわけではないですけれども、駅側をＪＲ。","id":"exchange-007"},{"speaker":"安藤委員","kind":"質問","question":"その上で伺いますけれど、今回の土地再編の具体化をしようという動きだと思うのですけれど、これで一体何が確定されるのでしょうか。とりあえずひろまち保育園と四季劇場がある現在の区有地を、現在の区役所の隣にくっつけますよと、そういうところまでを決めるということなのでしょうか。伺いたいと思います。土地再編を行う時期というのは、いつごろを考えておられるのか、あわせて伺います。","respondent":"稲田都市開発課長","answer":"この部分をＪＲ東日本、この部分を区といった面積などにつきましては今後詳細に、また合意していくという形になろうかと思われます。いつごろかですが、この辺の検討が進んだ暁には、そういう合意を結んでいくものと予定しております。","id":"exchange-008"},{"speaker":"安藤委員","kind":"質問・要望","question":"ひろまち保育園の問題もありますし、その時期は結構大事なことだと思うのです。再編するかどうかということも含めて、私たちは早い段階から、庁舎の問題がかかわっているわけですから、住民参加、情報公開をしてやるべきだということをずっと言ってきました。それを全くやらないでここまで来ているわけです。一刻も早く住民参加の会議体をつくり、検討していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"吉田委員","kind":"質問","question":"大井町駅周辺のまちづくりのほうです。先ほどまだたたき台で、方針自体、区の内部でまだまだ検討しなければいけないというご答弁があったように思います。現段階で、区内部での検討には、どのような部署が参加し、どういうことについて検討されているのか、伺いたいと思います。","respondent":"稲田都市開発課長","answer":"この方針の検討状況ですが、我々都市開発課の中で検討している状況です。区の内部には関係部署がたくさんありますので、私たちがやっていることがある程度になってくれば、今後関係部署等に説明をして、ご意見を伺いながらやっていくと。","id":"exchange-010"},{"speaker":"吉田委員","kind":"質問・要望","question":"警察などの外部機関も当然だと思うのですけれど、そういうところへも、ということでしたが、その辺、現段階でこことここは必ずとか、考えていらっしゃるところがあったら教えていただきたいのですが。","respondent":"稲田都市開発課長","answer":"外部におきましては、東急電鉄、またりんかい線も走っていますので、そういうところにも話をしなければいけないということで、一部、話を切り出ししている部分もありますけれども、並行しながらやっていきたいと考えております。","id":"exchange-011"},{"speaker":"吉田委員","kind":"質問・要望","question":"わかりました。そうするとスケジュール的に、関係部署にきちんと案が固まる前に出して、それぞれのものを入れてたたき台をつくるとなると、その後の地元関係者への説明とか、そういうのは今段階でどれぐらいになるのか。そうならない段階でぜひ示していただきたいと思うのですけれど、その辺のスケジュール感といいますか、お考えがあったら教えてください。","respondent":"稲田都市開発課長","answer":"ただ、協議の期間等にもよりますので、一概には今のところ、まだ私たちの課の案をまとめる段階ですので、その辺で関係部署の意見を聞きながらやっていきたいというところで、来年４月以降、なるべく早い段階とは思っておりますが。","id":"exchange-012"},{"speaker":"吉田委員","kind":"質問・要望","question":"これは広町地区についても同じですけれど、今伺った範囲だと、やはり区内の検討自体が、まずここに関係している部署ということでしたが、これだけ大きなまちづくりとなりますと、福祉の面、保育の面、今後ここにお住まいになる方たちにとって、大きな問題になると思います。その後の説明の中で、ご意見として必ずそういうことも出てくると思うのです。これは是非ということで、要望にとどめします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"何点かお伺いします。そうなったとき、今、ＪＲ東日本と一緒にやっていこうという形をとっているわけではないですか。違う形が出てくるのだったら、いろいろと意見交換をした中でこういう形になったと、その理由をきちんと説明できるようにしておいてほしいと思います。それは要望しておきます。今、ご答弁をといってもなかなか、これからだという話になるでしょうから、要望だけしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"吉田委員","kind":"質問・要望","question":"庁内での検討の中に、ぜひ福祉とか保育の関係部署も入れてほしいという要望は言ったのですけれど、まちづくりに関係してくると、車いすをお使いの方、視覚障害の方とかさまざまな障害者には、私たちにわからない影響が出てくると思います。ぜひ地域への説明とか、地元関係者への説明の中にはそういう方々も入れて、ご意見がきちんと反映できる形での説明会の実施を要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"}]},{"id":"topic-03","title":"大崎駅東口第４地区まちづくりガイドライン（案）","agenda":"大崎駅東口第４地区まちづくりガイドライン（案）","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"連絡会の構成について伺いたいのですけれど、「など」とありますけれど、この中に開発協力企業も入っているのではないかと思いますけれど、そこも含めて「など」に当たるところを全て、教えていただきたいと思います。それと、まちづくり組織が２つあるということで、５ページに書いていますけれど、この２つの準備組合それぞれの範囲の地権者数、土地所有者、借地権者を伺いたいと思います。","respondent":"稲田都市開発課長","answer":"それから「など」ですけれども、マンションが２棟、間にあるのです。そこの管理組合の方もお呼びしています。３つ目のまちづくり補助金、いわゆるまちづくりに関係する補助金という形では、出ていないということです。","id":"exchange-016"},{"speaker":"安藤委員","kind":"確認","question":"フジタも入っているというふうに聞いたのですけれど、開発協力企業はその３社でいいのか、確認させてください。ここに書いている課題というのは、具体的に住民のほうから、住んでいる方々から、大変だということで区に何回も問い合わせですとか、意見が挙がったものなのか、そこはどうなのかお聞かせください。そこら辺についてはどうでしょうか。","respondent":"稲田都市開発課長","answer":"そういう中で、この資料の２ページの上のほうの地図を見ていただくとおわかりいただけますが、遅れてまちづくりに参加、この地区内でやってきたという意識もあるようでございまして、先ほど言ったようなこの地区の課題等も解決しながらやっていこうということで。","id":"exchange-017"},{"speaker":"安藤委員","kind":"質問・要望","question":"ですから、こういったガイドラインに沿って計画をつくっていくとか、段階的な整備をしていくとか書いていますし、市街地再開発事業を中心とした整備の推進ということで、再開発ありきという感じで、どうも街並みを誘導していくところは、私はいかがなものかと思うし、もちろん地元の人がまちづくりを考えて、勉強してやっているのでしょうけれど。","respondent":"稲田都市開発課長","answer":"先ほどの訂正です。西側の権利者数は１５名と言ったのですが、済みません、会員数が１５名ということでご理解ください。","id":"exchange-018"}]},{"id":"topic-04","title":"ゆうぽうと跡地開発計画におけるホール施設の賃借","agenda":"ゆうぽうと跡地開発計画におけるホール施設の賃借","exchanges":[{"speaker":"松本委員","kind":"質問","question":"賃料がある程度この辺だというのが確定していくのは、どのぐらいのタイミングになるとイメージすればよろしいでしょうか。","respondent":"稲田都市開発課長","answer":"着工前の予約契約というのを行うのですけれども、大体そこで絞り込んでいけるのではないかと。最終的には本契約を行うのですけれども、今の段階では、１億４,０００万円を上限として、賃料を考えていくというところでやっています。","id":"exchange-019"},{"speaker":"松本委員","kind":"質問・要望","question":"本契約締結時点で大分下がっているということは、今後あり得るのではないかと思っていますので、そこの部分はできるだけ、賃料の交渉部分は流動的に、ぎりぎりのところまで行っていただきたいというところは、要望として挙げします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"たけうち委員","kind":"質問","question":"今のと関連してくるのですけれど。これからなのかもしれないですけど、３０年間の中で、例えば１０年ごとに契約を見直すとか、何かそういう考え方といいますか、そういう内容を入れたりすることはできなかったのか。区がこれを借りるので、このホールの運営管理等は、指定管理、委託とかで行うことになるのでしょうか。","respondent":"稲田都市開発課長","answer":"それと運営の仕方ですが、まだどうやっていこうと決めてはおりませんで、今後、運営をどのようにしていくかというところも、区の中で検討していくところです。","id":"exchange-021"},{"speaker":"たけうち委員","kind":"質問・要望","question":"要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"教えていただきたいのですが、賃貸借面積は２,４００平米ですと。それでホールの面積が、今お伺いすると４００平米と１００平米で、合計５００平米です。そうすると、バックヤードがこれだけあるというのであれば、１億４,０００万円の中でどういうふうに分けているかわからないですけれど、バックヤードの賃貸借に割引とか、そういうものはあるのですか。そういうことは研究されているのですか。","respondent":"稲田都市開発課長","answer":"そういうもろもろありまして、ホールとそういうもので２,４００平米です。そういったバックヤード等は割引の対象になるかというお話ですが、現在この２,４００平米で１億４,０００万円という形での設定で、やっているところです。","id":"exchange-023"},{"speaker":"吉田委員","kind":"質問","question":"今のいろいろご意見を聞いていて、最終的に金額を決めて、金額の妥当性というのは総務委員会の所管になると思うのですけれど、経理課に渡すところまでは、ここの所管が最終的にやっていくという理解でよろしいでしょうか。","respondent":"稲田都市開発課長","answer":"総務委員会に行く部分につきましては、ちょっとまだ、行くかどうか、契約とかそういう話になってくるとそうなるのでしょうけれども、まだそこまで、どういう運営をするかという話もやっていかなければいけないということにつきまして、しばらくは私どものほうと。","id":"exchange-024"},{"speaker":"吉田委員","kind":"確認","question":"確認ですが、具体的なところまでは所管課でやっていくということで、よろしいのですよね。契約という話しで、その金額の妥当性となると、最終的には総務委員会の議題にあがるということで理解して、よろしいということですよね。","respondent":"稲田都市開発課長","answer":"今回、基本的な協定を結んで、ようやく契約というところで、考えているところです。その段階でどこがどう持つかというのは、いろいろな部署の関係がございまして、どこに絞っていくかというのは今後の課題です。","id":"exchange-025"},{"speaker":"安藤委員","kind":"質問・要望","question":"ホールの位置づけについて区はどのように考えていらっしゃるのか、伺いたいと思います。３点目としては要望ですけれど、区民利用の場合は予約の受付期間が若干早かったり、実質上優先するところも、区民集会所などではあると思うのですけれど、そういったことも考えていただけないかと思いますけれど、いかがでしょうか。","respondent":"稲田都市開発課長","answer":"今後、区民優先の申し込みなどにおきましては、運営方法をこれから考えていくところですので、その辺で検討していくというふうに考えております。","id":"exchange-026"}]},{"id":"topic-05","title":"第二戸越幹線整備工事（下水道本管立杭整備および上流部シールド）","agenda":"第二戸越幹線整備工事（下水道本管立杭整備および上流部シールド）","exchanges":[{"speaker":"石田（秀）委員","kind":"質問","question":"１点だけ。戸越幹線整備工事の完了時期だけ教えてほしいです。完成して、水は大丈夫ですよというのはいつが予定されているかだけ、教えてください。","respondent":"松本河川下水道課長","answer":"第二戸越幹線整備工事につきましては、現在令和６年度の完成を予定しております。","id":"exchange-027"}]},{"id":"topic-06","title":"土砂災害ハザードマップの作成および配布","agenda":"土砂災害ハザードマップの作成および配布","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"このハザードマップですが、ホームページなどにアップする予定はあるのでしょうか。それとこのマップの裏にいろいろありましたけれども、今、崖地の補修の補助制度があったと思うのですが、そちらの情報が載っていないように見えるのですが、そちらは載せたほうがいいのではないか、お知らせすべきではないかと思うのですけれど、いかがでしょうか。","respondent":"中島防災課長、長尾建築課長","answer":"擁壁の補修の補助に関する記載はこちらにしていないのですが、ホームページに合わせてなのか、周知の仕方については検討しますが、お伝えできるようにしてまいりたいと思っています。崖の改修工事の助成制度につきましては、今回ハザードマップを配布する箇所と完全に一致しているわけではございませんで、崖自体を所有されている方に対してご利用いただく制度ですので、こちらについては個別に。","id":"exchange-028"},{"speaker":"安藤委員","kind":"質問・要望","question":"実際に危ないと言われても、そういう制度があるということも知らない方もいると思うので、ぜひ工夫をして、お知らせいただきたいと思います。ホームページの件は了解いたしました。最後に避難情報緊急通知コールですけれど、これはとても大切な事業ではないかと思うのですけれど、現在の登録状況を伺わせてください。登録件数は何件か、実際に稼働された実績はあったのか、あわせてお願いします。","respondent":"中島防災課長","answer":"広報しながわの１１月１１日号にも掲載して、その後登録数は伸びているところですが、今、最新の数字がなくて申しわけございません。運用につきましては、この前の台風第１９号において、避難準備情報あるいは避難勧告等の場面で活用しています。","id":"exchange-029"},{"speaker":"安藤委員","kind":"質問・要望","question":"これはぜひ、有効な手段だと思いますので、対象区域への配布ということもありますが、できればこういった制度があるのですよという声がけも含めて、避難情報緊急通知コールの登録者を増やしていただく努力もしていただければと思います。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"それでこの前台風がありました。今後、台風などまた来るだろうから、それまでにどういうふうに周知なり、対処なり、避難勧告を早目に出すのはいいのです、どんどん避難してください、品川学園に行ってくださいというのは結構なのですが、ある程度決め事をしておかないと、また変な理解から危ないということになってしまうので、そこら辺だけ教えていただきたいと思います。","respondent":"中島防災課長","answer":"そういう形で、今回は対象を限定して周知をしていくところですが、日ごろから土砂災害に対する情報発信を、建築課とも連携しまして、周知などの決め事等含めて、誤解のないように努めてまいりたいと考えています。","id":"exchange-031"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"周知をよろしくお願いします。例えば別紙２を見て、最初にこの絵で「がけがくずれそうだ！集中豪雨があったときに崩れる可能性があります、可能性があるから緊急通知する、だから避難してください、というほうが、いきなり「くずれそうだ」というと、何か皆、崩れちゃうのみたいな感じになるのではないかと思っていて、言葉の使い方なのですが、そこに関してもしお考えがあれば教えていただきたいと思います。","respondent":"中島防災課長","answer":"今回、避難通知コール等の運用につきましては、やはり高齢者等避難開始から、避難勧告、避難指示という場面で使い分けていくところですが、区としましてはやはり現地での崖崩れの発生という前に、大雨警報あるいは土砂災害警戒情報ですとか、そういう気象情報を活用しまして。","id":"exchange-032"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"それはいいのです。早目でお願いします。周知をしていただいて、早目にしていただいて、それがハズレて、毎回うそつきのようになってもいいのです。それで結構です。ただ、あまりこういう、「がけがくずれそうだ！」というのは、変な誤解を与えるような気がしてならないのです。そこだけはちょっとお考えいただきたいという、これは要望にしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"たけうち委員","kind":"提案","question":"私は昨年の第３回定例会で、こうした浸水また高潮、土砂災害を想定した避難訓練をぜひ、今まで品川は地震だけしかやっていないので、これからはこういう形も多いので、ぜひやってもらいたいということを質問、提案しましたところ、災害対策担当部長から、「浸水、高潮および土砂災害を想定した避難訓練については、既に実施している避難誘導ワークショップ訓練や、区の風水害初動訓練に取り入れていくなど。","respondent":"中島防災課長","answer":"そのあたりは今回のしながわ防災学校でも、そういう講座等も検討していますので、そういう一連の流れでしっかりと、訓練を行っていけるように努めてまいりたいと思っています。","id":"exchange-034"},{"speaker":"松本委員","kind":"質問","question":"避難情報緊急通知コールのほうですけれども、私、きちんと把握できていなくて、メールのほうはわかりやすいというか、一斉に配信すればいいというのはわかるのですけれども、電話のコールのほうで登録している人がたくさんいる場合、これは仕組みとしては自動で電話がかかって、例えば電子音声か何かで、同じものがバッと流れていくのか、その仕組みをお伺いしてもよろしいでしょうか。","respondent":"中島防災課長","answer":"メールと電話の両方ご登録いただいた方に関しましては、最初にメールを送らせていただきまして、そこで受信確認ができましたら電話は行わない形になっております。メールの受信が何回か送って確認できない場合は、電話がかかるという仕組みになっております。","id":"exchange-035"},{"speaker":"松本委員","kind":"質問","question":"今、順次という言葉が出たかと思うのですが、順次ということは、電話についてはタイムラグがあり得るということでしょうか。","respondent":"中島防災課長","answer":"失礼いたしました。一斉で、電話をかけるようになっています。","id":"exchange-036"},{"speaker":"高橋（伸）副委員長","kind":"質問・要望","question":"ご説明ありがとうございました。１点だけ確認させていただきたいのですけれど、ハザードマップの配布予定期間が１２月９日月曜日からとなっていますけれども、今週、１２月７日土曜日に区内一斉防災訓練があると思うのですけれど、対象地区の避難所には、こういったハザードマップができましたとか、そういった啓発を事前にするのかどうか、お聞きしたいと思います。","respondent":"中島防災課長","answer":"今回の１２月７日の一斉防災訓練では、そのような周知を行う予定はございません。","id":"exchange-037"}]},{"id":"topic-07","title":"所管質問","agenda":"所管質問","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"１１月２９日の須貝議員の災害停電時の中高層マンション対策についてですが、非常用エレベーターや照明用の発電機の設置は義務づけているというご答弁でしたが、その義務づけの具体的な内容やその義務づけた発電機の発電量では何基のエレベーターがどれぐらいの時間動かせるもので、照明についてもどの規模の灯りをつけることが可能なものなのかなど、伺いたいと思います。","respondent":"長尾建築課長","answer":"所管質問に関連いたしまして、発電機設置の義務づけについて、配付いたしましたＡ４の資料で説明いたします。初めに１、建築基準法における義務づけについてです。","id":"exchange-038"},{"speaker":"安藤委員","kind":"質問","question":"停電時は基本的に区民避難所に避難してくださいというのが品川区の方針なのでしょうか。伺いたいと思います。それと最少作動時間の捉え方について、もう少しご説明いただければと思います。","respondent":"中島防災課長、長尾建築課長","answer":"本会議での答弁の繰り返しになるところもありますが、在宅避難ができる方は在宅避難していただきます。それが難しい場合には区民避難所等に避難をしていただきたいという考えを、区としては持っております。実際に計画される建物で、この最少作動時間以上の稼働ができるように任意で設定されている建物も、実際あります。","id":"exchange-039"},{"speaker":"安藤委員","kind":"質問","question":"在宅避難できる方は、在宅避難してくださいということですけれども、事実上、非常用の発電機で日常生活が送れるほどの電源ではないということが、この資料からも明らかだと思うのですけれど、区としては在宅避難できる方というのは、超高層にお住まいの方ですと、大体どれぐらいいらっしゃるとお考えなのか、考え方だけ伺いたいと思います。","respondent":"中島防災課長","answer":"定量的にお示しすることは難しいところですが、停電の期間でありますとかにも関係してくると思います。区としてはやはり備蓄、日ごろからの備えということを、しながわ防災ハンドブック等でも啓発しています。","id":"exchange-040"},{"speaker":"吉田委員","kind":"質問","question":"法定の最少作動時間というのは、例えば非常用照明だと３０分の間に避難、どういう行為が終了するだろうというか、その間にこういうことはできるはずということが想定されていると思うのです。エレベーターの場合も、６０分動けば大体の人は外に出られるのか、その辺の考え方を教えてください。","respondent":"長尾建築課長","answer":"非常用照明とか排煙設備というのは、その建物の中にいる方が安全に避難できるようにということで、３０分間というふうに設定されておりますので、各階のフロアにいらっしゃる方が避難する場合は、まず階段室に逃げて、階段室から地上階におり。","id":"exchange-041"},{"speaker":"吉田委員","kind":"質問","question":"そうすると住んでいる方たちの緊急避難というよりも、まずは消防活動ということで、でも割と住んでいらっしゃる方で、例えばうちのマンションはちゃんと非常用電源が備えられているからということで、安心されている方がいるかなと思うのですが、そういうことはやはり入居のとき、非常用のものは基本そういうものであってということは、きちんと説明されているというふうに理解してよろしいのでしょうか。","respondent":"長尾建築課長、稲田都市開発課長","answer":"任意で法定以上の能力を備えた非常用エレベーターを設けられた場合は、それを売りとして考えられている販売業者や事業者であれば、そういった説明もされているかと想像できます。今、任意という話も出ましたけれども、市街地再開発事業でやっているところの例をご紹介いたしますと、東京都の新しい都市づくりのための都市開発諸制度活用方針というものがありまして。","id":"exchange-042"},{"speaker":"吉田委員","kind":"質問・要望","question":"もちろん区ができることというのは限りがあると思いますけれども、その辺の情報提供が求められた場合はきちんとできるように、ぜひ考えていっていただきたいと思います。区民の方たちも関心が高まっていくと思うのです、自分のマンションはどうなのだろうかと。その辺はきちんと説明できるようにしておいていただけたらと思います。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-043"},{"speaker":"安藤委員","kind":"意見","question":"このご説明いただいた資料は建築基準法における義務づけということで、都市開発課長の答弁では、今はまたそれとは別に諸制度活用方針があって、３日間とどまれるよう、自立性が確保できるよう努めるという規定がありますというご紹介があったと思いますけれども、実際に区内の６０メートル以上というか超高層の建物、特にマンションで、こういう活用方針に従って実際に整備されているところは。","respondent":"稲田都市開発課長","answer":"どれだけかというところは把握しているものではございませんけれども、７２時間稼働させる非常用発電機を所有しているところは、武蔵小山等におきましてはありますし、ほかの地区でもそういうところがあるという状況です。","id":"exchange-044"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/248410?Template=document&Id=4280#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2019-01-01&TermEnd=2019-12-31"}],"sourceMeta":{"pages":0,"characters":36038,"voices":130}},{"id":"r01-20191203-9","meetingId":"r01-cm12","date":"2019年12月3日","dateIso":"2019-12-03","committee":"文教委員会","time":"午前１０時００分～午後 ２時３６分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を86件抜き出しています。","topics":[{"id":"topic-01","title":"旧三井文庫第二書庫の国登録文化財への答申","agenda":"旧三井文庫第二書庫の国登録文化財への答申","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"耐震上の問題があるということで、それは、どういった問題というか、耐震補強などをしなければいけないのか。そういったところを伺いたいのと、今後、国登録文化財となった後、どのようにしていくのか、今後の展開といいますか、伺いたいと思います。","respondent":"有馬庶務課長","answer":"ただし、この書庫の文化的な価値というのは、先ほども説明したとおり、壁でこの建物を支えているということが１つの特徴になっていますので、ここを耐震補強で周りを補強してしまうと、それ自体で、この文化的価値がなくなるということで。","id":"exchange-001"},{"speaker":"筒井委員","kind":"意見","question":"今後はそうした期間限定の公開の予定のようなご答弁がありましたけれども、今現在、防災倉庫として活用されているということで、そうした防災倉庫としての活用はやめて、公開的な施設にするのか、区民の皆さんが見られるような施設の運用にしていくのか。今わかる状況でお知らせいただければと思います。","respondent":"有馬庶務課長","answer":"今言ったように、若干、耐震性の問題もあるので、内部公開については期間限定みたいな対応をしていきたいと思っています。中に入っている防災の備蓄品、特に毛布ですとか、若干、食料が入っておりますけれど、それについては、現状、そのままにしておくつもりです。","id":"exchange-002"},{"speaker":"塚本委員","kind":"質問","question":"登録文化財になると、国からある程度、いろいろな支援があるのではないかと思うのですけれども、そういうものが、どういうものがあるのかというところを最初にお聞きするのと。そばに寄って行って、“おー”という感じだと思うのですけれど、その辺りの周辺整備みたいなことも、国の支援の中でできるところはあるのかどうか。周辺整備の可能性というものとか、考えみたいなものがあれば。","respondent":"有馬庶務課長","answer":"３６５日、人が入っていますので、そんな中で、あそこの公園もかつての国文学研究資料館のときから比べると大分明るくなったという評価は得ていますけれども、その中で、公園課ともまた協議しながら、どういう形がいいのかは検討していきたいと考えております。","id":"exchange-003"},{"speaker":"高橋（し）委員","kind":"意見","question":"それで、今、お話にもありましたけれど、何となく目立たないところがあるので、先ほどパネル等の話がありましたけれど、近くに寄っても、資料の裏にあるような、内部がわかるようなパネル等、解説を付けていただければいいのですが、簡単で結構なのですが、どんな感じのパネルにする予定か、もしわかればお願いします。","respondent":"有馬庶務課長","answer":"ただプレートがあって、何かそれだけで終わってしまうというのも、少し寂しいかとは思っていますので、またいろいろと検討していきたいと考えております。","id":"exchange-004"}]},{"id":"topic-02","title":"令和２年度入学希望申請の状況","agenda":"令和２年度入学希望申請の状況","exchanges":[{"speaker":"塚本委員","kind":"質問","question":"最初に、小学校、中学校ともに、受入枠なのですけれど、これは、前年度との比較は出ていないのですけど、それほど変わっていないということでいいのですか。","respondent":"篠田学務課長","answer":"基本的には、昨年度とほぼ変わっていないような状況です。若干、お子さんが増えている通学区域、あるいは減っている通学区域、それぞれありますが、基本的にはほぼ同じだとご覧いただければと思います。","id":"exchange-005"},{"speaker":"塚本委員","kind":"確認","question":"今回、通学区域が変わっていますよね。令和２年度から学事制度審議会の審議を経て、新たな通学区域で、というところで。それをちょっと確認させてください。","respondent":"篠田学務課長","answer":"八潮学園の受入枠に関してなのですけれども、今回、そういった形での対応ですので、本来であれば受入枠を変更するという形になってまいります。","id":"exchange-006"},{"speaker":"塚本委員","kind":"質問","question":"これは、どれぐらいの年数、そういう対応になりそうですか。いわゆる兄弟姉妹ということを考えると、上の子は八潮学園に入れたからいいのだけど、あるときから学区で、抽選というのはあるけれど、浜川小学校に戻るみたいな形になるわけですよね。そういうのは、どれぐらいの年数になるのでしょうか。","respondent":"篠田学務課長","answer":"兄弟枠というのが、学校の抽選にあたっては、優先順位が１番目に設定されてありますので、そういった部分も受け入れができるのかと考えますと、学校の改築が終わる、この先５年間ぐらいは、こういった動きが続くのかとは想定しているものです。","id":"exchange-007"},{"speaker":"のだて委員","kind":"質問","question":"年々、抽選校が増えているという状況で、小学校では３年連続抽選になっているのが１２校もあって、中学校もわりとあるということで、選びたくても選べないような状況になっているのかと思うのですが、その点について伺いたいと思います。","respondent":"篠田学務課長","answer":"学校選択の基本的な考え方ですけれども、まず受入枠の設定をするということで、受入枠はどういうふうに設定するかというと、先ほどもご説明したとおり、基本的には通学区域内のお子さんの数です。通学区域内の住民基本台帳人口が基本的に一番になります。","id":"exchange-008"},{"speaker":"のだて委員","kind":"質問","question":"人口が増えてきているので、受入枠が少なくなって、抽選校が増えているというお話でしたけれども、やはり結局、選べないということになると、入りたかったのに入れなかったということで、子どもが傷つくといったこともあるという気がするのですが、そういった抽選で入れなかった子どもへの影響というのはどのようにお考えでしょうか。","respondent":"篠田学務課長","answer":"あわせて、選ばれるということを各学校が考えて、学校もそれぞれ対応していくといったこともありますから、そういった意味で、学校選択というのは必要な制度だろうと考えて実施しています。","id":"exchange-009"},{"speaker":"のだて委員","kind":"質問・要望","question":"選べることが一番大切なのだというお話でしたけれども、今、実際に余裕がなくなってきて、選べなくなってきているということだと思うのです。そういったところで傷つく子どもたちもいるということで、共産党としてはかねてから、学校選択制というのはやめるべきだと言ってきましたので、その辺りも、制度変更をしたばかりですけれども、改めて考え直していただきたいと思いますが、いかがでしょうか。","respondent":"篠田学務課長","answer":"先ほど申し上げたとおり、学校選択制にはきちんとした意義があると思っていますので、現状としては、引き続き、この制度を続けていきたいと考えているところです。","id":"exchange-010"},{"speaker":"筒井委員","kind":"質問","question":"先ほど、抽選して、その結果があって落選された方は、小学校は１月中待機、中学校が２月中待機ということなのですけれど、これは、落選しても、必ずどこかの学校には入れるような仕組みにはなっているということなのでしょうか。","respondent":"篠田学務課長","answer":"ただ、それ以外の学校を希望された方で、抽選に外れた方については、その間、例えば私学に行かれる方が出たりすれば、抜けがあって、抽選で繰り上がっていくというようなことがあって、それで最終的に、小学校であれば１月末までお待ちいただいて。","id":"exchange-011"},{"speaker":"筒井委員","kind":"質問","question":"そうすると、通学区域の学校には必ず入れると。通学区域外の学校を希望していた方に対しては、“残念ながらあなたは通学区域の学校にしか入れません”というような通知をするということでよろしいのでしょうか。","respondent":"篠田学務課長","answer":"抽選に外れてしまった方に関しましては、その時点では、ご自身の通学区域の学校を指定した形で、就学指定通知を送らせていただくという形になります。それで、待機の間に繰り上がりがあれば、それを変更していくという形になるものです。","id":"exchange-012"},{"speaker":"横山委員","kind":"質問","question":"学校選択制見直しの経過措置と、通学区域見直しの経過措置というのが、今回あるかと思うのですけど、その辺りの状況を教えてください。無抽選受け入れという方もいらっしゃるのかと思うのですけれど、これは希望申請数の「増」というところになるのでしょうか。その辺りの状況も教えてください。","respondent":"篠田学務課長","answer":"今回、学事制度審議会の答申を受けまして、制度の変更、通学区域等を選択することについて制度変更を行いました。それで、経過措置ですけれども、基本的には、今年度と来年度の２か年にわたって行うというものです。","id":"exchange-013"},{"speaker":"横山委員","kind":"確認","question":"無抽選受け入れの質問なのですけれど、ちょっと私の質問がわかりづらかったのかもしれないのですが、希望申請数の「増」というところに入っているということでよろしいのでしょうか。確認をお願いします。","respondent":"篠田学務課長","answer":"失礼いたしました。そのとおりです。あくまで現在の通学区域と別の学校という形になりますと、そこの数字に計上されているという形になってあります。","id":"exchange-014"},{"speaker":"横山委員","kind":"質問・要望","question":"確認なのですけれども。それと、経過措置が今年と来年だけということになると思うのですけれども、いろいろと説明ですとか、わかりづらい部分というのが、変更の期間があるので、そのために経過措置というのが設定されているかと思うのですけれど、来年度までだというところや、今年度の、どういったお問い合わせなどあったのかというところが気になっていまして、その辺りの状況を教えていただきたいです。","respondent":"篠田学務課長","answer":"改めて、また今年度のような形で説明会等を行うという予定はございませんけれども、特に小学校から中学校に上がる際に、どうしても学校の先生方、担任の先生などに、どうなるのですかということをよく聞かれる保護者の方がいらっしゃると伺っており。","id":"exchange-015"},{"speaker":"せお委員","kind":"確認","question":"１点目は確認なのですけれど、特別支援学級などの希望者数というのは、また別の表になるのでしょうか。２点目は、去年、一昨年は入学者数とか、あと今年の希望者数も、毎年３０名前後のところで、浅間台小学校とか中延小学校とか上神明小学校とか、小規模の学校だと思うのですけれど、こういったところの、何か今後の展望、今後の予定などがありましたら、あればで結構なのですけれど、教えてください。","respondent":"篠田学務課長","answer":"それで、これまでも、例えばＩＣＴ推進校に指定しまして、お子さん全員にタブレットを配付するというような形ですとか、さまざまな支援をしてきているような状況がありますけれども、具体的に小規模校の場合には、一般論としては、やはり選択の中では小さい学校というのは。","id":"exchange-016"},{"speaker":"せお委員","kind":"質問・要望","question":"特別支援学級のほうは、結果だけでということですか。確認なのですけれど、このように申請状況など、途中経過などは出ずに、結果だけ出るということでよろしいのでしょうか。小規模校のほうは、なくしてほしいなどでは全くないのですけれど、やはりすごく新しいことを品川区はされているので、引き続き、そういった小規模校ならではのできることというのがあると思うのです。先ほどの１点だけ、お願いします。","respondent":"篠田学務課長、大関教育総合支援センター長","answer":"最終的には、年度当初、確定した数字をお知らせしたいと考えております。３月のぎりぎりまで、就学相談を重ね、個別に対応する中で、一番ご自宅から近い特別支援学級をお勧めはしておりますが、さまざまな事情等もご相談させていただきながら、直接ご希望の個別の学校見学もしていただいて。","id":"exchange-017"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"幾つかお伺いします。１つ目は、先ほど、中学校のほうの学区の変更の影響はあまりないということだったのですが、その辺りは、もう一回、確認なのですけれど、希望申請の中では特にないのでしょうか。それが２つ目。いわゆる、そういった意味での、特別支援学級の学区の変更というのですか、そういうことの可能性について確認したいのですけれど。","respondent":"大関教育総合支援センター長、篠田学務課長","answer":"特別支援学級のお問い合わせについてですが、どのような状態で、また学校が合理的配慮がどこまで可能かも踏まえながら、個別に相談していますので、必ずしも可能となるのか、あるいは最初から難しいのかということはなく。そういった動きを踏まえて、最終的に繰り上がりのぎりぎりの期限で、できるだけ多くのお子さんを入れるような対応もとっているところですので、今年度も引き続きそういったことを念頭に置いて対応してまいりたいと考えているところです。","id":"exchange-018"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"それぞれありがとうあります。例えば９０名という受け入れ枠のところを９９名とか、そういう形で転入者枠をとりつつ、いっぱいいっぱいまで受け入れていただいていると思いますけれども、そういったことを、ほかの希望の多い学校でも行っていただいて、ぜひご兄弟で一緒に通えるようなことを実現していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"}]},{"id":"topic-03","title":"令和２年度 品川区立学校教育職員採用候補者選考状況","agenda":"令和２年度 品川区立学校教育職員採用候補者選考状況","exchanges":[{"speaker":"筒井委員","kind":"質問","question":"申込者６１名で、今のところ内定者２名ということで、倍率２０倍というご答弁がありましたけれども、これはかなり狭き門だと思っているのですが、毎年このような状況なのでしょうか。","respondent":"工藤指導課長","answer":"今、区固有教員の配置人数に関しましては３０名を目途に行っているところでございまして、現状が２７名ですので、したがって、募集人員は３名となっています。ですので、それに対してということで、実際、約２０倍ということで、狭き門という現状ではあります。","id":"exchange-020"},{"speaker":"筒井委員","kind":"質問","question":"そうすると、区固有教員の３０名のうち２７名しかいないから、その残りの枠を埋めるために募集したという理解でよろしいのでしょうか。","respondent":"工藤指導課長","answer":"委員ご指摘のとおりです。","id":"exchange-021"},{"speaker":"塚本委員","kind":"質問","question":"３名の内定に至った段階で１名辞退と。一応、辞退がどういう理由だったかというのをお聞きしたいのです。内定から辞退というのは、これまでもそういうときがあって。後で辞めると言われて、その時点でわかるわけがないので難しいのですけれど、対象者をこの段階で９名にしているのはどういう考えなのかというのをお聞きしたい。","respondent":"工藤指導課長","answer":"実際には、第一次選考で合格者が２３名ですが、考え方としては、その約半数を呼ぶと。それで、半数を呼んだ場合には、例えば約１０名というときには、今回、募集定員が３名に対して３倍以上あるので、おおむね、その部分で、です。","id":"exchange-022"},{"speaker":"塚本委員","kind":"意見","question":"採用基準を下げてまで人数を充足したほうがいいのかとか、非常に難しいところではあるのですが、また欠員が１つ出てしまうので、その穴埋めというか、本来の定員をしっかりと確保できるように、今後ともよろしくお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-023"},{"speaker":"高橋（し）委員","kind":"質問","question":"免許の取得状況をお伺いしたいのですが、あまりたくさんの方だと大変なので、面接を受けた方ぐらいがもしわかれば。それから、今、人数として、来年度は１名の枠なのでしょうか。ですから、この方々のお仕事の状況からすれば、継続して、何人かまではというのは大変かもしれませんけれど、存在意義というのは大変大きなものだと考えていますので、その点についてもお伺いします。","respondent":"工藤指導課長","answer":"今後ですが、現状で言うと、見込みとしては１名というところの欠員がありますけれども、３０名に達した後というのは、さまざまなことを勘案しながら、またそれは検討していきたいと考えています。少なくとも現状は３０名を目途に、というところで考えているところではあります。","id":"exchange-024"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"東京都に期限付きの方や講師の方が合格されて、そのまま区内の小学校・中学校で勤務されている方もいらっしゃって、経験を活かして、それも学校で随分活躍されているとお聞きしているので、そういった点は、教育委員会の配慮という意味ではないのですが、ぜひ品川区で働いてくださいということを、そういった方々に勧奨していただけるといいかと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"}]},{"id":"topic-04","title":"品川区子ども読書活動推進計画（素案）およびパブリックコメントの実施","agenda":"品川区子ども読書活動推進計画（素案）およびパブリックコメントの実施","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"最初のあたりで、長期基本計画なども含んでというところ、生きる力を育むというところを含めて、今回の、本などを活用して、自ら主体的に思考し行動する人に育つというところになっているわけですけれども、生きる力というと、競争を勝ち抜いていくという感じをとても強く感じるのです。そこのところを伺いたいと思います。","respondent":"横山品川図書館長","answer":"ただ、情報環境が複雑になっているので、いろいろなデータや情報を自分の中で役立つものに変換する力が必要だということも一方で言えるというところで、「読書能力」と位置付けまして、双方をバランスよく身につけていく過程が「育つ」ということで考えていることが。","id":"exchange-026"},{"speaker":"のだて委員","kind":"提案","question":"計画の中に、これは２９ページにありますが、読書興味を持ち続けることができるような読書機会を提供していくということが書かれているのですが、これはなかなか難しいことかと思っておりまして、どういった形で、今、検討されているというか、イメージ、そういったところを伺えればと思います。","respondent":"横山品川図書館長","answer":"中高生のワークショップでこれから進めていくのですが、自分より下の世代の子どもたちがどうやったら読書をするようになるかというのを継続的に検討していくような場も設けていって、お互いに勧め合いを、世代を超えて行うような取り組みもしていきたいと考えているところです。","id":"exchange-027"},{"speaker":"のだて委員","kind":"質問・要望","question":"やはり興味がないとなかなか読み進んでいくということもできないと思いますので、そこのところをぜひ重視していただいて、取り組んでいただきたいと思います。困難を抱えている子どもたちも当然そうですし、本に興味がないと言ったら言い過ぎですけれど、なかなか読めない子どもたちへの支援というのですか、そういったことも必要だと思うのですけれども、その点ではどのようにお考えでしょうか。","respondent":"横山品川図書館長","answer":"これは、読書へ困難さを抱えたお子さんへの対応と同じように、図書館員それぞれが個別にその子に対峙するということも非常に大事ですし、一般的な、その子にわかりやすいような資料や向いている資料をご紹介する機会を増やすというような形でも。","id":"exchange-028"},{"speaker":"のだて委員","kind":"質問・要望","question":"今、言いましたこともぜひ重視していただいて、子どもの読書が進むようにしていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"１つだけ。そういった中で、もう一つ、広町の再開発の話が出ておりますけれども、それとは別に図書館という機能として、映画にもなっていますけれども、ニューヨーク公共図書館、これは私立なのですけれど、ああいった、図書館というよりも文化を広めていくような施設に関して、再開発するときに、そういった施設をということを、教育委員会として発言する機会などはあるのでしょうか。","respondent":"横山品川図書館長","answer":"私も、ニューヨーク公共図書館の映画については拝見しまして、非常に理想的なものだと思いますが、あれは規模もかなり違いますし、あそこが文化の機能をかなり重視している図書館ですので、理想形として、地域全体でそれを叶えられるような形に、区全体でできるように。","id":"exchange-030"},{"speaker":"高橋（し）委員","kind":"意見","question":"図書館としても、そういった配置の件については検討課題だというのは認識されているということですので、機会を見つけて、設置についてはうまくいくようにしていただければと思います。広町に関しては、そういったことを心に思っていただいているということがわかりましたので、ぜひ実現することを希望します。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-031"},{"speaker":"のだて委員","kind":"意見","question":"先ほど聞き忘れました。パブリックコメントの期間が大体２週間ぐらいになっておりますけれども、この期間を決定した理由と、最低でも１か月ぐらいあったほうがいいのではないかと思うのですが、いかがでしょう。","respondent":"横山品川図書館長","answer":"そういう意味では、終結にかかってきている時期でもありまして、年度内におさめるとして、最終の第５回の会議を設定すると、こちらの都合で申しわけないのですけれど、２週間とるのがぎりぎりという形になってしまいまして、年末年始を挟んでしまったというところがありまして。","id":"exchange-032"},{"speaker":"のだて委員","kind":"質問","question":"会議との関係でこうなったというお話でしたが、後ろが決まってしまっているということだと思うのですけれど、前が延びるということはできなかったのでしょうか。","respondent":"横山品川図書館長","answer":"２週間を目途として設定しているところがあったので、前というのがなかなか考えられなかったのと、あと、ご案内しましたように、事前のアンケートやワークショップ、あと専門家インタビューと、割り合い広いご意見をいただいている状況でもあったところだったので。","id":"exchange-033"},{"speaker":"のだて委員","kind":"質問・要望","question":"いろいろな専門家がワークショップをやって、話、意見を聞いているということでしたけれども、やはりこのパブリックコメントで初めて知る方もいらっしゃるので、ぜひパブリックコメントの期間を最低でも１か月設けるようにしていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"せお委員","kind":"質問","question":"１点だけ失礼します。５９ページに、策定委員会の名簿があるのですけれど、新しい５年間の計画では、こちらの委員の方々は変わらないということでしょうか。","respondent":"横山品川図書館長","answer":"こちらの名簿に載っている委員につきましては、あくまでも推進計画をつくるための委員の方で、これを運営するにあたっては、図書館サイドが実施主体として、各所管と連絡をとりながらやっていくような形になるかと思います。","id":"exchange-035"},{"speaker":"せお委員","kind":"質問","question":"策定委員会はこちらのメンバーで、これから開かれることはないということですか。","respondent":"横山品川図書館長","answer":"こちらは、５９ページにありますように策定するための委員会なので、令和元年６月１日から令和２年３月３１日までの期間の設定になっております。ですので、令和２年４月１日からの実行期間については、図書館が運営主体として各所と連絡を取り合って運営します。","id":"exchange-036"},{"speaker":"せお委員","kind":"質問","question":"こちらの委員の方を拝見していると、読むことに困難を抱えている当事者の方などはいらっしゃらないかなと思うのですが、この点はいかがでしょうか。","respondent":"横山品川図書館長","answer":"事務局で教育総合支援センターの指導主事に入っていただくとともに、教育総合支援センター長にもオブザーバーとして参加していただいて、特別支援のこと、ほかについて教えていただくような機会もございました。","id":"exchange-037"},{"speaker":"せお委員","kind":"意見","question":"どの場面も多分一緒だと思うのですけれど、例えば、視覚障害の方などが本を読むことに特に困難があると思いますので、そういった方々の当事者などを入れていただく。どの場面でも、どんな委員会などでもそうだと思うのですけれど、相互理解がやはりすごく必要だと思います。パブリックコメントの実施もすごくいい企画だと思っていますので、そういった委員の方を選ぶ際にも配慮いただけたらと思っています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-038"},{"speaker":"横山委員","kind":"質問・要望","question":"もしあれば、何か所ぐらいかというところを確認させてください。３点目なのですけれども、おはなし会ですか、開催日時がなかなか都合がつかないということであるのですけれども、これはいつであれば都合がよいというようなことが、もしわかっているのであれば教えていただきたいのと、そもそも忙しいので都合が合わないということなのかと思うのですけれど、もし詳細がわかりましたら教えてください。","respondent":"横山品川図書館長","answer":"一般的に忙しい方は、どんな時間でもというところが確かにあるので、その方たちへのアプローチをどのようにしていくかというのを、例えば子どものワークショップで出ていたのですけれど、インターネットに本やお話を配信してくれたら見るなどということがあるので。","id":"exchange-039"},{"speaker":"横山委員","kind":"提案","question":"ワークショップの内容はすごく興味深く拝見させていただきました。小学生もそうですけれども、中学生のそういった図書委員の、各学校での委員会等で出ている意見や提案など、そういったところも、ワークショップ等を含めて聞いていただきながら進めていただきたいと思うのですけれども、いかがでしょうか。","respondent":"横山品川図書館長","answer":"当事者が考えるのが一番有効なやり方だというところは認識しておりますので、そういう機会をつくりたいですし、もう少し進んで、学校図書館の図書委員が運営に参加できるような形で将来的には取り組んでいきたいと考えております。","id":"exchange-040"},{"speaker":"筒井委員","kind":"質問","question":"昨日の陳情審査でもありましたけれど、学校図書館のあり方とか司書の重要性などが話されました。鍵がかかっているところもあるとか、そういった話もありましたけれども、今後は開館していって、有効活用していこうというお考えなのでしょうか。学校図書館についてどのようなお考えなのか、お聞かせください。","respondent":"横山品川図書館長","answer":"本を読むだけではなく、いろいろな情報を活用して調べたり考えたり協議したりするような場に、将来的にはなっていくものと思い、そちらに向けての支援を進めていきたいと考えています。","id":"exchange-041"}]},{"id":"topic-05","title":"子どもの食の支援事業","agenda":"子どもの食の支援事業","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"申請するのが、電子申請フォームでやるということで、１８歳未満のお子さんをもっている家庭なので、ネットや携帯電話などを持っているとは思うのですけれども、万が一、持っていない家庭があった場合の申請方法、そういった対応について伺いたいと思います。実態把握のところで、アンケートを実施するということなのですが、どういった形でやられるのか、今の検討状況を伺えればと思います。","respondent":"三ッ橋子ども家庭支援課長","answer":"アンケートにつきましては、今、最終検討している段階ですけれども、実際のお困り事がどのような状況なのか、例えば就労支援、学習支援が必要な方に対して区の施策を展開していきたいと考えておりますので、その辺りのことを考えております。","id":"exchange-042"},{"speaker":"のだて委員","kind":"質問・要望","question":"申し込みのほうは連絡いただければというお話だったので、そういう対応をしますよということで、ぜひ周知していただきたいと思います。アンケートのほうでは、対象というのですか、ひとり親家庭、今回通知したところということになるのか。その辺りを伺いたいです。","respondent":"三ッ橋子ども家庭支援課長","answer":"食を届けたときにもアンケートを実施していくと考えております。","id":"exchange-043"},{"speaker":"塚本委員","kind":"質問","question":"最初に、寄附はどのぐらいの、どういう人たちか。人数とか、区内・区外とか、そういうところでの寄附の状況を聞きたいと思います。それと、金額的には大体お１人で平均どのぐらいのものが多いのかというようなことも伺いたいと思います。","respondent":"三ッ橋子ども家庭支援課長","answer":"こちらは総額に対する割合ですけれども、そのような状況になっておりまして、その金額が、３２０万円ぐらいが区外の方です。区内の方は８０万円強となっております。それから、１人の平均の金額なのですが、さまざまですので、１人平均幾らということは差し控えします。","id":"exchange-044"},{"speaker":"塚本委員","kind":"質問","question":"そうですね。それと、先ほど、申請で多数の場合は抽選ということなのですけれども、この金額で、１人当たり、人数の、抽選になる限界の決め方というのはどういう決め方なのでしょうか。応募状況によって、多少、申請日数が変わってきたりするのか、予定より多かったら少し枠を広げましょうか、といった余地を考えているのか、その辺りの考え方をお伺いしたいと思います。","respondent":"三ッ橋子ども家庭支援課長","answer":"人数です。区外の方は７２名、区内の方は３３名です。抽選の部分ですけれども、委員がおっしゃるように、できる限り、区といたしましては、応募された方に対して食品配送をしていきたいのですけれども、確かに限界がありますので、応募状況によって勘案したいと思います。","id":"exchange-045"},{"speaker":"塚本委員","kind":"質問","question":"なるべくその方向がいいのかと思います。食品のいわゆる流通のさせ方というか、仕入れはどういうふうになっているのでしたか。“こういうものが欲しい”という注文みたいな部分があるのかどうか。それから、仕入れなどというのは、どういうふうにかけるのかなどというところで、その辺りの食品の需要と供給の関係みたいなところをお伺いしたいと思います。","respondent":"三ッ橋子ども家庭支援課長","answer":"食品の内容ですけれども、こちらは、一人ひとりの状況を具体的に、その方の希望はとりません。書かせていただいたように、主食を中心に嗜好品ということを考えております。食品の調達は、今、区内企業を考えておりまして、そこと最終調整しています。","id":"exchange-046"},{"speaker":"横山委員","kind":"確認","question":"こちらは目標金額の３００万円を達成されたと思うのですけれども、どのぐらいで目標金額に達したのかというところを教えていただけたらと思います。確認なのですけれども、子ども食堂に１００万円ということなのですが、こちらはどのように使っていくのかというところ。今、検討はしていただいているかと思うのですけれども、その辺り、詳細を教えてください。","respondent":"三ッ橋子ども家庭支援課長","answer":"アンケートですが、確かに委員がおっしゃいますように、丁寧にアンケートについては考えていきたいところですけれども、この趣旨としては、食の支援に困っている方というのが一番基本にありますので、「食の支援に困っていますか」と聞いて。","id":"exchange-047"},{"speaker":"芹澤副委員長","kind":"質問・要望","question":"以前、この事業のご説明をいただいたときに、たしか来年、次年度以降もできればやりたいというようなお話だったと思うのですが、やるかどうかもまだ決まっていないところであれだと思うのですが、寄附していただいた方に対して何かしらの、“もし次もあればお願いします”みたいなアプローチができているのかを教えていただきたい。その３点、お願いいたします。","respondent":"三ッ橋子ども家庭支援課長","answer":"寄附の方に対する来年度のお知らせですけれども、今回のふるさと納税のガバメントクラウドファンディングについては結果の報告をしなければいけませんので、そのときに、「来年度以降も実施する場合には、よろしくお願いします」という部分は伝えていく予定です。","id":"exchange-048"},{"speaker":"高橋（し）委員","kind":"確認","question":"１つだけ。ふるさとチョイスでやられているのだと思うのですが、私はその仕組みに詳しくないもので。これは今、３００万円が４００万円になったのですが、最終的にふるさとチョイスに支払う手数料というのでしょうか、そういうものはお幾らになるのか確認いたします。","respondent":"三ッ橋子ども家庭支援課長","answer":"ふるさとチョイスへの手数料ですけれども、１０％です。","id":"exchange-049"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"手数料、わかりました。それで、４００万円以上集まったので、事業への活用を速やかに行っていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-050"}]},{"id":"topic-06","title":"ひとり親家庭住宅入居支援事業","agenda":"ひとり親家庭住宅入居支援事業","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"確認なのですが、住宅相談会は、初回保証料の助成との関係というのはあるのですか。チラシが、どういった形でお知らせされていくのかということと、今回の事業について予算額というのはどのぐらいになるのでしょうか。できるだけ多くの方に支援していっていただきたいと思うのですけれども、伺います。","respondent":"三ッ橋子ども家庭支援課長","answer":"住宅相談会と保証料の関係ですけれども、基本的には住宅相談会は住宅についての相談、ひとり親家庭に対する住宅相談ですので、ひとり親家庭住宅入居支援事業についての説明もいたしますけれども、そのほか、どういうところを探しているとか、本当に基本的な住宅相談をいたします。","id":"exchange-051"},{"speaker":"のだて委員","kind":"確認","question":"住宅相談会は、ここに参加しないと、初回保証料の助成とか、そういうものが受けられないわけではないというところの確認と、予算としては、初回保証料は７件ということで、これは新しく始めると思うので、実績などは多分ないのですよね。７件の根拠というのですか、そこのところを伺いたいのと、保証額というのは大体１０万円以内でおさまってくるのかというところも伺いたいと思います。","respondent":"三ッ橋子ども家庭支援課長","answer":"こちらの住宅相談会に参加しなくてもご相談はありまして、この住宅入居支援事業に対して、保証料の部分の助成は相談した上で、例えば窓口等々相談した上で助成してまいります。","id":"exchange-052"}]},{"id":"topic-07","title":"西五反田保育園病後児保育室の改築","agenda":"西五反田保育園病後児保育室の改築","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"工事内容で、「２方向避難の確保」というのがあるのですが、大体、保育園というのは確保されているのかと思っていたのですが、今までは確保されていなかったということなのか、そこのところを伺いたいと思います。安全面への配慮からのレイアウト変更というところも、大体どういった変更なのかというところを伺えればと思います。","respondent":"吉田保育施設調整担当課長","answer":"西五反田保育室の病後児保育室「どるふぃん」は、平成１２年に開室しております。その時点では、乳幼児健康支援一時預かりということで、その時点の基準を満たした建物でございました。","id":"exchange-053"},{"speaker":"のだて委員","kind":"質問・要望","question":"そうすると、２方向避難のところは、平成１２年に違う施設として開設されて、どこかのタイミングで病後児保育室に変わって、そこで既存不適格になって、今回改築するにあたって基準を満たすようにしていくということでよろしいのか、そこの確認をさせていただきたいと思います。","respondent":"吉田保育施設調整担当課長","answer":"つくった時点では、その時点の基準を満たしていたです。ただ、その後、保育園に関しては、保育室の基準の変更とかが多々ございまして、現在では２方向避難は必須となっておりますので、今回、改築にあたっては、基準を満たすように変更したです。","id":"exchange-054"},{"speaker":"のだて委員","kind":"質問・要望","question":"わかりました。それはぜひ安全確保のためにやっていっていただきたいと思います。これは関連してなのですが、ほかの保育園などで、そういった２方向避難の既存不適格の園というのはあるのでしょうか。","respondent":"吉田保育施設調整担当課長","answer":"保育室の全園において既存不適格があるかどうか、今、資料が手持ちにないところです。","id":"exchange-055"},{"speaker":"のだて委員","kind":"質問・要望","question":"今わからないということで、あるかないかもわからないということですか。既存不適格ということがあれば、安全面は細心の注意を払っていっていただきたいと思います。一時休室にするということなので、そこは周知をしっかりとしていただいて、利用されていた方が困らないようにしていただきたいと思います。","respondent":"佐藤保育課長","answer":"病後児保育室の２方向避難の関係ですが、ほかに西大井保育園と清水台保育園、２施設あるのですけれども、こちらは保育園の中にある一室を使っていますので、当然、２方向避難は確保されています。","id":"exchange-056"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"現在、病後児保育室なのですが、転用に向けた対応ということは、これは病児保育室と病後児保育室、両方になるのか。ちょっとその辺りもお願いします。病後児なので、あまり明るくてもあれですけれども、その辺りのレイアウトも配慮して改築していただきたいと思いますが、いかがでしょうか。","respondent":"吉田保育施設調整担当課長","answer":"内装、明るさ等につきましては、必要な明るさ等を確保しながら進めてまいりたいと考えています。","id":"exchange-057"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"議会の中でも病児保育の必要性が議論されて、区にも要望させていただいていると思いますので、その方向でお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-058"}]},{"id":"topic-08","title":"品川区第二期子ども・子育て支援事業計画（素案）","agenda":"品川区第二期子ども・子育て支援事業計画（素案）","exchanges":[{"speaker":"のだて委員","kind":"確認","question":"確認なのですが、保育園のところです。ひろまち保育園の閉園に伴う定員などもあると思うのですが、そういったところも含めて検討されているのかというところを伺いたい。見込みのところで、令和２年度から令和３年度になるときに、多分、どの地域も、５歳児と２歳児のところが結構、増加しているのですけれども、ここが特に増加している理由というか、何かあれば伺えればと思います。","respondent":"吉田保育施設調整担当課長","answer":"量の見込みを立てる際に、国からの算出の考え方というのが出ております。その中においては、例えば、都市開発部門との調整を含めて、よく十分な情報共有を図り、開発等の内容を勘案するようにという国からの指示も出ておりますので、開発の状況については含んでいるところです。","id":"exchange-059"},{"speaker":"のだて委員","kind":"質問・要望","question":"見込みの増加のところは、計算方法の問題なのかわからないのですけれど、令和２年度から令和３年度のところで、５歳児と２歳児のところがどの地域でも結構増加しているので、何か要因があるのかというところで伺ったのですが、もう一度ご答弁いただきたいと思います。実態は、全児童数で利用するわけではないと思うのです。","respondent":"吉田保育施設調整担当課長","answer":"量の見込みに対して、確保方策は努力目標ですので、そちらを確保することによって、必要な量に対して確保を頑張ります。それなので、過不足はゼロになるという考え方です。","id":"exchange-060"},{"speaker":"のだて委員","kind":"質問","question":"していくべきだと思うのですけれども、そこのところを伺いたいと思います。ニーズと確保のところは、すまいるスクールのところで伺ったのですけれども、要はゼロになるというところというよりは、確保するというのが、全児童数を確保する。そう言えばそうなのかもしれませんが、実態としては、利用する児童は全員ではないと思うので、この数値が適切なのかどうかと思うのですけれども、いかがでしょう。","respondent":"吉田保育施設調整担当課長","answer":"量の見込みの全児童数というのは、実際に利用している児童数、利用する方の全児童数ということで、その下がその内訳となっているところです。","id":"exchange-061"},{"speaker":"のだて委員","kind":"質問・要望","question":"すまいるスクールのほうは、これが実際に利用している数ということだったのですね。保育園のほうは国の計算でということだったのですが、やはり実際、区でも、希望しても入れない方はいらっしゃいますので、そこも含めて、この計算には入っているのかどうかわかりませんけれども、区の方針というのですか、考え方としては、含めてぜひ確保していっていただきたいと思うのですけれども、いかがでしょうか。","respondent":"吉田保育施設調整担当課長","answer":"子ども・子育て支援事業計画につきましては、昨年９月、国から、量の見込み等の算出のやり方等、マニュアルが出ております。それに沿って作業を進めているところです。そのため、それに沿った形で、区も対応しています。","id":"exchange-062"},{"speaker":"のだて委員","kind":"確認","question":"わかりました。国のやり方に沿っているということで。そうしたら、これは隠れ待機児童も入っているのかどうか、それを確認します。","respondent":"吉田保育施設調整担当課長","answer":"隠れ待機児童の捉え方があるとは思うのですけれど、認証保育所などは、２９ページ、３０ページで数値として、１項目としては周知はしています。","id":"exchange-063"},{"speaker":"のだて委員","kind":"意見","question":"今の答弁は、入っているという話だったのか、よくわからなかったのですが、やはり希望した子どもたちがしっかりと入っていけるということが重要だと思いますので、そういった対応をお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-064"},{"speaker":"筒井委員","kind":"質問","question":"子ども・子育て会議の委員についてなのですけれど、２０名いらっしゃいまして、この人選はどのようにして、どういう基準で選ばれているのかということと、あと公募区民の方が３名いらっしゃいますけれども、応募状況、何人ぐらいの方が手を挙げられて、結果、この３名になったのでしょうか。そうした委員のことについてお知らせください。","respondent":"吉田保育施設調整担当課長","answer":"第４期の選出にあたりましては、公募につきましては応募が４名ございまして、その際には、子ども・子育て会議に参加していただくための動機や思いを書いていただきまして、書類選考により、そのうち３名を選んだところです。","id":"exchange-065"},{"speaker":"筒井委員","kind":"意見","question":"今、学識経験者や、子ども・子育て支援に関する事業に従事する者、区内に住所を有する保護者、それぞれ人数の枠みたいなものがあるのですけれど、こういった基準、こうした人たちを呼ぶだとか、カテゴリーごとに何人だとかは、国の基準というのがあって、こうして選ばれたのか、それとも区独自で、こういうふうにしようということで判断されたのか、どちらなのでしょう。","respondent":"吉田保育施設調整担当課長","answer":"子ども・子育て支援法で、区でこのような子ども・子育て事業をやる場合、それから新しい保育園を建てたりするような場合、意見を聞く場を設けるという指示があります。","id":"exchange-066"},{"speaker":"筒井委員","kind":"質問","question":"具体的にどういう方を呼ぶかというのは、区の裁量ということでよろしいのでしょうか。","respondent":"吉田保育施設調整担当課長","answer":"先ほど申し上げました学識経験者であるとか、事業に従事する者というところで大きく分類しまして、その中で必要な、最大の効果があるような形での人選をしています。","id":"exchange-067"},{"speaker":"塚本委員","kind":"確認","question":"最初に確認ですけれど、２２ページの表で、１号認定、２号認定、３号認定とあって、一番下の３号認定のところ、０、１、２歳児・保育認定ですけれど、これは量の見込みと確保方策というのがあって、その下に内訳で、教育・保育施設、地域型保育事業、その他と。これは、下の内訳の３段、令和２年度から令和６年度まで、全部同じ数字になっているのはこれでいいのですか。どうでしょう。","respondent":"吉田保育施設調整担当課長","answer":"３号認定につきまして、特に教育・保育施設、地域型保育事業、その他のところが今後増えていくかどうかというのが見込めなかったところなので、今のところは令和２年度の形で、そのまま横引きしてあるところです。","id":"exchange-068"},{"speaker":"塚本委員","kind":"意見","question":"増えていく見込みが見通せなかったというのは、いまいち理解し得ないけれど、確保方策としては増えるわけですよね。量の見込みも増えるわけで、それでなぜ内訳が増えないのかというのが、整合性がないように見えるのですけれど、そういうことではないのかどうか。","respondent":"吉田保育施設調整担当課長","answer":"３号認定の教育・保育施設につきましては、令和２年度以降の数値が増えていくのが正しい形になります。２９ページ、３０ページにあります、これがもとの表になるのですけれども、この数値は、こちらにある数字が正しい形になりますので、２２ページの数字は至急、訂正いたします。","id":"exchange-069"},{"speaker":"塚本委員","kind":"質問・要望","question":"わかりました。増えない。要するに、教育・保育施設で、量の見込みの確保方策はそういう方向だというところが中心なのだろうと思っているのですけれども、そういう方針をとっているということの理由をお聞かせいただきたいというのが１つです。","respondent":"大澤保育支援課長","answer":"このような状況は今後も続くと思われまして、おっしゃるとおり、今後、地域型保育事業を増設する予定はございませんので、数値としてもゼロを見込んでおります。","id":"exchange-070"},{"speaker":"塚本委員","kind":"質問・要望","question":"保育士の皆さんが非常に大変そうだと。お伺いしたいのは、３月にまとめられた報告書のアンケートの中で、１０月に一応、幼児教育無償化が実施されるということは、もう既に決まっていたと思うのですが、ある程度、その辺りのことを加味した形での調査というのがなされているのかというのをお聞きしたいと思います。","respondent":"吉田保育施設調整担当課長、大澤保育支援課長","answer":"そのため、早い時期、来年もしくは中間年度の前にでも、もう一度、保育の量等の見直し等は行う必要もあるだろうと、子ども・子育て会議でも認識しています。保育士の処遇改善ですけれども、この間、区としては、賃金改善と宿舎借り上げ、インフルエンザ助成等をやっているところです。そういった保育士の処遇改善も、今後、継続していくしかないだろうとは思っています。","id":"exchange-071"},{"speaker":"横山委員","kind":"質問","question":"幾つかお伺いしてまいります。６０ページのしながわネウボラネットワークの部分なのですけれども、こちらは妊娠届のときの面談が増加しているということで、「今後は出産までの間の支援体制の検討を」というような記載があるのですけれども、妊娠届の際にどのようなご相談が多くて、妊娠から出産までというところで、どういう支援をお考えなのか、お聞かせいただけたらと思いました。お願いいたします。","respondent":"吉田保育施設調整担当課長、崎村児童相談担当課長","answer":"申しわけございません。しながわネウボラネットワークの1)、それから3)の産後ケア事業につきましては、保健センターの所管になる部分ですので、細かい数値等は持ち合わせていないところです。今後の子育て世代に対する家事支援のあり方という部分につきましては、今の産後の家事育児支援について順調に利用者数も伸びておりますので、これは現在が６か月までとなっておりまして、また、どうしても育児困難の方向けには。","id":"exchange-072"},{"speaker":"横山委員","kind":"確認","question":"５８ページなのですけれども、民間の活力、民間事業者の参入促進ということで、大分、待機児童も解消して、区で大変頑張っていただいていると思うのですけれど、株式会社の数がやはり急増しているようなところで、例えば今後、児童相談所の設置にあたって、またこの計画も見直したいというような時期が訪れるのかと思うのですけれども、どういった時期、今の設置予定というところで。","respondent":"二ノ宮児童相談所移管担当課長","answer":"他方で、子ども・子育て支援法につきましては大都市特例という規定はございませんので、児童相談所の設置をもって、こちらの事業計画を変更するというのは、直接的には結びついていないと考えております。","id":"exchange-073"},{"speaker":"高橋（し）委員","kind":"質問","question":"そういう認識。教育・保育施設を増やしていくという確保方策だと理解させていただいてよろしいでしょうかということが１つ。それから、オアシスルームの利用者が非常に多いということなのですけれども、そちらの利用実績の上昇に関する今後の対応はどのようにお考えでしょうか。","respondent":"吉田保育施設調整担当課長、大澤保育支援課長","answer":"委員ご指摘のとおり、教育・保育施設につきましては、今後、増えていく方向で、数値は書き改めるのと、パブリックコメントにおいての資料も差し替えます。オアシスルームにつきましては、今後、増設の方向で検討してまいります。","id":"exchange-074"}]},{"id":"topic-09","title":"ぷりすくーる西五反田","agenda":"ぷりすくーる西五反田","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"今回、認定こども園化することによって、どういったことが変わってくるのかということを伺いたいのと、今、いろいろと調整中ということでしたが、職員の方や、あとは子どもや保護者の方にとっての変更点というか、そこを伺えればと思います。","respondent":"吉田保育施設調整担当課長","answer":"教育方針につきましても、現行のものを引き継いでいけるような形での仕組みを、福栄会でも準備するような形をとりまして、現在のぷりすくーる西五反田の教育方針が、次の、運営母体は新しく社会福祉法人になったとしても、そのまま引き継いでいけるようなことを、今。","id":"exchange-075"},{"speaker":"のだて委員","kind":"質問","question":"そうすると、子どもや保護者の方への変更点というのは特にないということでいいのかということと、ＮＰＯから社会福祉法人に事業を移行するということで、それは職員も一緒に移動するということなのか、そこのところをお伺いいたします。","respondent":"吉田保育施設調整担当課長","answer":"その辺りの解決が、なかなか長い期間、１年間とかをかけてやらなければならないところもありますので、保育士はそのまま引き継げるよう、それで質を維持して次につなげていきたいと、今のところ進めているところです。","id":"exchange-076"},{"speaker":"のだて委員","kind":"質問・要望","question":"保育士は引き継ぐということで、やはり、いろいろと変わると保育の質も悪くなると思いますので、それはそれで進めていただきたいと思います。そうすると、今回、社会福祉法人福栄会に移行していくということで、福栄会は保育園というのは今までやられたことはあるのかどうか。そこのところを伺いたいのと、認定こども園化されることで、保育料とか、そういった面の変更もないということなのでしょうか。","respondent":"吉田保育施設調整担当課長","answer":"認定こども園における保育料ですが、まだ認定こども園化における事業が２０２４年を目途としておりますので、金額等についてはどうとも言える段階にはまだ来ていないところです。","id":"exchange-077"},{"speaker":"のだて委員","kind":"質問","question":"そうすると、社会福祉法人運営になる段階では認定こども園とならないので、そこまでは保護者の負担は変わらないということですね。わかりました。そこで、今現在は指定管理者でやって、委託していると思うのですけれども、その期限が終わったところだと思うのですが、そこで社会福祉法人立にしていくというスケジュールだと思うのですけれど、そうした理由、経緯を伺いたいと思います。","respondent":"吉田保育施設調整担当課長","answer":"園庭の確保などのところにつきましては、まだ今後調整を図らなければならない部分もありますので、社会福祉法人になったからといって、すぐに認定こども園となるというわけでは、今のところも予定しておりません。","id":"exchange-078"},{"speaker":"のだて委員","kind":"質問","question":"課題はほかにもあるというお話だったのですが、その課題の解決の見通しというのですか、解決できそうなのかというところを伺いたい。","respondent":"吉田保育施設調整担当課長","answer":"指定管理の期間において、区がやるべきことにつきましては、区が十分、必要な対応をしていくことで、解決に導けていけたらと考えておりますが、認定こども園化した後につきましては、今度は法人立になり、法人の話になります。","id":"exchange-079"},{"speaker":"塚本委員","kind":"確認","question":"認定こども園化にあたってどうなっていくのかという。それで、先のことだからということではありましたけれど、普通に考えると、今までの品川区の条例によって定められていた施設から、国の法律によって認可される認定こども園として、幼児教育無償化の対象施設となるし、０、１、２歳に関して言えば、認可施設としての、品川区の保育料が所得に応じて決まっているじゃないですか。","respondent":"吉田保育施設調整担当課長","answer":"言い方が不明瞭で申しわけございませんでした。１０月からの無償化のところにおきまして、認可外保育施設も含めまして、無償化の対象になっているところもありますので、その制度が続いている限りはそのような対応になります。","id":"exchange-080"},{"speaker":"塚本委員","kind":"質問","question":"今いる人たち、スタッフが中心となってやっていくのか、新たな社会福祉法人で、またそこは何かしらの検討委員会みたいなものをつくって、議論する場をつくってやっていくのか。そのようなことについて、現状で見えている部分というものがあれば教えてください。","respondent":"吉田保育施設調整担当課長","answer":"それで、認定こども園はその後、何年かかけてというのはありますけれども、またそこに肉づけをするような形で、また発展的な意味で、よりよい認定こども園化を目指していければと、今は予定しています。","id":"exchange-081"},{"speaker":"高橋（し）委員","kind":"質問","question":"それで、社会福祉法人ではないから認定こども園にできないという理由に関しては、先ほどもありましたように、ほかのハード面の問題等もあったので、ここの１文は、ＮＰＯ法人子育て品川は社会福祉事業をやっているということと、あと社会福祉法人認可が、だからといってできないというのは、文脈的にあれかと思ったのですが、まず、そこはどうでしょうか。","respondent":"吉田保育施設調整担当課長","answer":"その点が社会福祉法人になれないという最も顕著なところでございまして、それがあるので、このＮＰＯがそのまま社会福祉法人になれないというところの説明が、この資料の２になります。","id":"exchange-082"},{"speaker":"高橋（し）委員","kind":"質問","question":"タイムスケジュールのところで、先ほど法人立になるとおっしゃった部分があるのですけれど、今、ＮＰＯが今後２年、指定管理をやって、その後、社会福祉法人福栄会にどういう形で移るのか。指定管理を変更するということですけれども、先ほどのお話の中で、その後、法人立になるということは、区立ではなくなるという意味でおっしゃったのでしょうか。","respondent":"吉田保育施設調整担当課長","answer":"２０２４年になりますと、今の予定では、そこで認定こども園化を目指します。それで、今度は社会福祉法人立の認定こども園と考えておりますので、ここで初めて社会福祉法人立の施設となる予定です。","id":"exchange-083"},{"speaker":"高橋（し）委員","kind":"質問","question":"それから２つ目は、そもそも５年の指定管理の予定だったのが２年ということですので、その点について、もちろん指定管理の議案が議会に出てきて、議会でどうするかという話の部分になってしまいますが、ＮＰＯの中では事業が移るとしても、３年分の指定管理に関しての、ＮＰＯとしての契約期間を短くされてしまうという部分があるので、その点について、何というのですか、何らかのマイナスというか。","respondent":"吉田保育施設調整担当課長","answer":"基本的にはＮＰＯと社会福祉法人との間の話になりまして、区としては、調整としてそれに顔を出すという形になりますので、主体的に話し合うのは、ＮＰＯと社会福祉法人の間で、それについて問題があったら、いろいろな法律面での解釈だとか。","id":"exchange-084"}]},{"id":"topic-10","title":"その他","agenda":"その他","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"田中議員の体罰の質問のところで、児童をたたいたり、廊下に立たせたりという事例があるということで、そういった声が届いている中で、今後、調査などは行っていくのか、また、そういった事例を区でつかんでいるのか、伺いたいと思います。","respondent":"工藤指導課長","answer":"２つご質問をいただきました。その事例をつかんでいるかどうかということに関しましては、ご指摘の事例が、いつ、どの学校で起きたのかという情報がない段階ですので、それについては把握しているかどうかという判別ができないと考えるところです。","id":"exchange-085"},{"speaker":"のだて委員","kind":"確認","question":"判別ができないというお話だったのですけれど、この間の体罰に関する報告の中で、たたくとか、廊下に立たせるといった事例というのは報告されていないのかどうかを確認します。","respondent":"工藤指導課長","answer":"いわゆる体罰関連の行為でいきますと、例えば、東京都教育委員会が示している体罰関連行為のガイドラインに示されているものの中には、立たせるという行為に関しては、記載は２か所あります。","id":"exchange-086"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/810051?Template=document&Id=4988#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2019-01-01&TermEnd=2019-12-31"}],"sourceMeta":{"pages":0,"characters":61273,"voices":246}},{"id":"r01-20191203-5","meetingId":"r01-cm12","date":"2019年12月3日","dateIso":"2019-12-03","committee":"総務委員会","time":"午前１０時００分～午前１１時５９分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を25件抜き出しています。","topics":[{"id":"topic-01","title":"品川区長期基本計画の策定状況","agenda":"品川区長期基本計画の策定状況","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"やはり、この８回ないし約１年間で審議をするのは無理があるなと思います。質問ですけれども、パブリックコメントについては１８２人の方からご意見が寄せられたわけですから、いわゆる広報で返答するのではなく、お１人お１人に区の意見を返信して、お寄せいただいたご意見に対応することが最低限必要だと思いますので、その辺について質問をしたいと思います。","respondent":"柏原企画調整課長","answer":"これまで８回、策定委員会ということで、いろいろな方、区の関係団体であったり、公募区民の方々であったり、議会の方々も含めてご議論いただいたと私どもとしては認識をしているところでございまして、そういった議論の中で練り上げられたといいますか。","id":"exchange-001"},{"speaker":"中塚委員","kind":"質問・要望","question":"連絡先がわからない方には返事はしようがないとは思いますけれども、連絡先がわかる人にとっては返事をすべきだと思いますので、この点、もう一度伺いたいと思います。区もこうやって区の意見を述べているわけですから、広報しながわでまとまって要約を示すという形ではなく、連絡先がわかる方については、返事をすべきだと思いますので、改めて伺いたいと思います。質問は１点だけです。","respondent":"柏原企画調整課長","answer":"ホームページにはもうこの形でほぼ原文、個人が特定できない状態にはいたしますけれども、この状態でホームページで公開して、区の考え方をお示しさせていただきたいと思ってありますので、パブリックコメントの返事といいますか、考え方につきましては。","id":"exchange-002"},{"speaker":"田中委員","kind":"質問・要望","question":"要望なんですけれども、パブリックコメント前に住民への説明会を開けるような、スケジュールの段階で住民説明会の日程を今後は取り入れてほしいと強く要望したいですし、そこについて、ちょっと見解を伺いたいと思います。","respondent":"柏原企画調整課長","answer":"全体でこれも１年間かけて、内部の検討活動に２年以上かけてやっているところもございまして、あまり長い時間をかけるといった計画のつくり方は、関連する方々が多いというところもありますし、長く時間をかければいいというものではないかなと思いますので。","id":"exchange-003"},{"speaker":"田中委員","kind":"質問・要望","question":"区民生活にかかわることなので、ぜひ住民の方たちがわかる説明会を今後はスケジュールの予定に取り入れてほしいと要望いたします。そしてパブリックコメントに寄せられた意見の反映なのですけれども、庁内で共有しているので個々に反映できるということでいいのですか。確認をさせていただきたいと思います。ヤングケアラーの部分は具体的施策に取り入れてほしいということを要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"西本委員","kind":"質問・要望","question":"その際にまた作業的にはどういう作業が考えられるのかということ。多分難しいと思います。日本全体で見れば人口減少ですから、そうなってくると品川区に今は流入してこられる方はいらっしゃるので増えていきますけれども全体の目で見たら、こんなに人口増えていくのというようなところがちょっと私はこの分析に、不安要素があるかなと思っているのですが、その辺のご見解をお聞きしたいと思います。","respondent":"柏原企画調整課長","answer":"前回の計画は１０年の計画で、中間の５年ということで一つ目安をとっておったところですが、一つこの長期基本計画が細かい内容ではなくて、施策の方向性、考え方を示すというところの長期基本計画ですから。","id":"exchange-005"},{"speaker":"西本委員","kind":"質問・要望","question":"万遍なくこれがいいというのは確かに行政側から出す長期基本計画については万遍なくという形なのでしょうが、ただもう少し希望としては、ここだけは品川区は絶対やっていくぞというような、それが教育なのか、福祉なのか、住宅政策なのかといういろいろなテーマはあるにせよ、もう少し特徴を踏まえた形で実施計画をするにも、あとは数値目標を掲げていくにもしていただけたら。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"須貝委員","kind":"意見","question":"内容は個々別々ですが、それぞれの人がやはり区に対して、例えば職員の皆さん、区長、副区長はじめさまざまな部長、課長、皆さんと専門分野のことでもやはり話を聞いてほしいというのが、本当にまだ少ない人数ですけれども、寄せられた意見ですがこれだけあるのかなと。本来ならやはり評価してほしい施策もありますし、今までやってきた事業で、こういうことはよかったよと。意見を述べさせていただきました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-007"}]},{"id":"topic-02","title":"台風１９号被害に伴う山北町、早川町への見舞金","agenda":"台風１９号被害に伴う山北町、早川町への見舞金","exchanges":[{"speaker":"中塚委員","kind":"意見","question":"見舞金にかかわって、台風１９号は本当に各地に被害があって、品川区から職員の派遣はどういう状況なのかあわせてご報告いただけますか。","respondent":"黒田人事課長","answer":"１９号のほうでは、こちらは対口支援組織とは別でございまして、二十三区の清掃関係の課長会のほうの要請を受けて、廃棄物処理ということで、千葉県の鋸南町でありますとか、世田谷区、埼玉県の東松山市に清掃の廃棄物処理の支援のほうで職員を派遣しているものです。","id":"exchange-008"},{"speaker":"西本委員","kind":"質問","question":"見舞金というのはわかりました。今、どういう状況なのかなと思うのです。復興が大分進まれているのか、あと何か必要なこととか、何かお困りになっていることとかという、直後よりもいろいろ出てくると思うのです。それはいかがですか。","respondent":"立川総務課長","answer":"被害状況の説明をもうちょっと詳しくお話しいたしますと、公共施設等につきましては、町営のオートキャンプ場のふれあいビレッジに土砂が流入いたしまして、これは復旧未定です。","id":"exchange-009"},{"speaker":"西本委員","kind":"質問","question":"まだまだ復旧はしていない状況だなというのがわかりました。ここは施設を利用してこちらから宿泊したりという何か交流を図っていると思うのですが、それに対しての品川区民への周知といいますか、いつから復旧できるとか、できないとか、何かいろいろ報告しないといけないと思うのですが、それはいかがですか。","respondent":"立川総務課長","answer":"こちらは地域活動課のほうで、ふれあい交流、ふるさと交流ということで事業を実施しておりますので、詳しいことはまだ聞いていないところですので、こういうご質問があったということで所管課のほうに伝えたいと思います。","id":"exchange-010"},{"speaker":"須貝委員","kind":"質問","question":"山北町、早川町に見舞金はわかるのですが、今、品川区でも災害見舞金というのをそれぞれ住民の皆様に各個別に支給する事業があると思うのですが、その辺はどのぐらい充実されているのですか。火災とか災害とか、交通事故やさまざまあると思うのですが、ちょっと参考のために教えてください。","respondent":"立川総務課長","answer":"所管が違いますので、お答えは控えします。","id":"exchange-011"}]},{"id":"topic-03","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"質問と意見です。品川区民の寄附先ということで、寄附額が多い自治体が紹介されておりますが、返礼品に何か特徴があるのか、どんなふうに区は把握というのか、見ているのか、そこを質問したいと思います。ただ、実態はもうネットショッピングといいますか、肉や魚を上手に購入するといいますか、制度と実態があまりにも乖離していると考えています。質問だけお願いいたします。","respondent":"伊東税務課長","answer":"ご存じかと思いますけれども、上位のところに関しては、先ほどちょっとネットショッピング的な言葉もございましたけれども、まさにそのとおりでございまして、全国各地の特産品を取りそろえて、１,０００種類とかいうようなキャッチコピーもありましたが、そういうもので。","id":"exchange-012"},{"speaker":"田中委員","kind":"質問・要望","question":"各所管課の取組みの状況をもしご説明できるようでしたらしていただきたいと思います。もう１点が、今年度の流出額の見込み額がこれだけ増えている理由を教えていただければと思うのですけれども。","respondent":"伊東税務課長","answer":"今年度の見込みのところで、２３億と書かせていただいていますが、３０年中の部分で、今年、税賦課計算をした中で、２３億円ほどが控除という形で流出しているという状況ですので、ほぼほぼこの数字は今年度の流出額と言えるところです。この表のとおり伸びております。","id":"exchange-013"},{"speaker":"須貝委員","kind":"質問","question":"本当にこのふるさと納税というのは、こういう税制度をつくっていいのかどうなのか。とんでもない制度だと私は思うので、実際、２０１８年は横浜市が流出したのが１３６億円、名古屋市が８０億円、大阪が７４億、近くの川崎市が５６億。世田谷区なんか５３億円です。静岡県の小山町は２５０億円。すごい額が入っている。それと区民に対して大変な負荷がかかってくるのだと思うのですが、これはどうなのですか。","respondent":"伊東税務課長","answer":"３割以下ですけれども、やはりそういうところでは３割以下のところまではちょっと上げていかなくてはなかなか体験型といっても難しいことになろうかと思いますので、基準の範囲内で、以前よりは少し単価的な部分は見直しをして。","id":"exchange-014"},{"speaker":"須貝委員","kind":"質問・要望","question":"何かで節税しなければいけない。それ以下というような状況です。そうしないと、これは２３区、皆さんおそらく困ってしまうと思うので何か。確かにご苦労されているのはわかるのですが、国のほうにも申し上げるとか、やはりきちんと意見を言っていただくということは大事だと思うので、何とかそっちの対策、何かいい方法がありましたら、私は２３区で区長会でも副区長会でも考えていただきたいと思います。","respondent":"桑村副区長","answer":"それに寄附されたらプレートをつけするとかいうことをやっているわけですが、そういう事業の支援あるいは区が特別に狙っているような仕事、これからですと環境未来館みたいなものがありますけれども。","id":"exchange-015"},{"speaker":"西本委員","kind":"質問","question":"幾つか質問なのですけれども、２９年度から３０年度は非常に品川区へのふるさと納税額が大きくプラスされているのです。これは何か。なぜ多くなったのかなというのを１つお聞きしたいと思います。","respondent":"伊東税務課長","answer":"３０年度大きく伸びているところの理由としては、３０年度は品川区水辺千本桜計画があったというのと、あと我々のほうでシナモロールのぬいぐるみをつくって、それがファンに受け入れられたというところで、伸びているところです。","id":"exchange-016"},{"speaker":"西本委員","kind":"質問","question":"そうすると実際、今年の見込みが２３億円となっているけれども、関連という形になると、これ以上ということですよね。それでいうとどうなるのですか。どういう計算になっているのでしょうか。そうなった場合、億にはならないと思いますが、そこら辺の絡み、それも含めるともうちょっと高く流出額というか経費も含めるともうちょっと影響の金額は多くなるのかなと思うのですが、いかがですか。","respondent":"伊東税務課長","answer":"返礼品との関係でいいますと、返礼品は今、品川区に寄附をいただければ、先ほど言ったシナモロールのぬいぐるみですとか、千本桜でいえばプレートとかというその経費については歳出のほうで組んでいるのですけれども、それはもう総務省から言われているとおり。","id":"exchange-017"},{"speaker":"西本委員","kind":"意見","question":"寄附が多ければそれだけ出ていくものも多いという感覚はあるので、寄附額の多い順といっても、実際はどうなのかなというのが少し疑問にありました。でも、ではこれをどうするかといったときには、やはり今後は担当をかえないといけないのではないかなと思うのです。文化観光？だから返礼品ではなくて本来のふるさと納税という考え方からいうと、やはり事業支援をしてほしいという思いがあるわけです。という。","respondent":"榎本総務部長","answer":"ただし、事業支援ということは各事業が、各部がそれぞれ自分のところでそれを活用してどんなことができるかというのは、今もう全庁の職員はわかっていますので、こういういろいろなメニューを考えるのは各部で検討していますので。","id":"exchange-018"},{"speaker":"西本委員","kind":"質問・要望","question":"いろいろな意味でシティプロモーションも含めて考えると、もうちょっと中心になる部署が事業支援という言い方をしましたが、事業レベルでのという形で、どういう結果だったのかとかという分析とかいろいろ出てくると思うのですけれども、その全部のまとめ役として税務課というのはちょっとしんどいだろうなと私は思うので、それは今後、検討していただきたいなと思っています。意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"大倉委員","kind":"質問・要望","question":"で、令和になると６万円を超えていくというところでは、人口も増えていくし、このまま１件当たりの額も増えていくとなると、かなりの流出額になって、それこそさっき言ったような何十億とまだ増えていくというところで、先ほど来いろいろお話ありますが、流出については、どう今後抑制をしていくことができるのか、どういう取り組みが考えられるのか、その辺について少し見込みを含めて。","respondent":"伊東税務課長","answer":"抑制というところで、やはり根本的に、制度ができて、この制度のお得なところというのが全国的にすごい勢いでのＰＲをされている中では、やめて下さいという話というか、こちらからお願いというのもなかなか言葉として発することは難しいというか、できないところですので。","id":"exchange-020"},{"speaker":"大倉委員","kind":"質問・要望","question":"全国連携というところで、今、副区長からお話があったかと思うのですが、広域のガバメントクラウドファンディングをいろいろなところがやられているのかなと思うのですけれども、例えば区長会とか、そういったところで、では２３区で何かというのか、例えば城南４区とか５区で何かとか。","respondent":"伊東税務課長","answer":"もう１点、返礼品に関しては自区民に対しては返礼品を出してはいけないというのが、今回の改正で明確に示されてしまったところで、そもそも区民はそこに納税しているわけですからおかしいでしょうということがこの発想だとは思うのですけれども。","id":"exchange-021"},{"speaker":"大倉委員","kind":"質問","question":"例えばそういったものや水族館等の何か利用の仕方とか、品川区が今持っているある程度発信力と体験型という意味では体験できるのかなと思ったので、そういった持っているものを使ってのクラウドファンディングではないですけれども、ふるさと納税の何か考えとかがあれば教えてください。","respondent":"伊東税務課長","answer":"それをまさに今後、来年度に向けて、検討をしていき、ＰＲできれば寄附に結びつくかなというところです。","id":"exchange-022"},{"speaker":"つる副委員長","kind":"質問・要望","question":"今、品川区の現況ということで、この５カ年度の数字で、見込みも出していただいているのですが、例えば先ほどの長期基本計画の話ではないですが、人口が増えていって、品川区の住民税等の今、自然増という形と流出額の関係で見たときに、当然１円でも多く増える、１円でも流出を少なくしていくのが当然大事なことなのですけれども。","respondent":"品川財政課長","answer":"こういったところをどうしていくかは今後の課題となってくるとは思うのですけれども、少しでもとにかく流出を抑えるような主張をしていくのも大事なことですし、そこはやはり品川区単独ではなく、特別区一体となってやっていくことが大事でありますし。","id":"exchange-023"},{"speaker":"つる副委員長","kind":"質問","question":"だからそこのところの見え方というのですか。何かマイナスに捉えるのではなく、プラスに捉えていくという視点がどうしても大事なのでしょうけれども、やはり本来やろうと思っていた、３０年度での１６億５,０００万円で何ができたのかとか、そういう見せ方も区民の方に対しては、すごくアピールポイントになるのではないかと思うのです。ちょっと感想めいたことですけれども。","respondent":"伊東税務課長","answer":"所得税の控除、住民税の基本控除と、あと特例控除ということで、特例控除が追加されたことでふるさと納税という形になっているわけで、その控除された部分は、ご本人にとっては寄附金額の２,０００円を除く部分がほぼ控除されると。","id":"exchange-024"},{"speaker":"つる副委員長","kind":"質問・要望","question":"すみません。私も事前に細かく確認をしてから質問させていただければよかったのですけれども、要はふるさと納税されたことによって品川区の寄附という視点での税収が増になって、ただ減額することによって、翌年度の住民税の税収が減額になるわけではないですか。その辺のバランスがどの程度なのだろうなと思って。自分でもちょっと勉強して確認します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/203294?Template=document&Id=2154#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2019-01-01&TermEnd=2019-12-31"}],"sourceMeta":{"pages":0,"characters":35177,"voices":71}},{"id":"r01-20191205-14","meetingId":"r01-cm12","date":"2019年12月5日","dateIso":"2019-12-05","committee":"行財政改革特別委員会","time":"午前１０時００分～午前１１時４５分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を38件抜き出しています。","topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"」という感じを私は受けているのですが、改めて間接にではなく直接お伺いしておきたいのですけれども、庁舎を建て替えるという話は、区としてははっきりと決まったことを前提にこの行財政改革特別委員会で話し合っているのだと。要するに決まったことなのかということを、前提としてはっきり直接お伺いしておきたいのですけれども、お願いします。","respondent":"立木経理課長","answer":"今年度６月、それから８月の行財政改革特別委員会でもご説明させていただいたとおり、まずは建て替えが必要であろうというところで候補地を決めた上で詳細検討をして、最終的にはこれが決定するという形になろうかと思います。","id":"exchange-001"},{"speaker":"おくの委員","kind":"質問","question":"よくわからなかったのですが、建て替えは決まったということなのですか。決まっていないということなのですか。","respondent":"榎本総務部長","answer":"たしか８月の行財政改革特別委員会でご報告した中で一番今後の方向性のところで、Ｄ案を中心に検討を進めていくこととしたい、区有地とＪＲ東日本所有地との再編を前提としてＪＲ東日本と協議をする、協議ですので、協議が整わない限りは決定という形にはできませんので。","id":"exchange-002"},{"speaker":"おくの委員","kind":"質問","question":"決まっていないけれども協議は進めるのですか。それがまたよくわからないのですが。","respondent":"立木経理課長","answer":"８月の委員会で、４つの候補地の中でその再編を前提としたとしても、広町が一番望ましいのではないかというようなご議論をいただいている中で、それを進めるに当たって、ＪＲ東日本との再編についての協議が必要になります。","id":"exchange-003"},{"speaker":"おくの委員","kind":"質問","question":"庁舎建て替えについては決まっていないけれども、土地を交換する調整についてはＪＲと協議をするということは決まっているということなのですか。","respondent":"立木経理課長","answer":"庁舎のための土地再編ということではなく、あくまでも広町地区のということで聞いております。そうした中で協議が整えば、区も一定程度広い土地が使えるということで庁舎の候補地として挙げさせていただいたところです。","id":"exchange-004"},{"speaker":"おくの委員","kind":"質問","question":"もう一度整理しますと、庁舎の建て替えは決まっていないけれども、土地の再編は決まっているということなのですか。","respondent":"立木経理課長","answer":"これは、すみません、所管は建設委員会のほうになろうかと思いますが、広町地区で一定程度まちづくりが進んでいる中で、それぞれ土地を有効利用するとの観点から再編の協議を進めていると聞いてあります。","id":"exchange-005"},{"speaker":"おくの委員","kind":"質問","question":"ですから、土地の再編については決まっているということなのですね。","respondent":"榎本総務部長","answer":"それを今、再編について協議をしているということなので、協議の結果、再編はだめだと言われれば整わないです。","id":"exchange-006"},{"speaker":"おくの委員","kind":"質問","question":"庁舎について言えば、私の考えとしては、まさに庁舎の建て替えをするか、しないかについて言えば、まさにきょう話し合うような機能検討ということが先に来るのではないかというのが私の発想ではあるのですけれども、ですから、まさにきょう話し合うような話を、それこそ区民の皆さんとともに話して、これを十分に煮詰めてから話し合うべきではなかったのかと私は思っておりますけれども。","respondent":"立木経理課長","answer":"まさに委員がおっしゃったとおり、これから機能検討を進めていくに当たりましては、もちろんたたき台をつくるために庁内検討を行います。","id":"exchange-007"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"ぜひ、再編する土地の交渉を進めていっていただきたいということを第一に要望します。それから、この「求められる庁舎機能」ということもここで４点出ていますけれども、これでお聞きします。きょうの質疑の中で、これに対してまた追加で要望する形の進め方なのか、その辺はどう進めるのかわからなかったので、それは後で教えてください。","respondent":"立木経理課長、大倉委員長","answer":"こちらの庁舎機能検討委員会ですけれども、こちらも２０人程度の中に、例示といたしましては、議会というところでは表示はされておりませんが、何かしらのご議論をいただく場といいますか。つまり、それに当たって今後の新庁舎機能をどのようにしていくかということで区から提出されたこの資料に沿って、こういったことを区のほうで考えているので、それに対してのさまざまなご意見をいただければと考えています。","id":"exchange-008"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"検討委員会のほうはわかりました。今も行財政改革特別委員会でやっていますけれども、行財政改革特別委員会でやっていくのか、この検討委員会の中に議員が入ってくるのか。議長に相談になると思うので、その辺について調整していただきたいと思います。この庁舎に何を求めるかは、きょうの段階ではないですね。そこだけ確認して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"須貝委員","kind":"質問","question":"ＪＲも話に乗ってくる。実際、区としてもそんなにたたき台がないわけですから、たたき台をしっかりつくっていただいて、それをまた議会にきちんと説明して、今の段階ではこうだという説明が後日きちんとあると思いますので、それでやっていくしかないかと。あくまで交渉ですから、交渉が先に進まない限りは進みようがないのが本来の状況だと私は思います。意見だけ言わせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"安藤委員","kind":"質問・要望","question":"議論に入る前に、いわゆる前回示されたＤ案、つまり再編まではそのような議論もあるでしょう。ただ、再編した土地の８,３００m2のみを区役所に充てる。資料に基づいて幾つかお伺いしたいと思います。１番のところですけれども、町会・自治会の１３団体、区関連団体とは、具体的にどこなのか教えていただきたいと思います。そこははっきりと教えていただきたいと思います。","respondent":"立木経理課長","answer":"こちらの資料１の１、「関係団体への説明」の中でも団体数が入っておりますが、これは大くくりの団体数になっておりまして、町会・自治会は各地域センターで所管しております品川区町会自治会連合会の会合にお邪魔しているということになりますので。","id":"exchange-011","title":"町会・自治会支援"},{"speaker":"安藤委員","kind":"質問・要望","question":"それぞれの自治体の事例について、主に何を研究して学んでいくという考えなのか伺いたいと思います。徹底した情報公開と住民参加で進めている世田谷区の事例を研究対象とすべきだと思うのですが、なぜここに名前が挙がっていないのか理由を伺いたいと思います。規模によっては、スポーツ施設は足りないわけですから、区民が利用しやすい施設になるかもしれません。先ほどの質問について伺います。","respondent":"立木経理課長","answer":"それぞれどういった形の研究をしていくかに関しましては、進め方の部分ですとか、検討内容とか、機能の部分、それからあとは財政の面とか、そういった部分に関しまして、既にやられたところはそれなりのノウハウが積み重なっているので、今現在進行中のところに関しましては。","id":"exchange-012"},{"speaker":"安藤委員","kind":"質問・要望","question":"財政のところという話がありました。前回でしたか、この議論をしたときにも豊島区の事例、視察した感想を述べさせていただきましたが、品川区の場合は、財政はかなり豊かではないですか。４番目の委員会ですけれども、これは公開でしょうか。いかがでしょうか。２０人程度と全体が既に決まっていますけれども、何人ぐらいの公募区民の方を想定しているのか、今現在のお考えがあれば伺いたいと思います。","respondent":"立木経理課長","answer":"内訳等につきましては、これからバランス等を考えながらということになろうかと思いますが、区内団体の想定に関しましては、先ほどご説明させていただいた、説明に回らせていただいている団体から代表者を出していただいたり、公募区民の方に関しましては。","id":"exchange-013"},{"speaker":"安藤委員","kind":"質問・要望","question":"ぜひ公開のところ、傍聴や議事録のホームページ公開を必ずやっていただきたいと考えています。要望です。ぜひご検討いただきたいと思いますけれども、いかがでしょうか。２０２１年度で基本構想となっていましたけれども、基本構想策定に当たっても、このような区民参加の検討、組織を立ち上げる考えはあるのでしょうか伺いたいと思います。","respondent":"立木経理課長","answer":"基本構想に関しましては、とりあえず来年度に関しましては「庁舎機能検討委員会」という形をとらせていただいて、その後は「基本構想基本計画」という形になろうかと思いますので、そういったことに関しましても、そのまま引き継ぐのか。","id":"exchange-014"},{"speaker":"安藤委員","kind":"質問・要望","question":"最後、Ｄ案の中身についてもう少し伺いたかったのですけれども、Ｄ案は先ほど言ったように、区庁舎にくっつけた土地の一部８,３００m2を新庁舎の敷地に充てるという案だと理解しております。ある程度想定していると思いますので、伺いたいというのが１点です。区としては延床面積、現在の４万３,１０１m2を超えておよそどれぐらいを確保したいと今考えているのかを伺いたい。","respondent":"立木経理課長","answer":"土地の再編につきましては都市開発課で進めておりまして、所管は建設委員会となりますので、私からは詳細はお答えはできないですが、きちっとＪＲとの協議を詰めているということは聞いているところです。","id":"exchange-015"},{"speaker":"安藤委員","kind":"質問・要望","question":"最初の答弁ですけれども、お答えできないというのは知らないということなのですか。大体どれぐらいの土地と交換するのかを経理課長は知らないという状況なのですか。それと、伺ったのは、現在は延床面積は４万３,１０１m2で、それを超える広さを確保すべきと考えていらっしゃるということですから、では大体何平米ぐらいを確保することを目標にされているのかを伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"安藤委員","kind":"質問","question":"そうだと思うのです。６万m2から７万m2ぐらいは確かに必要になってくるのではないかと思うのですが、それはあくまで希望ということなのですね。ですから、必要な機能や基本構想の策定をしていない中で敷地面積を確定するこのＤ案は順序があべこべだし間違いだと共産党は言っているわけです。Ｄ案は白紙にして、情報公開と住民参加で進めるべきだと思いますけれども、これはいかがでしょうか。","respondent":"立木経理課長","answer":"進め方につきましては、今後、公募区民等も入れました委員会等も立ち上げる予定ですので、そうした中できちっとやっていきたいと考えているところです。","id":"exchange-017"},{"speaker":"安藤委員","kind":"質問","question":"ですから、再編自体を、協議をやめろと言っているわけではないのです。では庁舎はどうあるべきかという議論が全く密室で行われて、区民の参加なしに進んできて、庁舎分はこれくらいですということを先に決めている。一般質問では、私たちはこれまで進んでこなかった大井プレイス構想が動き出したきっかけとなったのは区役所建て替え計画なのですかと質問させていただきました。意見を述べします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"あくつ委員","kind":"質問・要望","question":"２番のところが「求められる庁舎機能」ということで、いわゆる防災であるとか環境というところで、今、ほかのここにある２区のほかに７区が庁舎の建て替えを検討されているというところで、基礎自治体が持つ区庁舎にどのようなものがこれから求められていくのかという、トレンドという言い方が適切かどうかはわからないですけれども、一般的な今の流れ、ワンストップであるとかというものが書いてあって。","respondent":"立木経理課長","answer":"こちらの「庁内検討」のほうに５つほど挙げさせていただいた後半に、左側の「求められる庁舎機能」の中で大きく防災機能と環境という部分で出しています。","id":"exchange-019"},{"speaker":"あくつ委員","kind":"質問・要望","question":"今のところということですから、ぜひ我々としては防災、それとこれからはどんどん災害がふえてくる。残念ながら減りはしないと思うのです。は責任をどこが持つのかというところで、当然、協議体ですから、全員でチームとなってやっていくということだとは思うのですけれども、そこの責任の所在を確認させていただきました。","respondent":"立木経理課長","answer":"検討委員会、それから基本構想それぞれに関しましても、きちっと情報提供をさせていただいた中で意見を取り入れるという形ではいろいろな手法があるかと思いますので、そこら辺はパブリックコメント等も含めましてやらせていただきたいと思います。","id":"exchange-020"},{"speaker":"あくつ委員","kind":"質問・要望","question":"そこは注目される。そうですよね」で終わらせるのではなく、それを区民がこれはＳＤＧＳと連動してしっかり世界の一員としての品川区が進めているのだということがわかる形でこの建て替えも進めていただきたい、環境にも配慮していただきたい、また、防災のこともやっていただきたいという思いで申し上げました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"須貝委員","kind":"質問・要望","question":"さらに加えて、アンテナ等の通信機能を増強することはこれから求められる時代ではないかと思います。今、品川区役所の１階にはダンパーを設置してありますけれども、あのような完全に取り換えにくいようなことはやめるべきで、長く区役所が１００年以上もつような庁舎をつくっていただきたいということで、庁舎機能検討ということですから、意見として言わせていただきます。質問はありません。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"大沢委員","kind":"質問","question":"経理課長にお尋ねしたい。この資料をつくるのにどれぐらいの役所の担当の方たちが目を通されて推敲なりチェックされているのか教えてください。","respondent":"立木経理課長","answer":"こちらの資料に関しましては、所管は経理課になりますが、そちらでたたき台をつくりまして、その後、上層部までこの内容で議会に諮らせていただきたいというところで、そういった区の組織体の中でやらせていただいているところです。","id":"exchange-023"},{"speaker":"大沢委員","kind":"質問","question":"先ほどあくつ委員から２番と３番の兼ね合いというところで、３番のところ、具体的にこの５項目を出していただいて、説明の中でほかにもありますというのですけれども、委員会資料として今後、議事録等々載っていくわけでありまして、ここのところは説明を受けて初めてわかることでありまして、このような表現の方法をしてしまうと。","respondent":"立木経理課長","answer":"端的に少し箇条書きに資料はつくらせていただいておりますので、そこら辺は関係各位にはきちっと説明できるものを今後も用意する形で進めていきたいと考えております。","id":"exchange-024"},{"speaker":"大沢委員","kind":"質問","question":"ここの表現ではないのですけれども、ワンストップ窓口機能、５項目ありまして、そこの横に「届出・証明系」と、事細かに具体的に書いてあるのですけれども、このほかにもこの窓口の機能、５つの機能がありますけれども、ほかにも、今はまだ検討段階なので、出る場合もなきにしもあらずと思いますので、ここのところ、２と３の「など」という言葉もありますけれども。","respondent":"立木経理課長","answer":"今回、資料をつくるに当たりましては、ここに全部例示し切れない、細かく出過ぎるという部分もございまして、このような形で「など」という表現にまとめさせていただいたので、誤解を受けないように。","id":"exchange-025"},{"speaker":"大沢委員","kind":"質問・要望","question":"新しい品川区の庁舎像というものは非常に重要な、大事な課題、議題でありまして、そこの入り口になるだけに、前回のＤ案とかＡ案とかありましたけれども、デリケートな問題なので、表現をしっかりと注意しながら取り扱っていただきたいと思います。意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"せお委員","kind":"確認","question":"１点、確認なのですけれども、庁舎機能検討委員会ですけれども、庁舎機能を区民の方々と一緒に議論する場は、この庁舎機能検討委員会だけということになりますでしょうか。","respondent":"立木経理課長","answer":"委員おっしゃるとおり、こちらの庁舎機能検討委員会の中でご意見、議論なりをしたいと考えております。こちらだけというところで今のところは考えております。","id":"exchange-027"},{"speaker":"せお委員","kind":"質問・要望","question":"議論する場はどこかと思ったのですけれども、いろいろなところで私は言っているのですけれども、このような庁舎機能検討委員会、区民の方が参加する委員会というのは、なるべくならさまざまな立場とか状況の方からさまざまなニーズが伺える、そのような場にしていただきたい。なので、そのような方々が利用する施設なども併設していただけたらと、ここでは要望で終わらせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"それを説明していただきたいと私は思っているのですけれども、そのようなことをする段階もあるのだとは思うのです。それはどの辺になるのか、区としてはどう考えているかお伺いします。","respondent":"立木経理課長","answer":"今後、細かい部分が検討材料として出てきたときには、その都度きちっとこれまで説明してきた団体の皆さんを通してだったりとか、もしくはまた検討委員会等、それから基本構想の検討に当たりましては。","id":"exchange-029"},{"speaker":"石田（ち）委員","kind":"提案","question":"２点目に、このＤ案です。しかし、これがどのような議論を経て承認されたのか、「Ｄ案で進めるものとする」という指示が出たのかが、それまでの経緯、議論が全く書かれていないので、経営会議でなぜＤ案と決めたのか、その根拠を伺いたいのと、そもそも提案されたＤ案は誰によって提案されて、どのような人たちで決まっていったのか、どのような議論があったのかを、それぞれご説明いただきたいと思います。","respondent":"立木経理課長","answer":"１つ目の「関係団体への説明」に関しましては、品川区町会自治会連合会にもご説明した際や、あと品川区高齢者クラブ連合会等、大分大人数のところで会長等にも説明させていただいたりしている中では、このお話に関しては一切秘密ということではなく。","id":"exchange-030"},{"speaker":"石田（ち）委員","kind":"提案","question":"住民への説明のところでは、オープンな形でと、それは当然だと思うのですけれども、それをさらに広くやってくださいということで、それは内緒にしてくださいなどというのは当然ないわけですから、そうした町会長や自治会長の皆さんは皆さんなりに広げていくでしょうけれども、そこだけでは広がらない部分が往々にしてあるわけですから、そこはぜひ早い段階での説明会をしていただきたいと思います。","respondent":"榎本総務部長","answer":"平成３０年度の行財政改革特別委員会の中では、ある程度、新庁舎整備の検討も行わなければいけないという部分も議論されてきましたし、この行財政改革特別委員会のまとめに関しては、議長から正式に区長のほうにこのような形でまとまりましたということで出てきていますので。","id":"exchange-031","title":"町会・自治会支援"},{"speaker":"こんの委員","kind":"質問・要望","question":"おおむね賛同の状況だったというところで、私も連合町会の方々とか地域の方々とか、これだけ説明をしてくださっているので町でも声を聞くようになってまいりまして、庁舎を何とか将来に向けて、災害もいつ起きるかわからない状況の中なので、こうした考え方はいいという声だとか、あるいは土地の再編についても。","respondent":"立木経理課長","answer":"区関連団体に関しましては、例えば社会福祉協議会であったり、あとは品川区高齢者クラブ連合会、それから東京商工会議所、品川区障害者７団体協議会、民生委員協議会、品川区商店街連合会、品川産業協会等々に説明をさせていただいているところです。","id":"exchange-032"},{"speaker":"こんの委員","kind":"質問・要望","question":"これからもこうした個別の説明会が、ある意味、必要かと思っているところですが、今後の予定はどのように説明をされていくのか、そこら辺をひとつ教えていただきたいと思います。私は、このワンストップ窓口という分野でここをくくる考え方もいいのですが、子育ての部分を取り出して、そうした利便性向上の庁舎機能も考えられるのではないかと思いますが、その点はいかがでしょうか。","respondent":"立木経理課長","answer":"はこの「福祉系」の中には、例えば子どもの関連ですとか、そういったことも検討を進めていく中で、これは独立してやったほうがいいのではないかということも出てくるのではないかと考えておりますので、そういったところを柔軟にいろいろ組み替えたり。","id":"exchange-033"},{"speaker":"こんの委員","kind":"提案","question":"庁内の検討はわかりました。子どもの分野でなぜこれを取り出してと申し上げたのかというと、どうしてもワンストップは、例えば庁舎の利便性から考えると、１階に何でも置きたいというか、上下の移動がないように区民の方の動線を確保した窓口としては、子育てというところも考えられるとなると、ここは子育ての方々は赤ちゃんやお子さんを連れて来ますので、結構スペースが必要なのです。意見で終わります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-034"},{"speaker":"おくの委員","kind":"意見","question":"今のこんの委員やあくつ委員、あるいはせお委員のお話に少し触発されて、今の５つの機能なのですけれども、これは何で５つの機能なのかが、この資料を読んだだけではよくわからなかったので、私が日ごろから気になっていることで言えば、「福祉機能」を取り出してもいいのではないかとぱっと思いついていたもので、そうすると、今のこんの委員とのやりとりをされた中で。","respondent":"立木経理課長","answer":"これ以外のところもこれで固定ということではないと考えていますので、その都度必要なものに関しましては、きちっと検討を進めていくという形で、何かしらチームなり作業部会なりという形をつくっていくことになろうかと考えています。","id":"exchange-035"},{"speaker":"おくの委員","kind":"質問","question":"施設の併設、障害者施設とか、特別養護老人ホーム施設とか、あるいは保育所、そのようなことも思い浮かびます。そのようなことを「福祉機能」ということで言えば、「福祉機能」がもしここに一つの機能としてピックアップされるとすれば、そのようなことも私などは思い浮かべたりするのですが、そのようなこともあり得ると考えておいていいのでしょうか。","respondent":"立木経理課長","answer":"これから検討分野をスタートしますので、そういった中で、まずは庁内検討の中での議論になろうかと思っています。そういった中で、必要性はきちっと精査をさせていただいてというところになると思っているところです。","id":"exchange-036"},{"speaker":"おくの委員","kind":"質問・要望","question":"それからもう一つ、２番目の「求められる庁舎機能」の中の（２）、「防災拠点機能を強化した庁舎」というところなのですけれども、これ、１番目に「災害対策本部として」「防災拠点として」ということが書いてあって、３番目に「災害時の区民受け入れを考慮した建物」と書いてあるのですけれども、具体的には結局、災害対策本部として機能することを中心に考えられておられるのでしょうか。","respondent":"立木経理課長","answer":"昨今の災害の状況を見ますと、庁舎に避難されてくる方は大分いらっしゃるというところでは、多分、委員会でも視察にいっていただいているところでも、そういった設計をされている庁舎があるという話も聞いている中では、一定程度こういったことも、今後。","id":"exchange-037"},{"speaker":"おくの委員","kind":"質問・要望","question":"ですから、そのような空間、スペース、あるいはそのときに必要になるいろいろな設備や食料など、それを考慮した建物ということは十分に考えていただきたいということをまた要望として申し上げておきたいと思います。それから、すみません、もう一点。それからもう一点、公開。会議は公開にしていただきたいし、議事録もきちっと公開していただきたいという、私の要望として申し上げておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/145510?Template=document&Id=6080#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2019-01-01&TermEnd=2019-12-31"}],"sourceMeta":{"pages":0,"characters":29904,"voices":79}},{"id":"r01-20191206-18","meetingId":"r01-cm12","date":"2019年12月6日","dateIso":"2019-12-06","committee":"オリンピック・パラリンピック推進特別委員会","time":"午前１０時００分～午後 ２時０９分","status":"正式会議録","sourceType":"formal","overview":"オリンピック・パラリンピック推進特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を25件抜き出しています。","topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"つる委員","kind":"確認","question":"別の段でああいう区の管理できるところに、品川区の非核平和都市品川宣言のプレートとか、あとはカンナの花とか、そのような質疑もかつてさせていただいたこともあったのですけれども、区で管理できるところで何かしらの、子どもたちがおもてなしだとか、ウェルカムの気持ちを表示できるようなものが、そもそもできるのかどうかという、まずその確認をさせてください。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"区が管理する競技会場周辺の土地でのおもてなしの仕方等のご質問です。何回もご説明申し上げているラストマイルから競技場の入り口までは、東京都がラストマイルということで全体の管理をしている、競技会場の中は組織委員会でやっているという区分けになっております。","id":"exchange-001"},{"speaker":"つる委員","kind":"質問・要望","question":"わかりました。今後いろいろな協議等、確認が必要かもしれませんけれども、当然、各園児、園の対応も大変なことが出てくるかとは思うのですが、そうしたことも全て含めて、子どもたちの心に残るような機会をぜひつくっていただきたいと思いますので、よろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"本多委員","kind":"質問・要望","question":"オリンピック・パラリンピック競技に関しましては、小学生、中学生、全児童、全生徒が、オリンピックに携わる、パラリンピックに携わるという意見をずっと出しているのですけれども、これは観戦もそうですが、観戦以外でも応援するとか、全児童・全生徒がという要望などもさせていただいてきておりますけれども、その中で、今の答弁とかやりとりで、組織委員会とのやりとりや東京都とのやりとりで。","respondent":"工藤指導課長","answer":"大会の実施年におきまして、委員ご指摘のとおり、競技観戦ということは５歳児以上、全児童・生徒ということで行っていくところですけれども、私どもの取り組みの中でいえば、これまでも例えばコロンビアの代表選手が事前キャンプに来た際には学校での交流をするというところで。","id":"exchange-003"},{"speaker":"新妻委員","kind":"質問・要望","question":"先ほど視察をさせていただいた中で、園長先生から、八潮わかば幼稚園の観戦競技がホッケーと決まったというお話があったのですが、そのほか、今どういう状況にあるのかというのをお知らせいただきたいのですが、観戦競技が決まって、最終決定がいつになるのかとか、子どもたちの観戦機会の創出というところでの流れをお聞きしたいと思います。","respondent":"工藤指導課長","answer":"本日の視察先で説明がありましたように、基本的に、幼稚園や低学年は屋内競技を中心とする、また暑さのことからパラリンピック競技を中心とするという案内があったところなのですが、先ほどの園長からもありましたように、近くにあるのに。","id":"exchange-004"},{"speaker":"新妻委員","kind":"確認","question":"まだ決定はされていないということで、確認をさせていただきました。引率者、会場に入れる人が、プラスアルファで多く行くという配券がされるということですが、これは安全面も含めて、そういう引率者を多くさせてもらえるという考え方でいいのでしょうか。","respondent":"工藤指導課長","answer":"私どもでいえば、会場の中は入れなくても、交通機関で移動するところに支援する方をつけるというところでの考えはありますので、会場内に入れないというところはチケット配券によりますので、そういったところでも支援はしていきたいと考えています。","id":"exchange-005"},{"speaker":"つる委員","kind":"質問","question":"再度、今の質問に関連してなのですが、何の機会かは忘れてしまったのですけれども、聞いたのですが、しな助の方々の活躍の場というところで、特に幼稚園・保育園の園の体制のこともあるので、なかなか引率が大変だというところもそれぞれの現場では聞く中で、しな助の方たちに引率のサポート、要するに会場内に入れれば一番いいのだけれども。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"ふだんからお子様の相手をしているといっても、初対面の方が急に来てというのは、なかなか難しいかなというところですので、現時点では学校なり、幼稚園や保育園で考えていただきたいと思っているところです。","id":"exchange-006"},{"speaker":"つる委員","kind":"質問","question":"そうしたときに、お金はあったけれども人がいないとなったときに、今ご答弁もありました、ふだんから子どもたちの対応ができている方でないと、なかなか難しいという部分もあるかと思うのですが、当然そうすると、そういう人員の確保というのは、公立園については別なのかもしれませんが、私立園もそれぞれ園で頑張ってくださいとなるのか、それとも何らかの形で東京都ないし品川区としても、人材の確保。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"そのあたりは、今の時点でどうするというのはなかなか決めづらいところもありますので、様子を見ながら検討して、教育委員会とも話し合いをしながら決めていきたいと考えています。","id":"exchange-007"},{"speaker":"つる委員","kind":"確認","question":"東京都のいろいろな会議録とかを確認すると、一応そうした各区市町村に対する人材の確保に必要な予算だとか、人員についてどうするかというところまでは言及がなかったのですけれども、ただ、そういうものがつくられたときに、せっかくそれが用意されてメニューがあるけれども、活用できなかったとならないような、現場の自治体としての対応の考え方の検討は、ぜひ積極的に積み上げていっていただいて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"のだて委員","kind":"質問・要望","question":"日本の伝統文化を学んでいくということは、とても大切だと思いますし、それとあわせて、オリンピック・パラリンピックですから、他国の文化を学ぶことによって、グローバル社会とも言われていますけれども、そういった多様性、さまざまな文化があることを学んでいくということが大切だと思いますので、１点、質問のところだけお願いいたします。","respondent":"工藤指導課長","answer":"つまり、いろいろな形、いろいろな飾りがあっていいというのが、他を理解する、いわゆる多様性の観点にもつながっていくと考えておりますので、そういったところを大事にしながら進めていくのが、このオリンピック・パラリンピック教育の中でも大事な観点だと考えていますので。","id":"exchange-009"},{"speaker":"のだて委員","kind":"質問・要望","question":"オリパラ教育の中で、今回私は改めて感じたところだったのですけれども、環境部門というところもオリパラ教育の中に入っていたかと思うのですが、品川で行われている環境部門での取り組みですとか、それは全校でやられているのか、そこを伺いたいのと、今回オリパラに当たって、パラリンピックということで、これを契機にインクルーシブ教育の推進というのも、ぜひ進めていっていただきたいと思うのですが。","respondent":"工藤指導課長","answer":"そういった意味では、インクルーシブ教育の取り組みということがございましたけれども、先ほどの多様性も含めながら、実際に子どもたちはさまざまな教育活動の中で、お互いを認め合いながら一緒に成長していく、学んでいくという姿勢でいくというのは大事にしておりますので。","id":"exchange-010"},{"speaker":"のだて委員","kind":"質問・要望","question":"インクルーシブ教育のところも、いろいろなところにかかわって多様性を認め合いながらということでしたけれども、今回の大会を契機に、品川でのインクルーシブ教育が進んだと言われるような形で、ぜひ取り組んでいっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"小芝委員","kind":"質問","question":"そういう意味で、さっきの見学で資料が配られましたが、しめ縄作りのワークショップの中で、「古事記」の天の岩屋戸を教えているそうなのですが、幼稚園の先生がこういったことを幼稚園児に教えているのでしょうけれども、ふだんの日常で園児と接する中で、こういったことも自分で吸収しているからこそ、園児に教えることができると思うのですが、区立の幼稚園の先生がこういった「古事記」とかを学ぶ環境は。","respondent":"工藤指導課長","answer":"そういった方で、また横のつながりになって、本日の講師の方をお呼びするとか、そういった方のお話を聞く機会というのが、私どもの研修の機会の中でも設定できるように検討してまいりますけれども、各園独自でも校内研修というのを行ってありますので。","id":"exchange-012"},{"speaker":"松澤委員","kind":"質問","question":"視察、ありがとうございました。ただ、僕も小さいとき、あまり落ちつきがないのもあったのですけれども、行って飽きてしまうかなと思うと、では子どもは何が好きかなと思ったら、３キャラクター、シナカモン、ビーチュウ、やたたまのようなキャラクターが、幼稚園の子どもたちと一緒に遊べる特別なイベントのようなものがあると、とてもいいかなと思うのですけれども、いかがでしょうか。","respondent":"工藤指導課長、辻オリンピック・パラリンピック準備課長","answer":"そういった意味では、この取り組みを各９園には、実践事例集をお渡しする中では共有している、また私どものオリンピック・パラリンピック教育に関する伝達のところでは、もちろん伝えていくのですけれども、例えば講師の方が。これからも私どもの行う機運醸成のイベント、それからスポーツ推進課が行う子ども向けのスポーツイベント等に出る予定もありますし、あと、地域で何か催しがあるときに、出演予定がなければ周りだけ。","id":"exchange-013"},{"speaker":"西村委員","kind":"質問","question":"今日は視察、ありがとうございました。２点だけお伺いをさせてください。２点目が、特別支援学校などにおいては、パラリンピックの教育の推進ですとか、学校運営計画に位置づけられているのかどうかというのをお伺いさせてください。","respondent":"工藤指導課長","answer":"学校によるのですけれども、５つ全ての資質を観点に置きながら、そのうち重点を２つのような学校もありますし、中には３つ重点を選んでそれを行う、それは学校独自に取り組むところなのですが、ただ、そうはいっても先ほど申し上げたように。","id":"exchange-014"},{"speaker":"西村委員","kind":"意見","question":"一生に一度あるかどうかという、日本で行われるオリンピック・パラリンピックですので、ぜひ障害を持ったお子さんたちに、特にパラリンピックを見る機会とか体験する機会があるといいなと思いますので、引き続きお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-015"},{"speaker":"吉田委員","kind":"質問","question":"先ほどから出ている、ほかの国のいろいろな文化への尊重とかということも大事な教育の一つだと思うのですけれども、配慮として提供されるだけではなくて、一緒に食べた子どもたちも、なぜこういうことが必要で、この方たちがどういうことを尊重して、このように戒律を守っておられるとか、そういう教育があわせてされたのか、ぜひそうであってほしいという趣旨の質問なのですけれども。","respondent":"工藤指導課長","answer":"そういった取り組みの中では、給食を共にしながら、お互いの国を知るという観点でいえば、このときにどんな指導をしたかというのは、今は把握していないのですけれども、そういった前後の指導というのは大事な部分ですので、行っていくところですし。","id":"exchange-016"},{"speaker":"吉田委員","kind":"質問・要望","question":"もちろん、一緒に給食が食べられるという意味で、いらした方への配慮としてのハラルミールの用意というのは、それだけでもすごいと思うのですけれども、なぜそういうことが必要なのかということ、せっかくの機会ですので、もし今後もこういうことがあれば、ぜひその前後の教育のほうも丁寧にやっていただきたいと思います。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"吉田委員","kind":"質問","question":"このチラシをつくられたのは、どこなのでしょうか。なぜそれを聞くかというと、いつも大抵、特にパラリンピック関係のものには、読み取りコード、ＳＰコードと、それから印が、切り込みが入っているかと思うのですが、これにないのは何か意図があるのでしょうか。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"全体のチラシをつくるときには、通常どおりにＳＰコードを入れたりなどをしますので、そこのところはご容赦いただきたいと思います。","id":"exchange-018"},{"speaker":"吉田委員","kind":"質問・要望","question":"そういうことでしたら、わかりました。ただ、そもそもこういうチラシが出ているということがなかなかわかりにくい方たちですので、積極的にこういうチラシがありますという広報をぜひ心がけていただきたいと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"筒井委員","kind":"質問","question":"ＬＩＮＥスタンプの販売についてお伺いしたいのですけれども、幅広い方、特に若い方とかへのオリンピック・パラリンピックの啓発、機運醸成には、非常に役立つものかと考えています。費用は大体お幾らぐらいかかったのでしょうか。同じこのキャラクターのデザイナーが、ある程度お描きになったかと思うのですけれども、どのぐらい費用がかかったのかをお知らせください。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"今回のＬＩＮＥスタンプの販売に関しましては、もともと私どもの持っている３キャラのポーズをもとに、職員が申請をしてやっておりますので、特段、費用というのはかかっておりません。","id":"exchange-020"},{"speaker":"筒井委員","kind":"質問","question":"この絵は、新しく描いたのではないということですか。それもあまり費用がかかっていないという意味でよろしいのでしょうか。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"３キャラのポーズといいますか、顔だちとかは、幾つも在庫を持っておりまして、その中からＬＩＮＥのスタンプに適当なものとフレーズを組み合わせて、今回はつくっております。","id":"exchange-021"},{"speaker":"筒井委員","kind":"質問","question":"すばらしい工夫、在庫活用ということで、すばらしい取り組みだと考えています。これをぜひ多くの区民の方、もちろん区外の方も使ってほしいのですけれども、このＬＩＮＥスタンプの周知というのは、どのようにお考えなのでしょうか。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"これからの「Ｃｈａｌｌｅｎｇｅ ＆ Ｍｏｖｅ」ですとか、さまざまな機運醸成のイベントの際に、チラシとして、ＬＩＮＥスタンプを始めましたというのでまたつくって、入れる等の形でのお知らせをしたいと考えています。","id":"exchange-022"},{"speaker":"つる委員","kind":"提案","question":"ＬＩＮＥスタンプですが、これは昨年の８月の委員会で具体的に提案させていただきました。ですが、オリパラのＬＩＮＥ上にも、周知はこれからなのです。それから、価格がクリエイターズのほうで出されているので、１２０円ないし５０コインというところで、その収入というのは、区の予算とかそういうところでは、どういう名前での収入の位置づけになっていくのか教えてください。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"費用についてなのですが、一旦ＬＩＮＥのほうに収入が行ったうちの、幾つかのうちの少しだけペイバックがあるような形になっているということなのです。微々たるものなのかなという認識でおりまして、おそらく雑入ということで入るのではないかと考えています。","id":"exchange-023"},{"speaker":"つる委員","kind":"質問","question":"この委員会が妥当かどうか、あれですけれども、雑入で入ってくるのは何％ぐらいなのですか。どのぐらいの人が買ってくれたというのは、いろいろな形でわかる方法があるのでしょうけれども、そういうのもわかったりするのでしょうか。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"それともう一つが、どれぐらいの人が買っているかということで、それは人数がわかることで、それで何％という割合になりますので、そこでわかることになります。","id":"exchange-024"},{"speaker":"西村委員","kind":"質問","question":"「Ｃｈａｌｌｅｎｇｅ ＆ Ｍｏｖｅ」で１点だけお伺いさせてください。対象年齢を小学校４年生以上に定められた理由だけ教えてください。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"こちらは開催が夜だということで、遅くなるので小学生の高学年以上といいますか、４年生以上と今回はしています。","id":"exchange-025"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/110082?Template=document&Id=6566#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=18&TermStart=2019-01-01&TermEnd=2019-12-31"}],"sourceMeta":{"pages":0,"characters":20516,"voices":69}},{"id":"r01-20191211-10","meetingId":"r01-cm12","date":"2019年12月11日","dateIso":"2019-12-11","committee":"議会運営委員会","time":"午前１０時３０分～午前１０時５２分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を3件抜き出しています。","topics":[{"id":"topic-01","title":"ＩＣＴ推進会議からの報告事項","agenda":"ＩＣＴ推進会議からの報告事項","exchanges":[{"speaker":"大倉委員","kind":"確認","question":"１０月２１日にご説明しましたとおり、令和元年第４回定例会で試行的に、招集にかかわる通知をサイドブックス上へ掲載するとともに、あわせてメールによりその掲載連絡を行い、電子化を図りました。実施後、ＩＣＴ推進会議にて今回の方法について意見交換を行い、今後もこの方法で実施可能ではないかとの確認ができました。以上、ご検討のほどよろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"あくつ委員","kind":"確認","question":"確認なのですけれども、この招集通知については、申し合わせ確認事項とか、何か議会の取り決めというのはそもそもあるのでしょうか。","respondent":"米田区議会事務局長","answer":"通知するということの記載のみでして、どの媒体をもってということについては記載はありません。","id":"exchange-002"},{"speaker":"あくつ委員","kind":"確認","question":"わかりました。少し違う話ですが、政務活動費の方で私が担当者なのですけれども、実態にそぐわないような規定があって、それを早く修正したいのですが、それがゆえに事務作業が増えているところがあるので。そういう意味で、今、規定があるのかないのか確認して、特に問題はないと確認できましたので、結構です。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/268822?Template=document&Id=5340#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2019-01-01&TermEnd=2019-12-31"}],"sourceMeta":{"pages":0,"characters":7776,"voices":34}}]);
